window.LFS_DATA = {"fallacies":{"version":2,"none_id":"none","families":[{"id":"source","name":"Оценка по источнику","near":["evasion","pressure","heritage","structure"]},{"id":"evasion","name":"Подмена предмета спора","near":["source","rules","pressure","choice"]},{"id":"rules","name":"Подгонка правил и понятий","near":["evasion","language"]},{"id":"pressure","name":"Давление вместо доводов","near":["source","evasion","heritage","choice","sampling"]},{"id":"heritage","name":"Старое, новое, естественное","near":["pressure","source","choice","sampling"]},{"id":"cause","name":"Ложная причина","near":["sampling","structure","choice"]},{"id":"sampling","name":"Выборки и цифры","near":["cause","language","pressure","heritage","structure"]},{"id":"choice","name":"Искажённая картина вариантов","near":["pressure","structure","evasion","heritage","cause"]},{"id":"structure","name":"Сбой в структуре вывода","near":["cause","choice","language","source","sampling"]},{"id":"language","name":"Слова, части и сходства","near":["rules","sampling","structure"]}],"fallacies":[{"id":"ad_hominem","name":"Переход на личность","latin":"argumentum ad hominem","aliases":["аргумент к человеку","довод к личности"],"family":"source","definition":"Аргумент отвергают, нападая на того, кто его высказал (характер, возраст, мотивы), а не на сам аргумент.","cues":["что (его|ее|их) слушать","(вечно|всегда) со всеми","не застал","о каком понимании","выгоден лично","кто (ты|он|она) такой","безбилетник"],"counter":{"how":"Не отвечай встречной колкостью и не оправдывайся. Спокойно отложи вопрос о себе и верни разговор к доводу.","say":["Допустим, я зануда. Но предложение-то от этого хуже не стало — что именно с ним не так?"],"avoid":"«Это переход на личность!» — звучит как обвинение, и дальше спор пойдёт о том, кто кого обидел."}},{"id":"tu_quoque","name":"«Сам такой»","latin":"tu quoque","aliases":["«ты тоже»","вотэбаутизм"],"family":"source","definition":"Критику или совет отвергают, указывая, что критикующий сам поступает так же. Лицемерие советчика не делает его довод ложным. Частный случай перехода на личность.","cues":["(ты|вы) сам(а|и)?\\b","у них самих","не тебе (меня )?учить","на себя посмотри","а (ваши|твои) .*сами"],"parent":"ad_hominem","counter":{"how":"Признай несоответствие — это обезоруживает — и отдели совет от советчика.","say":["Да, я сам так делаю, и это глупо. Потому и говорю.","Пусть я лицемер — совет от этого не испортился."],"avoid":"Доказывать, что ты «не такой», — это уже спор о тебе, а не о деле."}},{"id":"genetic_fallacy","name":"Генетическая ошибка","latin":null,"aliases":["ошибка происхождения","оценка по источнику"],"family":"source","definition":"Идею, вещь или обычай оценивают по их происхождению, а не по нынешнему содержанию и последствиям.","cues":["(придумал|придумали|изобрел|изобрели) .*(значит|поэтому|так что)","(родом|пришл[аои]|происходит) из","кто (это )?придумал","(слово|обычай|праздник) .*изначально"],"counter":{"how":"Спроси, что не так с идеей сейчас, независимо от того, откуда она взялась.","say":["Хорошо, придумали это там-то. А работает оно или нет?"],"avoid":"Спорить о происхождении («да оно вовсе не оттуда!») — так ты соглашаешься, что происхождение что-то решает."}},{"id":"false_authority","name":"Ложный авторитет","latin":"argumentum ad verecundiam","aliases":["аргумент к авторитету","апелляция к неавторитетному мнению"],"family":"source","definition":"Тезис подкрепляют мнением человека, который не является экспертом в обсуждаемом вопросе, или статусом вместо доказательств.","cues":["сыграл","доктор .*наук","с такой степенью","знакомый работает","как человек, который","известный актер"],"counter":{"how":"Не нападай на сам авторитет — спроси, на чём основано его мнение, и предложи посмотреть, что говорят специалисты именно в этой области.","say":["Он отличный певец. А что про это говорят те, кто этим профессионально занимается?","А на что он сам ссылается?"],"avoid":"Высмеивать кумира собеседника — защищать будут кумира, а не тезис."}},{"id":"ignoratio_elenchi","name":"Подмена тезиса","latin":"ignoratio elenchi","aliases":["довод не по существу"],"family":"evasion","definition":"Вместо тезиса, о котором идёт речь, доказывают, опровергают или «исполняют» другой — похожий, но иной. Общая категория: её частные случаи — «соломенное чучело» (искажённый тезис опровергают) и «отвлекающий манёвр» (переходят к другой теме). Не путать с подменой понятий, где меняется смысл одного слова.","cues":["упрекнул меня,? что","(имел|имела) в виду","то есть (он|она) недовол"],"counter":{"how":"Мягко напомни исходный тезис и спроси, как сказанное с ним связано.","say":["Подожди, мы начали с того, что… Как это доказывает именно это?"],"avoid":"Увлечься новым тезисом и начать опровергать уже его."}},{"id":"straw_man","name":"Соломенное чучело","latin":null,"aliases":["искажение позиции оппонента"],"family":"evasion","definition":"Позицию оппонента искажают — утрируют, упрощают, доводят до крайности — и опровергают уже искажённую версию. Частный случай подмены тезиса.","cues":["то есть (ты|вы) (хочешь|хотите|считаешь|считаете)","понятно, (ты|вы) (считаешь|считаете|хочешь|хотите)","требуют (выгнать|запретить|отменить|уничтожить)","вообще запретить"],"parent":"ignoratio_elenchi","counter":{"how":"Сам коротко и точно перескажи свою позицию и спроси, с ней ли спорит собеседник. Ещё лучше применять это заранее и к нему: «правильно я понимаю, что ты считаешь…?»","say":["Я не говорил, что X. Я говорю Y — с этим ты согласен?"],"avoid":"Защищать чучело («да я не такой экстремист…») — так искажённая версия становится предметом спора."}},{"id":"red_herring","name":"Отвлекающий манёвр","latin":null,"aliases":["красная селёдка","уход от темы"],"family":"evasion","definition":"Обсуждаемый вопрос подменяют другим, посторонним, чтобы увести разговор в сторону. Частный случай подмены тезиса.","cues":["кстати","хочу напомнить","а (ты|вы) видел(а|и)?","вот где настоящ","лучше (скажите|посмотрите)"],"parent":"ignoratio_elenchi","counter":{"how":"Признай, что новая тема может быть важной, и предложи вернуться к ней потом.","say":["Про это — отдельный разговор, давай обсудим. Но сначала договорим про…"],"avoid":"Клюнуть: через пять минут вы обсуждаете совсем другое, а исходный вопрос так и висит."}},{"id":"loaded_question","name":"Сложный вопрос","latin":"plurium interrogationum","aliases":["вопрос с подвохом","многовопросье"],"family":"evasion","definition":"В вопрос заложено непризнанное и недоказанное допущение, так что любой прямой ответ его подтверждает.","cues":["(вы|ты) уже перестал","почему (вы|ты) (снова|опять|до сих пор|так и не)","когда (вы|ты) (наконец )?(перестанете|перестанешь|прекратите)","сколько (еще )?(вы|ты) будете","сколько (еще )?(вы|ты) "],"counter":{"how":"Не отвечай «да» или «нет» — назови скрытое допущение и разбери его отдельно.","say":["В вопросе уже заложено, что я… А это не так. Давай сначала об этом."],"avoid":"Отвечать в рамках вопроса: даже «нет» признаёт допущение."}},{"id":"no_true_scotsman","name":"«Настоящий шотландец»","latin":null,"aliases":["«ни один истинный шотландец»","подгонка определения"],"family":"rules","definition":"Контрпример к обобщению отбрасывают, задним числом переопределяя понятие: «настоящий X так не поступает».","cues":["настоящ(ий|ая|ее|ие)","истинн(ый|ая|ое|ые)","значит,? (он|она|это) (и )?не"],"counter":{"how":"Попроси определение до того, как приводить пример, и потом держись за него.","say":["А кто тогда считается настоящим? Давай договоримся о признаках, а потом проверим."],"avoid":"Спорить, «настоящий» ли конкретный человек, — граница будет сдвигаться бесконечно."}},{"id":"special_pleading","name":"Двойные стандарты","latin":null,"aliases":["особая просьба","«это другое»"],"family":"rules","definition":"Для себя или своих делают исключение из общего правила, не объясняя, чем этот случай действительно отличается.","cues":["это другое","(мне|нам|ему|своим) можно","у (меня|нас) (особ|друг)","(я|мы) же не"],"counter":{"how":"Спроси, чем этот случай отличается, — вдруг отличие и правда есть. Если нет, предложи применить правило симметрично.","say":["А если бы так сделал сосед, что бы ты сказал?","Чем наш случай отличается от общего?"],"avoid":"Обвинять в лицемерии — человек кинется защищать репутацию, а не правило."}},{"id":"bandwagon","name":"Апелляция к большинству","latin":"argumentum ad populum","aliases":["аргумент к публике","эффект присоединения"],"family":"pressure","definition":"Утверждение считают верным, а поступок — правильным, потому что так думают или делают многие.","cues":["все носят","миллион(а|ов)? (человек|россиян|людей|клиентов|покупателей)","столько людей","(девять|восемь) из десяти","большинств","могут ошибаться","уже перешли","присоединяйтесь"],"counter":{"how":"Не спорь с количеством. Спроси, почему эти люди так думают: доводы большинства обсуждать можно, само большинство — нет.","say":["Окей, многие так считают. А какие у них основания?"],"avoid":"«Миллионы мух не могут ошибаться» — собеседник почувствует себя мухой."}},{"id":"appeal_to_fear","name":"Апелляция к страху","latin":"argumentum ad metum","aliases":["запугивание","аргумент к палке (argumentum ad baculum)"],"family":"pressure","definition":"Вывод навязывают запугиванием — угрозой или пугающей картиной, а не доводами.","cues":["пока не поздно","(иначе|а то|не то) .*(пожалеете|пожалеешь|потеряете|останетесь|будет поздно)","страшно (подумать|представить)","подумайте о (детях|семье)","вы потеряете","(может|будет) (стать )?поздно"],"counter":{"how":"Признай, что страх понятен, и отдели вопрос «насколько угроза реальна» от вопроса «что делать». Спроси про вероятность и масштаб.","say":["Звучит страшно. А насколько это вероятно и откуда такие данные?"],"avoid":"Высмеивать страх («паникёр!») — испуганный человек от этого защищается ещё сильнее."}},{"id":"appeal_to_pity","name":"Апелляция к жалости","latin":"argumentum ad misericordiam","aliases":["аргумент к жалости","давление на жалость"],"family":"pressure","definition":"Вывод держится на сочувствии к человеку, а не на доводах по существу.","cues":["пожалейте","войдите в (мое|его|ее) положение","(у меня|у него|у нее) (же )?(трое|двое) детей","столько (старал|работал|сил)","(он|она) так (старал|переживал)"],"counter":{"how":"Раздели сочувствие и решение: прямо вырази первое и отдельно обсуди второе. Часто можно найти выход, который учитывает обстоятельства, не ломая правило.","say":["Мне правда жаль, что так вышло. Давай подумаем, что можно сделать, — но по существу."],"avoid":"Холодно отмахнуться — тогда спорить будут уже с твоей бессердечностью."}},{"id":"appeal_to_consequences","name":"Апелляция к последствиям","latin":"argumentum ad consequentiam","aliases":["аргумент к последствиям"],"family":"pressure","definition":"Истинность утверждения оценивают по тому, приятны ли его последствия: «не может быть правдой, ведь тогда было бы плохо».","cues":["не может быть (правдой|так)","(тогда|ведь тогда|иначе) (получается|выходит)","не хочу (в это )?верить","(было бы|это было бы) (ужасно|слишком)"],"counter":{"how":"Раздели два вопроса: «правда ли это» и «что нам с этим делать». Признай, что последствия неприятные.","say":["Да, если это правда, то неприятно. Но давай сначала поймём, правда ли."],"avoid":"Доказывать, что последствия «не так уж страшны», — это тот же подход, только с другой стороны."}},{"id":"appeal_to_tradition","name":"Апелляция к традиции","latin":"argumentum ad antiquitatem","aliases":["апелляция к древности","«так заведено»"],"family":"heritage","definition":"Что-то считают правильным, потому что так делали всегда или так делали предки.","cues":["делали всегда","(деды|отцы|предки)","сорок лет","испокон","так заведено","при моей маме","зачем ломать"],"counter":{"how":"Спроси, зачем традиция появилась и решает ли она эту задачу сейчас. Для человека традиция часто ценна сама по себе — уважай это.","say":["А почему так делали раньше? Эта причина ещё актуальна?"],"avoid":"«Это пережиток» — человек услышит, что его родители были дураками."}},{"id":"appeal_to_novelty","name":"Апелляция к новизне","latin":"argumentum ad novitatem","aliases":["культ новизны","хронологический снобизм"],"family":"heritage","definition":"Что-то считают лучшим только потому, что оно новое или современное.","cues":["новейш","последн(ее|ей|яя|юю|ий) (слово|поколени|верси|модел)","(xxi|двадцать перв)[а-я]* век","(давно|уже) устарел","по-современному"],"counter":{"how":"Спроси, чем новое лучше конкретно — по каким параметрам и для кого.","say":["Что именно в новой версии лучше для нас?"],"avoid":"Встать в позу «раньше было лучше» — это зеркальная ошибка."}},{"id":"appeal_to_nature","name":"Апелляция к природе","latin":"argumentum ad naturam (неклассическое)","aliases":["«натуральное — значит полезное»"],"family":"heritage","definition":"Что-то считают хорошим, потому что оно «натуральное» или «естественное», или плохим, потому что «неестественное».","cues":["натурал","природ","естествен","организм сам","никакой химии"],"counter":{"how":"Переведи разговор с происхождения на действие: что известно о пользе и вреде.","say":["Окей, натуральное. А что известно о том, как оно действует?"],"avoid":"Ехидно перечислять ядовитые грибы — пример верный, но звучит как издёвка."}},{"id":"post_hoc","name":"После — значит вследствие","latin":"post hoc ergo propter hoc","aliases":["после этого — значит, по причине этого","ложная причина"],"family":"cause","definition":"Считают, что раз событие Б произошло после события А, то А и есть причина Б.","cues":["приносит .*удачу","ровно с","всё дело в","связь очевидна","открылся .*а с","с (его )?приходом"],"counter":{"how":"Предложи проверку, а не опровержение: другие объяснения, случай для сравнения.","say":["А в соседнем дворе, где вышки нет, что с голубями?","Что ещё поменялось за это время?"],"avoid":"«Корреляция не означает причинность» — цитата из учебника никого не убеждает."}},{"id":"cum_hoc","name":"Корреляция ≠ причинность","latin":"cum hoc ergo propter hoc","aliases":["ложная корреляция","«вместе — значит из-за»"],"family":"cause","definition":"Из того, что два явления встречаются вместе, делают вывод, что одно вызывает другое, не исключив общую причину или обратную связь.","cues":["(чаще|реже|больше|меньше|выше|ниже) .*(у тех|те|тех), кто","(в странах|в регионах|в городах|в семьях|в школах),? где","связан[аоы]?\\b","чем больше .*тем"],"counter":{"how":"Вопросом предложи третью причину или обратную связь.","say":["А может, их обоих вызывает что-то третье?","А не наоборот — не второе ли вызывает первое?"],"avoid":"Утверждать, что связи точно нет, — этого ты тоже не знаешь."}},{"id":"hasty_generalization","name":"Поспешное обобщение","latin":null,"aliases":["анекдотический довод","обобщение по единичному случаю"],"family":"sampling","definition":"Общий вывод делают по слишком малой или нерепрезентативной выборке.","cues":["все [а-я]+[ыи] (в|этого|этой) ","единодушно","живое доказательство","оба раза","горожане"],"counter":{"how":"Признай, что опыт настоящий, и спроси, на скольких случаях держится вывод.","say":["Тебе правда дважды не повезло. Но хватит ли двух случаев, чтобы судить обо всех?"],"avoid":"Обесценивать опыт («просто совпадение») — неприятно-то человеку было по-настоящему."}},{"id":"cherry_picking","name":"Выборочные факты","latin":null,"aliases":["черри-пикинг","умолчание о неудобных фактах"],"family":"sampling","definition":"Приводят только данные, подтверждающие вывод, умалчивая о тех, что ему противоречат.","cues":["(показ|привод|приве|выбира|выбра|публику|опубликова|выкладыва)[а-я]* только","(лучшие|удачные|хорошие) (месяцы|отзывы|дни|кадры)","(остальные|другие) .*(не показал|не привел|умолчал)"],"counter":{"how":"Спроси о данных, которые не попали в подборку, и о том, как её составляли.","say":["А что говорят исследования с обратным выводом и почему мы их не берём?"],"avoid":"Ответить своей подборкой — начнётся война подборок."}},{"id":"survivorship","name":"Ошибка выжившего","latin":null,"aliases":["систематическая ошибка выжившего"],"family":"sampling","definition":"Выводы делают только по тем, кто «дошёл до финиша» и виден, не учитывая выбывших, которых не видно. Частный случай поспешного обобщения (нерепрезентативная выборка).","cues":["(бросил|не окончил|без образования) .*(миллиардер|миллионер|успешн)","все (известные|успешные|знаменитые)","(уцелел|выжил|сохранил)[аио]?с?[ья]? .*(значит|потому что|так что)","(старые|старинные) [а-я]+ (стоят|служат|работают)","дожил","до сих пор работа","бросил[^.]*..*успех","(самых )?(богатых|успешных|известных) людей"],"parent":"hasty_generalization","counter":{"how":"Спроси, кого не видно: тех, кто не дошёл до финиша.","say":["А сколько людей сделали то же самое и прогорели? Про них ведь не пишут."]}},{"id":"misleading_statistics","name":"Манипуляция статистикой","latin":null,"aliases":["игра с процентами","статистическая манипуляция"],"family":"sampling","definition":"Цифры подают так, что они создают ложное впечатление: проценты без базы, относительный рост вместо абсолютного, несопоставимые сравнения.","cues":["в (два|три|четыре|пять|десять|\\d+) раза","на (\\d+|сто|двести|триста) процентов","(с|со) (одного|двух|трех) до","d+ ?%","средн(яя|ий|его) (зарплат|доход)"],"counter":{"how":"Попроси абсолютные числа и базу сравнения.","say":["Рост в два раза — с какого числа до какого?","Проценты от чего?"],"avoid":"Отмахиваться «статистика врёт» — это подрывает и твои собственные цифры."}},{"id":"gamblers_fallacy","name":"Ошибка игрока","latin":null,"aliases":["ошибка Монте-Карло"],"family":"sampling","definition":"Считают, что прошлые исходы независимых случайных событий влияют на будущие: «давно не выпадало — значит, скоро выпадет».","cues":["(теперь|уж)-?то .*точно","подряд","назрел","сколько можно","закон[уа]? вероятност","не выпадал"],"counter":{"how":"Объясни, что у случайности нет памяти; если есть время — предложи посчитать или проверить.","say":["Рулетка не помнит прошлый раз. Шансы на красное каждый раз одинаковые."],"avoid":"Спорить с игроком в азарте — вернись к разговору потом, на холодную голову."}},{"id":"false_dilemma","name":"Ложная дилемма","latin":null,"aliases":["ложная альтернатива","чёрно-белое мышление","«или — или»"],"family":"choice","definition":"Выбор сводят к двум вариантам, хотя существуют и другие.","cues":["\\bлибо\\b.*\\bлибо\\b","\\bили\\b[^.]*,\\s*или\\b","третьего не дано","если (ты|вы) против .*значит","только два варианта"],"counter":{"how":"Назови третий вариант конкретно: абстрактное «вариантов больше» звучит как увёртка.","say":["А почему не так: …? Это ведь тоже вариант."],"avoid":"Выбирать одну из навязанных сторон, даже «меньшее зло», — так ты признаёшь рамку."}},{"id":"middle_ground","name":"Ложный компромисс","latin":"argumentum ad temperantiam","aliases":["аргумент к умеренности","«истина посередине»"],"family":"choice","definition":"Считают, что истина или справедливое решение всегда лежит посередине между двумя позициями.","cues":["посередине","золот(ая|ую) середин","(где-то|как обычно) между","поровну|пополам|наполовину"],"counter":{"how":"Спроси, почему середина правильна именно здесь: иногда одна из сторон просто права.","say":["Если один скажет «дважды два — четыре», а другой «шесть», ответ — пять?"],"avoid":"Приводить пример с арифметикой без хорошего контакта — прозвучит снисходительно."}},{"id":"nirvana","name":"Ошибка нирваны","latin":null,"aliases":["ошибка идеального решения","«лучшее — враг хорошего»"],"family":"choice","definition":"Решение отвергают, потому что оно не идеально и не решает проблему полностью, хотя улучшает положение.","cues":["(все равно|всё равно) (будут|найдут|кто-то)","какой (в этом )?смысл","не (решит|спасет|остановит|уберет) (всех|все|полностью|проблему)","(сто|100) процентов","стопроцентн"],"counter":{"how":"Сравнивай решение с тем, что есть сейчас, а не с идеалом.","say":["Да, проблему целиком это не решит. Но станет лучше, чем сейчас, или нет?"],"avoid":"Доказывать, что решение идеально, — это та же рамка «идеал или ничего»."}},{"id":"slippery_slope","name":"Скользкая дорожка","latin":null,"aliases":["преждевременное допущение","эффект домино","аргумент наклонной плоскости"],"family":"choice","definition":"Утверждают, что небольшой шаг неизбежно запустит цепочку всё более тяжёлых последствий, не обосновывая звенья этой цепочки.","cues":["сегодня [^.—]*, завтра","а там и","оглянуться не успеешь","через (год|месяц) .*превратится","начнем с","придется разрешить всем","(потом|затем) все захотят"],"counter":{"how":"Попроси пройти цепочку по звеньям: почему каждый следующий шаг неизбежен? Иногда можно предложить точку остановки.","say":["Хорошо, первый шаг. А почему из него обязательно следует второй?"],"avoid":"Отрицать риск вообще — иногда склон действительно скользкий."}},{"id":"sunk_cost","name":"Невозвратные затраты","latin":null,"aliases":["эффект Конкорда","ловушка невозвратных затрат"],"family":"choice","definition":"Продолжают вкладываться в дело из-за того, что уже потрачено, а не из-за ожидаемой пользы в будущем.","cues":["заплачен","не пропадать же","на ветер","уже вложил","псу под хвост","не можем остановиться","(столько|много) [а-я ]*вложил","уже посмотрел"],"counter":{"how":"Предложи посмотреть с чистого листа и признай, что потраченного жалко.","say":["Если бы ты сейчас ничего ещё не вложил, стал бы начинать?"],"avoid":"«Ты зря потратил деньги» — соль на рану: человек начнёт защищать прошлое решение."}},{"id":"circular","name":"Порочный круг","latin":"circulus in probando","aliases":["круг в доказательстве"],"family":"structure","definition":"Вывод уже заложен в посылку: тезис доказывают через него самого или через утверждение, которое само опирается на тезис.","cues":["потому что .*потому что","там написано","доказывает .*то, что","потому что он написан","а почему"],"counter":{"how":"Попроси довод, который не опирается на сам тезис, — независимое подтверждение.","say":["А если заранее не принимать, что это так, — что ещё на это указывает?"]}},{"id":"non_sequitur","name":"Мнимое следование","latin":"non sequitur","aliases":["«не следует»","логический скачок"],"family":"structure","definition":"Вывод не вытекает из посылок: между «раз…» и «значит…» нет связи, даже если сами посылки верны. Сюда же относится смешение достаточного условия с необходимым. Общая категория: если у ошибки есть более точное название (утверждение следствия, отрицание основания), лучше назвать его.","cues":["раз [^.]*[—,] значит","ясно дело","ясен корень","а раз [^.]*[—,] (значит|то)"],"counter":{"how":"Согласись с посылкой и попроси проговорить переход: часто человек сам находит пропущенное звено — или пробел.","say":["С первым согласен. Не понимаю, как отсюда получается второе, — объясни этот шаг."]}},{"id":"false_premise","name":"Ложное основание","latin":"error fundamentalis","aliases":["основное заблуждение","предвосхищение основания (petitio principii)","недоказанное основание"],"family":"structure","definition":"Вывод построен по правилам, но опирается на ложную или ничем не подтверждённую посылку, которую выдают за очевидную.","cues":["(нужно|необходимо|надо) непременно","известно же,? что","всем известно","общеизвестно","как известно","непременно нужно"],"counter":{"how":"Не спорь с выводом: если логика правильная, проиграешь. Найди посылку и спроси, откуда она известна.","say":["Ты исходишь из того, что… А откуда мы это знаем?"]}},{"id":"affirming_consequent","name":"Утверждение следствия","latin":"fallacia consequentis","aliases":["утверждение консеквента","обратный вывод"],"family":"structure","definition":"«Если A, то B; B есть — значит, A». Но B могло случиться и по другой причине. Частный случай мнимого следования.","cues":["если [^.]*, (то|значит)[^.]*\\..*(значит|выходит|следовательно)","(всегда|обязательно) [а-я]+ — значит"],"parent":"non_sequitur","counter":{"how":"Приведи другую причину того же следствия.","say":["Мокрый асфальт бывает и после поливалки. Что ещё говорит именно о дожде?"]}},{"id":"denying_antecedent","name":"Отрицание основания","latin":null,"aliases":["отрицание антецедента"],"family":"structure","definition":"«Если A, то B; A нет — значит, и B нет». Но B может наступить и без A. Частный случай мнимого следования.","cues":["если [^.]*, (то )?[^.]*\\..*не [^.]*,? (значит|так что|выходит),? (и )?(нам )?не"],"parent":"non_sequitur","counter":{"how":"Покажи другой путь к тому же результату.","say":["Без диплома — значит, не программист? А самоучки?"]}},{"id":"appeal_to_ignorance","name":"Апелляция к незнанию","latin":"argumentum ad ignorantiam","aliases":["аргумент к незнанию","перекладывание бремени доказательства"],"family":"structure","definition":"Утверждение считают истинным, потому что его не опровергли, или ложным, потому что его не доказали.","cues":["не доказал","никто (еще |так и )?не (доказал|опроверг|смог)","нет доказательств","не опроверг","ни одной жалобы"],"counter":{"how":"Вежливо верни бремя доказательства и спроси, что вообще считалось бы доказательством.","say":["Утверждаешь ты — тебе и показывать. Что тебя самого убедило?"],"avoid":"Кидаться опровергать: ты берёшь бремя на себя, и любой пробел в опровержении станет «доказательством»."}},{"id":"fallacy_fallacy","name":"«Ошибка ошибки»","latin":"argumentum ad logicam","aliases":["аргумент от ошибки"],"family":"structure","definition":"Из того, что довод в пользу вывода плох, заключают, что сам вывод ложен.","cues":["(довод|аргумент|доказательств)[а-я]* .*(плох|ошибоч|неверн|глуп|слаб|бредов|липа).*значит","раз (он|она|ты|вы) (ошибся|ошиблась|ошиблись|не смог)"],"counter":{"how":"Раздели: довод плохой, но вывод ещё может оказаться верным. Это совет и себе: поймав ошибку, не празднуй победу.","say":["Аргумент так себе, согласен. Но вопрос открыт — давай поищем доводы получше."]}},{"id":"equivocation","name":"Подмена понятий","latin":"aequivocatio","aliases":["эквивокация","учетверение термина (в силлогизме)","игра слов"],"family":"language","definition":"Одно и то же слово внутри рассуждения используется в разных смыслах, и вывод держится на этой двусмысленности. Не путать с подменой тезиса, где подменяется всё утверждение.","cues":["в (прямом|переносном|юридическом|бытовом) смысле","тоже (ведь )?[а-я]+, значит","по определению"],"counter":{"how":"Попроси уточнить, в каком смысле употреблено слово, и держать этот смысл до конца.","say":["«Теория» тут в каком смысле — догадка или научная теория?"]}},{"id":"false_analogy","name":"Ложная аналогия","latin":null,"aliases":["слабая аналогия","сравнение яблок с апельсинами"],"family":"language","definition":"Из сходства двух вещей в чём-то одном выводят их сходство в существенном, хотя по важным признакам они различаются.","cues":["это (все )?равно что","точно так же,? как","то же самое, что","ведь и [а-я]+ тоже","как и с"],"counter":{"how":"Прими аналогию и укажи существенное различие, которое меняет вывод.","say":["Похоже, да. Но есть важное отличие: … Это не меняет вывод?"]}},{"id":"composition","name":"Ошибка композиции","latin":"fallacia compositionis","aliases":["от части к целому"],"family":"language","definition":"Считают, что раз свойством обладает каждая часть, то им обладает и целое.","cues":["(каждый|каждая|каждое|все) .*значит,? (и )?(вся|весь|все вместе|целиком|команда|блюдо|суп)","из (самых )?лучших"],"counter":{"how":"Приведи пример целого, которое ведёт себя не как его части.","say":["Каждый игрок — звезда, но команда ведь может и не сыграться."]}},{"id":"division","name":"Ошибка деления","latin":"fallacia divisionis","aliases":["от целого к части"],"family":"language","definition":"Считают, что раз свойством обладает целое, то им обладает и каждая его часть.","cues":["раз (вся|весь|наша|наш|эта|этот) [а-я]+ .*значит,? (и )?(каждый|любой|он|она)","значит,? (и )?(каждый|любой) (ее|его|их)? ?(сотрудник|выпускник|житель|игрок)","часть организма"],"counter":{"how":"Спроси про конкретную часть: обладает ли она свойством целого?","say":["Команда сильная — значит, и запасной вратарь сильный?"]}},{"id":"none","name":"Ошибки нет","latin":null,"aliases":[],"family":null,"definition":"Рассуждение корректно: вывод следует из посылок, источники уместны, альтернативы учтены.","cues":[]}],"overlaps":[{"pair":["ad_hominem","tu_quoque"],"note":"«Сам такой» — частный случай перехода на личность."},{"pair":["tu_quoque","red_herring"],"note":"«А у вас…» (вотэбаутизм) одновременно уводит от темы."},{"pair":["straw_man","red_herring"],"note":"Искажённая позиция часто служит и сменой темы."},{"pair":["straw_man","false_dilemma"],"note":"«Если вы против X, значит вы за крайность Y» — и дилемма, и искажение."},{"pair":["hasty_generalization","bandwagon"],"note":"Опрос узкой группы, выданный за мнение большинства."},{"pair":["appeal_to_nature","appeal_to_tradition"],"note":"«Так жили предки» часто подаётся как «так естественно»."},{"pair":["hasty_generalization","post_hoc"],"note":"Причинный вывод по одному случаю — оба признака."},{"pair":["post_hoc","cum_hoc"],"note":"Обе — ложная причина; разница в том, опирается ли вывод на порядок во времени."},{"pair":["hasty_generalization","cherry_picking"],"note":"Малая выборка против намеренно отобранной."},{"pair":["hasty_generalization","survivorship"],"note":"Выборка только из «выживших» — частный случай нерепрезентативной."},{"pair":["cherry_picking","misleading_statistics"],"note":"Удобный период или база — и отбор данных, и манипуляция цифрами."},{"pair":["appeal_to_tradition","appeal_to_novelty"],"note":"Зеркальные ошибки: «старое — значит лучше» и «новое — значит лучше»."},{"pair":["genetic_fallacy","ad_hominem"],"note":"Оценка по источнику: идея от «плохого» человека."},{"pair":["no_true_scotsman","equivocation"],"note":"Переопределение понятия задним числом — тоже игра со смыслом слова."},{"pair":["appeal_to_fear","slippery_slope"],"note":"Пугающая цепочка последствий — и запугивание, и скользкая дорожка."},{"pair":["appeal_to_fear","appeal_to_consequences"],"note":"Неприятные последствия как довод о факте или как угроза."},{"pair":["composition","division"],"note":"Зеркальные ошибки части и целого."},{"pair":["composition","hasty_generalization"],"note":"«Каждый X — значит, все вместе» похоже на обобщение."},{"pair":["affirming_consequent","denying_antecedent"],"note":"Две формальные ошибки с одной импликацией."},{"pair":["affirming_consequent","post_hoc"],"note":"«Есть следствие — значит, была причина» звучит как вывод о причине."},{"pair":["appeal_to_ignorance","fallacy_fallacy"],"note":"Обе выводят ложность тезиса из слабости доказательств."},{"pair":["middle_ground","false_dilemma"],"note":"Обе неверно описывают пространство вариантов."},{"pair":["nirvana","false_dilemma"],"note":"«Идеально или никак» — тоже ложный выбор."},{"pair":["appeal_to_pity","red_herring"],"note":"Сочувствие подменяет обсуждение по существу."},{"pair":["bandwagon","false_analogy"],"note":"«У других сработало — сработает и у нас» опирается и на большинство, и на сходство."},{"pair":["loaded_question","circular"],"note":"Вопрос, заранее предполагающий ответ."},{"pair":["non_sequitur","false_premise"],"note":"Вывод не следует — или следует, но из ложной посылки: важно, где именно дефект."},{"pair":["non_sequitur","slippery_slope"],"note":"Цепочка необоснованных «раз… значит» похожа на скользкую дорожку, но это вывод о факте, а не прогноз последствий."},{"pair":["false_premise","circular"],"note":"Недоказанная посылка против посылки, которая сама опирается на вывод."},{"pair":["no_true_scotsman","hasty_generalization"],"note":"«Настоящий шотландец» спасает поспешное обобщение от контрпримера."},{"pair":["no_true_scotsman","circular"],"note":"Подогнанное определение делает утверждение верным «по определению» — почти круг."}]},"questions":[{"id":"q001","batch":1,"difficulty":1,"text":"На собрании жильцов Ольга Петровна предложила поставить шлагбаум, чтобы машины перестали парковаться на газоне. Сосед с третьего этажа отмахнулся: «Да что её слушать, она вечно со всеми ругается и бельё на балконе сушит». Шлагбаум обсуждать не стали.","answer_id":"ad_hominem","distractors":["tu_quoque","genetic_fallacy","red_herring","straw_man"],"offer_none":false,"highlight":"Да что её слушать, она вечно со всеми ругается и бельё на балконе сушит","explanation":"Предложение отвергнуто не потому, что шлагбаум плох (дорого, мешает скорой, неудобно жильцам), а из-за характера и привычек автора. Сварливость Ольги Петровны никак не влияет на то, защитит ли шлагбаум газон.","nearest_distractor":"tu_quoque","contrast":"«Сам такой» было бы, если бы сосед сказал: «А сама-то на газоне паркуется» — то есть упрекнул автора в нарушении того же самого. Здесь же припомнили посторонние недостатки, не связанные с парковкой."},{"id":"q002","batch":1,"difficulty":2,"text":"Молодой экономист опубликовал колонку о том, что повышение пошлин на импортную технику ударит по покупателям. В комментариях профессор из соседнего вуза ответил: «Человеку двадцать семь лет, он даже кризиса девяносто восьмого не застал. О каком понимании экономики может идти речь?» Расчёты из колонки он разбирать не стал.","answer_id":"ad_hominem","distractors":["false_authority","tu_quoque","genetic_fallacy","red_herring"],"offer_none":true,"highlight":"Человеку двадцать семь лет, он даже кризиса девяносто восьмого не застал.","explanation":"Возраст автора и отсутствие у него личного опыта кризиса не опровергают его расчётов. Чтобы возразить по существу, нужно было показать ошибку в цифрах или логике колонки, а профессор вместо этого дискредитирует самого автора.","nearest_distractor":"false_authority","contrast":"Ложный авторитет — когда тезис подкрепляют ссылкой на неподходящего «эксперта». Профессор не ссылается на свой статус как на доказательство, он бьёт по личности оппонента. Его звание не превращает атаку на возраст в аргумент.","pick_notes":{"tu_quoque":"«Сам такой» — частный случай перехода на личность, когда оппоненту указывают, что он сам делает то же самое. Здесь такого упрёка нет: автора атакуют за другое."}},{"id":"q003","batch":1,"difficulty":3,"text":"Депутат Синицын выступил за снижение налога для фермеров. Журналист в эфире заметил: «Неудивительно — у его тестя крупное хозяйство в области». Ведущий подхватил: «Значит, и спорить не о чем: закон выгоден лично ему, следовательно, он вреден для страны».","answer_id":"ad_hominem","distractors":["genetic_fallacy","red_herring","tu_quoque","straw_man"],"offer_none":true,"highlight":"закон выгоден лично ему, следовательно, он вреден для страны","explanation":"Указание на возможную заинтересованность депутата — законный повод внимательнее проверить его аргументы, но не их опровержение. Вывод «выгоден ему — значит вреден стране» отвергает закон по обстоятельствам жизни автора, не разбирая самих последствий закона. Это ситуативный вариант перехода на личность.","nearest_distractor":"genetic_fallacy","contrast":"Генетическая ошибка оценивает идею по её происхождению вообще: откуда взялся обычай, кто придумал слово. Когда «происхождение» — это мотивы конкретного оппонента в споре, принято говорить о ситуативном переходе на личность. Граница тонкая.","also_accepted":[{"id":"genetic_fallacy","note":"Ситуативный переход на личность нередко описывают и как генетическую ошибку: закон оценивают по его источнику. Но точнее — переход на личность: оценивают мотивы конкретного оппонента в споре."}],"pick_notes":{"tu_quoque":"«Сам такой» — частный случай перехода на личность, когда оппоненту указывают, что он сам делает то же самое. Здесь такого упрёка нет: автора атакуют за другое."}},{"id":"q004","batch":1,"difficulty":1,"text":"Отец сказал шестнадцатилетнему Диме, что курение разрушает лёгкие и пора бросать. Дима усмехнулся: «Пап, ты сам полпачки в день выкуриваешь. Так что не тебе меня учить». И закурил прямо на балконе.","answer_id":"tu_quoque","distractors":["ad_hominem","red_herring","special_pleading","genetic_fallacy"],"offer_none":false,"highlight":"ты сам полпачки в день выкуриваешь. Так что не тебе меня учить","explanation":"Отец действительно непоследователен, но это не делает его довод ложным: курение вредит лёгким независимо от того, курит ли тот, кто об этом говорит. Дима отвергает совет, указывая на лицемерие советчика.","nearest_distractor":"ad_hominem","contrast":"При переходе на личность припоминают любые недостатки — характер, возраст, внешность. «Сам такой» — его частный случай: оппоненту указывают, что он сам нарушает то, к чему призывает. Здесь упрёк ровно про курение.","pick_notes":{"special_pleading":"Двойные стандарты — когда человек сам формулирует исключение для себя («мне можно, тебе нельзя»). Отец такого не утверждает: он просто не следует своему совету. Ошибка в рассуждении здесь у Димы."}},{"id":"q005","batch":1,"difficulty":2,"text":"МИД одной страны выразил обеспокоенность задержаниями журналистов в соседнем государстве. Пресс-секретарь соседей ответил: «Пусть сначала разберутся, сколько репортёров сидит у них самих». Вопрос о задержанных в его стране на брифинге больше не поднимался.","answer_id":"tu_quoque","distractors":["red_herring","ad_hominem","straw_man","special_pleading"],"offer_none":false,"highlight":"Пусть сначала разберутся, сколько репортёров сидит у них самих","explanation":"Даже если у критиков свои проблемы со свободой прессы, это не отвечает на вопрос, справедливы ли задержания в стране пресс-секретаря. Обвинение просто возвращается обвинителю вместо ответа по существу.","nearest_distractor":"red_herring","contrast":"Отвлекающий манёвр — смена темы на любую постороннюю. Здесь ответ специфичен: «вы делаете то же самое», то есть обвинение в лицемерии по тому же вопросу. Это и отличает «сам такой» от простого увода разговора, хотя эффект похожий.","also_accepted":[{"id":"red_herring","note":"Ответ действительно уводит от темы, и часть пособий так его и классифицирует. Но упрёк здесь зеркальный — «у вас то же самое», поэтому точнее «сам такой»."}]},{"id":"q006","batch":1,"difficulty":3,"text":"Тренер по плаванию сделал замечание родителю, который снимал соревнования со вспышкой: вспышка слепит детей на старте. Родитель возмутился: «А ваши ассистенты в прошлом месяце сами всё снимали со вспышкой!» Тренер ответил: «Тогда это тоже было неправильно, и я им об этом сказал. Уберите, пожалуйста, вспышку».","answer_id":"tu_quoque","distractors":["ad_hominem","red_herring","special_pleading","straw_man"],"offer_none":true,"highlight":"А ваши ассистенты в прошлом месяце сами всё снимали со вспышкой!","explanation":"Родитель пытается обесценить замечание тем, что сторона тренера сама нарушала то же правило. Но прошлые нарушения ассистентов не делают вспышку безопасной для пловцов. Тренер, кстати, отвечает корректно: признаёт ошибку своих и возвращается к сути.","nearest_distractor":"ad_hominem","contrast":"Родитель не нападает на личные качества тренера (возраст, характер, компетентность), а указывает на непоследовательность в том же самом вопросе — классическое «сам такой».","pick_notes":{"none":"Тренер действительно рассуждает корректно — и это ловушка. Ошибку допускает родитель: «ваши ассистенты сами снимали со вспышкой». Задача — найти ошибку в любой реплике сценки, а не оценить последнего говорящего. Наблюдательность — половина работы сыщика."}},{"id":"q007","batch":1,"difficulty":1,"text":"Мама предложила, чтобы по будням дети играли в приставку не больше часа. Старший сын взорвался: «То есть ты хочешь вообще запретить нам всё интересное, чтобы мы сидели с учебниками до ночи? Это бесчеловечно!»","answer_id":"straw_man","distractors":["slippery_slope","false_dilemma","red_herring","appeal_to_pity"],"offer_none":false,"highlight":"То есть ты хочешь вообще запретить нам всё интересное, чтобы мы сидели с учебниками до ночи?","explanation":"Мама говорила об ограничении одного занятия часом в будни, а сын спорит с выдуманной, утрированной позицией — тотальным запретом всего интересного. Опровергнуть такую позицию легко, но мама её не высказывала.","nearest_distractor":"slippery_slope","contrast":"Скользкая дорожка — это прогноз цепочки последствий («сегодня час, завтра совсем запретишь…»). Сын не предсказывает будущее, а сразу приписывает маме более крайнюю позицию, чем она заняла."},{"id":"q008","batch":1,"difficulty":2,"text":"Городской активист предложил расширить тротуары на центральной улице за счёт одной полосы для машин. В вечерних новостях это подали так: «Активисты требуют выгнать автомобили из центра. Но как тогда скорая доберётся до больных, а грузовики — до магазинов?»","answer_id":"straw_man","distractors":["red_herring","slippery_slope","appeal_to_fear","false_dilemma"],"offer_none":true,"highlight":"Активисты требуют выгнать автомобили из центра.","explanation":"Предложение сузить проезжую часть на одну полосу превращено в требование убрать машины вовсе, и возражения (скорая, доставка) направлены против этой искажённой версии. Против исходной идеи они не работают: полосы для машин на улице остаются.","nearest_distractor":"red_herring","contrast":"Отвлекающий манёвр уводит к другой теме. Здесь тема та же — машины и улица, но позиция оппонента подменена более крайней и удобной для критики."},{"id":"q009","batch":1,"difficulty":3,"text":"На планёрке аналитик сказала: «Опросы показывают, что клиентам не хватает поддержки по выходным; можно попробовать дежурства хотя бы в субботу». Руководитель отдела поддержки ответил: «Понятно, вы считаете, что моя команда плохо работает. Но ребята закрывают по восемьдесят обращений в день — посмотрите статистику!»","answer_id":"straw_man","distractors":["red_herring","ad_hominem","tu_quoque","appeal_to_pity"],"offer_none":false,"highlight":"Понятно, вы считаете, что моя команда плохо работает.","explanation":"Аналитик говорила о графике (в выходные поддержки нет), а не о качестве работы команды. Руководитель приписывает ей обвинение в плохой работе и опровергает уже его — статистикой будних дней, которая к выходным не относится.","nearest_distractor":"red_herring","contrast":"Статистика про восемьдесят обращений действительно уводит в сторону, но этому предшествует главный ход: руководитель переформулирует слова собеседницы в более удобное для спора обвинение. Отвлекающий манёвр был бы, если бы он просто заговорил о другом, не искажая её позиции.","also_accepted":[{"id":"red_herring","note":"Статистика будних дней действительно уводит в сторону. Но этому предшествует искажение слов собеседницы, и именно оно — первый и главный ход."}]},{"id":"q010","batch":1,"difficulty":1,"text":"Продавец в салоне связи настаивает: «Либо вы берёте этот флагман за девяносто тысяч, либо будете мучиться с тормозящим телефоном». Ирина присматривалась к модели за двадцать пять тысяч с хорошими отзывами, но о ней продавец даже не упомянул.","answer_id":"false_dilemma","distractors":["appeal_to_fear","nirvana","middle_ground","bandwagon"],"offer_none":false,"highlight":"Либо вы берёте этот флагман за девяносто тысяч, либо будете мучиться с тормозящим телефоном","explanation":"Выбор сведён к двум крайностям, хотя между ними множество моделей, в том числе та, что приглянулась Ирине. Отсутствие других вариантов не доказано, а просто подразумевается.","nearest_distractor":"appeal_to_fear","contrast":"«Будете мучиться» — нотка запугивания есть, но довод держится не на угрозе, а на том, что вариантов якобы только два. Уберите страшилку («либо флагман, либо бюджетная модель») — ошибка останется."},{"id":"q011","batch":1,"difficulty":2,"text":"В споре о школьной форме завуч сказала родителям: «Если вы против единой формы, значит, вас устраивает, что дети приходят на уроки в пляжных шортах». Несколько родителей, предлагавших ввести простой дресс-код без конкретной модели формы, промолчали.","answer_id":"false_dilemma","distractors":["straw_man","middle_ground","appeal_to_tradition","red_herring"],"offer_none":false,"highlight":"Если вы против единой формы, значит, вас устраивает, что дети приходят на уроки в пляжных шортах","explanation":"Завуч оставляет только два варианта: единая форма или полная вседозволенность. Промежуточный вариант — дресс-код — существует и даже звучал на собрании, но в её рамке ему нет места.","nearest_distractor":"straw_man","contrast":"Элемент искажения здесь есть, но ключевой приём — сужение выбора до двух полюсов: «или форма, или шорты». Соломенное чучело было бы, если бы завуч приписала родителям конкретное заявление («вы требуете разрешить шорты») и опровергала его.","also_accepted":[{"id":"straw_man","note":"Элемент искажения позиции родителей есть. Но ядро приёма — «или форма, или шорты», то есть искусственное сужение выбора."}]},{"id":"q012","batch":1,"difficulty":3,"text":"Колонка в городской газете: «Бюджет не резиновый. Мы должны выбрать: или ремонтируем дороги, или строим новый детский сад. Третьего не дано». В том же номере газета сообщает, что город перенёс на следующий год закупку новых автомобилей для администрации.","answer_id":"false_dilemma","distractors":["nirvana","middle_ground","sunk_cost","red_herring"],"offer_none":true,"highlight":"или ремонтируем дороги, или строим новый детский сад. Третьего не дано","explanation":"Ограниченность бюджета реальна, но «дороги или сад» — не единственный выбор: можно перераспределить другие статьи (например, ту же закупку машин), разбить ремонт на этапы, найти софинансирование. Фраза «третьего не дано» объявляет альтернативы несуществующими без доказательств.","nearest_distractor":"none","contrast":"Иногда выбор действительно бинарен, и тогда ошибки нет. Но здесь сама газета показывает, что в бюджете есть и другие статьи, — значит, вариантов больше двух."},{"id":"q013","batch":1,"difficulty":1,"text":"Бабушка против того, чтобы внучка проколола уши: «Сегодня серёжки, завтра пирсинг в носу, потом татуировки по всему телу, а там и до плохой компании недалеко. Оглянуться не успеешь — бросит институт».","answer_id":"slippery_slope","distractors":["appeal_to_fear","appeal_to_tradition","hasty_generalization","appeal_to_consequences"],"offer_none":false,"highlight":"Сегодня серёжки, завтра пирсинг в носу, потом татуировки по всему телу, а там и до плохой компании недалеко","explanation":"Каждый следующий шаг объявляется неизбежным следствием предыдущего, хотя ни одно звено не обосновано: миллионы людей носят серёжки и не бросают учёбу.","nearest_distractor":"appeal_to_fear","contrast":"Бабушка, конечно, пугает. Но логический дефект — в цепочке «одно неизбежно ведёт к другому». Апелляция к страху — когда вывод держится на самой угрозе, без такой цепочки: «не прокалывай, а то пожалеешь»."},{"id":"q014","batch":1,"difficulty":2,"text":"Городская дума обсуждает, разрешить ли кафе работать на летних верандах до полуночи. Один из депутатов заявил: «Начнём с веранд до двенадцати — и через год весь центр превратится в круглосуточный ночной клуб, жители побегут из района, а квартиры обесценятся».","answer_id":"slippery_slope","distractors":["post_hoc","appeal_to_fear","appeal_to_consequences","hasty_generalization"],"offer_none":true,"highlight":"через год весь центр превратится в круглосуточный ночной клуб, жители побегут из района, а квартиры обесценятся","explanation":"Лишний час работы веранд представлен как первый шаг неизбежного падения. Почему одно решение автоматически повлечёт следующие (круглосуточный режим, бегство жителей), не объясняется — каждый из этих шагов потребовал бы отдельного решения той же думы.","nearest_distractor":"post_hoc","contrast":"«После — значит вследствие» — ошибка в объяснении уже случившегося: «произошло после, значит из-за». Скользкая дорожка — прогноз будущей цепочки событий, которых ещё не было."},{"id":"q015","batch":1,"difficulty":3,"text":"Директор небольшой фирмы отказал сотруднику в одном удалённом дне в неделю: «Если разрешу тебе, придётся разрешить всем. Потом все захотят работать из дома постоянно, офис опустеет, мы перестанем общаться, проекты начнут срываться, и фирма закроется».","answer_id":"slippery_slope","distractors":["appeal_to_fear","false_dilemma","appeal_to_consequences","appeal_to_tradition"],"offer_none":true,"highlight":"Потом все захотят работать из дома постоянно, офис опустеет, мы перестанем общаться, проекты начнут срываться, и фирма закроется","explanation":"Первое звено («придётся разрешить всем») можно обсуждать — прецедент действительно возникает. Но дальше идут переходы, ничем не подкреплённые: от одного дня в неделю к полной удалёнке и от неё — к закрытию фирмы. Причём каждый следующий шаг директор сам вправе не разрешать.","nearest_distractor":"none","contrast":"Опасение прецедента само по себе разумно, и если бы директор остановился на нём, ошибки могло бы и не быть. Ошибка — в длинной цепи необоснованных «и тогда», доведённой до краха фирмы."},{"id":"q016","batch":1,"difficulty":1,"text":"Марина дважды заказывала еду в новом сервисе доставки, и оба раза курьер опаздывал. Она написала подруге: «Все курьеры в этом городе — безответственные люди. Больше ничего заказывать не буду».","answer_id":"hasty_generalization","distractors":["cherry_picking","post_hoc","gamblers_fallacy","false_analogy"],"offer_none":false,"highlight":"Все курьеры в этом городе — безответственные люди.","explanation":"Два случая с одним сервисом превращены в вывод обо всех курьерах города. Выборка слишком мала и не представляет даже этот сервис, не говоря уж о других. Отказаться от конкретного сервиса — разумно, обобщать на всех — нет.","nearest_distractor":"cherry_picking","contrast":"Выборочные факты — когда из многих данных намеренно показывают удобные. У Марины других данных нет вовсе: она опирается на всё, что видела, но двух случаев слишком мало для вывода обо всех курьерах города."},{"id":"q017","batch":1,"difficulty":2,"text":"Ведущий утреннего шоу: «Мы спросили нашу аудиторию в соцсетях, нужен ли городу новый стадион. Девяносто процентов ответили „да“! Очевидно, горожане единодушно поддерживают проект». Опрос проводился на странице спортивного канала.","answer_id":"hasty_generalization","distractors":["bandwagon","misleading_statistics","false_authority","post_hoc"],"offer_none":true,"highlight":"Очевидно, горожане единодушно поддерживают проект","explanation":"Выборка нерепрезентативна: подписчики спортивного канала заведомо чаще других хотят стадион. Вывод обо всех горожанах по такой группе — поспешное обобщение (смещённая выборка).","nearest_distractor":"bandwagon","contrast":"Апелляция к большинству — «это правильно, потому что так думают многие». Ведущий ошибается раньше: он неверно устанавливает само мнение большинства, обобщая взгляды узкой группы на весь город."},{"id":"q018","batch":1,"difficulty":3,"text":"Пётр Иванович курил с восемнадцати лет и дожил до девяноста двух, ни разу не лежав в больнице. На семейном празднике его внук заявил: «Вот вам и вред курения! Дед — живое доказательство, что все эти страшилки врачей сильно преувеличены».","answer_id":"hasty_generalization","distractors":["survivorship","post_hoc","false_authority","misleading_statistics"],"offer_none":false,"highlight":"Дед — живое доказательство, что все эти страшилки врачей сильно преувеличены","explanation":"Один случай не опровергает статистику, собранную на миллионах людей. При любом риске бывают счастливые исключения; вывод об общей закономерности по одному примеру — поспешное обобщение.","nearest_distractor":"survivorship","contrast":"Ошибка выжившего — когда вывод делают только по «дошедшим до финиша». Это здесь тоже есть: умерших курильщиков на празднике нет. Но основной дефект — опора на один пример вместо статистики.","also_accepted":[{"id":"survivorship","note":"Это тоже верное наблюдение: курильщиков, не доживших до праздника, за столом нет, и их не видно. Но внук опирается на один-единственный пример, поэтому основной ярлык — поспешное обобщение."}]},{"id":"q019","batch":1,"difficulty":1,"text":"В понедельник Света надела новый браслет, а во вторник получила пятёрку за контрольную, которую боялась завалить. Теперь она надевает браслет перед каждым экзаменом: «Он приносит мне удачу, это проверено».","answer_id":"post_hoc","distractors":["hasty_generalization","cum_hoc","gamblers_fallacy","false_authority"],"offer_none":false,"highlight":"Он приносит мне удачу, это проверено","explanation":"Пятёрка случилась после того, как Света надела браслет, но из этого не следует, что браслет её вызвал. Куда вероятнее, что сыграла роль подготовка. Совпадение во времени принято за причину.","nearest_distractor":"hasty_generalization","contrast":"Здесь тоже всего один случай, но вывод не обобщающий («все браслеты помогают»), а причинный: «этот браслет вызвал пятёрку». Ключевое — ошибка в причине, основанная на последовательности событий."},{"id":"q020","batch":1,"difficulty":2,"text":"Новый главный тренер возглавил хоккейный клуб в декабре, и до конца сезона команда выиграла восемь матчей из десяти. Спортивный обозреватель написал: «Перелом произошёл ровно с его приходом — значит, всё дело в нём». В той же статье упоминается, что в декабре из лазарета вернулись трое ведущих игроков.","answer_id":"post_hoc","distractors":["hasty_generalization","circular","gamblers_fallacy","false_authority"],"offer_none":true,"highlight":"Перелом произошёл ровно с его приходом — значит, всё дело в нём","explanation":"Победы последовали за приходом тренера, но одновременно изменились и другие факторы — вернулись лидеры команды. Вывод о причине сделан только на основании последовательности во времени, альтернативные объяснения не рассмотрены.","nearest_distractor":"hasty_generalization","contrast":"Обозреватель не обобщает частный случай на всех тренеров или все команды; он приписывает причину по совпадению во времени, игнорируя другие объяснения."},{"id":"q021","batch":1,"difficulty":3,"text":"После того как в районе открылся первый магазин крафтового пива, краж велосипедов во дворах стало больше. Местный блогер пишет: «Связь очевидна: магазин открылся в марте, а с апреля велосипеды пропадают вдвое чаще». Он не упоминает, что в апреле начинается велосезон и велосипеды вообще выносят из квартир.","answer_id":"post_hoc","distractors":["hasty_generalization","gamblers_fallacy","slippery_slope","misleading_statistics"],"offer_none":false,"highlight":"магазин открылся в марте, а с апреля велосипеды пропадают вдвое чаще","explanation":"Рост краж действительно следует за открытием магазина, но есть очевидное альтернативное объяснение — начало сезона, когда велосипедов во дворах становится больше. Последовательность во времени сама по себе связи не доказывает.","nearest_distractor":"hasty_generalization","contrast":"Блогер не делает вывода о «всех магазинах» по паре случаев; его ошибка — признать причиной событие, которое просто предшествовало росту краж."},{"id":"q022","batch":1,"difficulty":1,"text":"В рекламе витаминного комплекса известный актёр сериала говорит: «Я как человек, который сыграл хирурга в трёх сезонах, могу сказать: этот комплекс укрепляет иммунитет лучше любых лекарств». На экране — его фото в белом халате.","answer_id":"false_authority","distractors":["bandwagon","appeal_to_nature","genetic_fallacy","appeal_to_novelty"],"offer_none":false,"highlight":"Я как человек, который сыграл хирурга в трёх сезонах, могу сказать","explanation":"Роль врача не делает актёра экспертом в медицине. Утверждение об эффективности витаминов должно опираться на исследования, а не на известность и экранный образ.","nearest_distractor":"bandwagon","contrast":"Апелляция к большинству ссылается на «многих людей». Здесь ссылка на одного человека, чья известность выдаётся за компетентность."},{"id":"q023","batch":1,"difficulty":2,"text":"На форуме дачников спорят, когда сажать картофель. Один участник пишет: «Мой сосед — доктор физико-математических наук, он сказал, что сажать надо строго по лунному календарю. Человек с такой степенью не будет говорить ерунду».","answer_id":"false_authority","distractors":["appeal_to_tradition","bandwagon","appeal_to_nature","genetic_fallacy"],"offer_none":true,"highlight":"Человек с такой степенью не будет говорить ерунду","explanation":"Учёная степень по физике не делает человека знатоком агрономии. Компетентность в одной области переносится на другую, а сам совет подкреплён не данными об урожаях, а титулом соседа.","nearest_distractor":"appeal_to_tradition","contrast":"Лунный календарь — старинная практика, но участник обосновывает совет не тем, что «так всегда делали», а научной степенью соседа."},{"id":"q024","batch":1,"difficulty":3,"text":"В школьном чате родитель пишет: «Мой знакомый работает в министерстве, он говорит, что в следующем году ЕГЭ по математике отменят. Значит, можно не нанимать репетитора». Другие родители выяснили, что знакомый — водитель в министерском гараже, а официальных документов на эту тему нет.","answer_id":"false_authority","distractors":["hasty_generalization","bandwagon","genetic_fallacy","tu_quoque"],"offer_none":true,"highlight":"Мой знакомый работает в министерстве, он говорит, что в следующем году ЕГЭ по математике отменят","explanation":"Работа в министерстве не означает доступа к решениям об экзаменах. Источник выдаётся за осведомлённый только из-за места работы, а официальных подтверждений нет.","nearest_distractor":"none","contrast":"Ссылка на источник сама по себе не ошибка: если бы чиновник, отвечающий за экзамены, сослался на подписанный документ, довод был бы разумным. Ошибка в том, что компетентность приписана по формальному признаку — месту работы."},{"id":"q025","batch":1,"difficulty":1,"text":"Подруга уговаривает Катю купить модные широкие джинсы: «Да их сейчас все носят! Если столько людей их покупает, значит, они самые удобные».","answer_id":"bandwagon","distractors":["appeal_to_tradition","appeal_to_novelty","false_authority","hasty_generalization"],"offer_none":false,"highlight":"Если столько людей их покупает, значит, они самые удобные","explanation":"Популярность не доказывает удобства: люди покупают вещи из-за моды, рекламы, желания не отставать. Утверждение об удобстве не проверено, а выведено из количества покупателей.","nearest_distractor":"appeal_to_tradition","contrast":"Апелляция к традиции — «так делали всегда». Здесь — «так делают сейчас многие». Мода как раз новая, а не давняя.","pick_notes":{"appeal_to_novelty":"Модность джинсов тут ни при чём: подруга не говорит «это новое, значит лучшее». Её довод — «столько людей покупает», то есть число сторонников."}},{"id":"q026","batch":1,"difficulty":2,"text":"Реклама новой финансовой платформы: «Уже два миллиона россиян доверили нам свои сбережения. Неужели два миллиона человек могут ошибаться? Присоединяйтесь — ваши деньги будут в надёжных руках».","answer_id":"bandwagon","distractors":["false_authority","hasty_generalization","appeal_to_novelty","circular"],"offer_none":true,"highlight":"Неужели два миллиона человек могут ошибаться?","explanation":"Число клиентов говорит о популярности, но не о надёжности: её определяют лицензия, страхование вкладов, прозрачная отчётность. Финансовые пирамиды тоже собирали миллионы вкладчиков.","nearest_distractor":"false_authority","contrast":"Ложный авторитет опирается на мнение конкретного «эксперта». Здесь ссылка идёт не на специалиста, а на массу клиентов — довод держится на количестве."},{"id":"q027","batch":1,"difficulty":3,"text":"На совещании выбирают систему учёта. Менеджер говорит: «Девять из десяти наших конкурентов уже перешли на эту систему, а значит, она лучшая». Сравнивать системы по функциям и цене никто не стал.","answer_id":"bandwagon","distractors":["hasty_generalization","false_analogy","appeal_to_tradition","false_authority"],"offer_none":false,"highlight":"Девять из десяти наших конкурентов уже перешли на эту систему, а значит, она лучшая","explanation":"Распространённость решения среди конкурентов — повод его изучить, но не доказательство качества: конкуренты могли выбрать систему из-за скидки, моды или привычки. Вывод сделан только из того, что «так поступает большинство», а сравнение по существу не проводилось.","nearest_distractor":"hasty_generalization","contrast":"Проблема не в маленькой выборке — девять из десяти это почти все конкуренты. Проблема в том, что популярность решения выдаётся за довод о его пригодности."},{"id":"q028","batch":1,"difficulty":1,"text":"— Почему ты уверен, что этот сайт говорит правду? — Потому что там написано, что вся информация на сайте проверена и достоверна.","answer_id":"circular","distractors":["false_authority","appeal_to_ignorance","non_sequitur","bandwagon"],"offer_none":false,"highlight":"Потому что там написано, что вся информация на сайте проверена и достоверна","explanation":"Достоверность сайта доказывается словами самого сайта, то есть заранее предполагается то, что нужно доказать. Если сайту нельзя доверять, нельзя доверять и его заявлению о собственной достоверности.","nearest_distractor":"false_authority","contrast":"Ссылка на авторитет опирается на внешний источник. Здесь источник подтверждает сам себя — внешней проверки нет, круг замкнут.","pick_notes":{"non_sequitur":"Круг как раз «следует»: вывод тривиально вытекает из посылки, потому что он в ней уже содержится. Беда не в переходе, а в том, что такая посылка ничего не доказывает."}},{"id":"q029","batch":1,"difficulty":2,"text":"Отец объясняет сыну, почему нельзя опаздывать на тренировки: «Опаздывать нельзя, потому что приходить вовремя обязательно». Сын пожал плечами: «А почему обязательно?» — «Потому что опаздывать нельзя».","answer_id":"circular","distractors":["appeal_to_tradition","false_authority","non_sequitur","equivocation"],"offer_none":false,"highlight":"Опаздывать нельзя, потому что приходить вовремя обязательно","explanation":"«Опаздывать нельзя» и «приходить вовремя обязательно» — одно утверждение разными словами. Обоснование повторяет тезис, и на вопрос «почему» отец просто возвращается к началу.","nearest_distractor":"appeal_to_tradition","contrast":"Отец не ссылается на «так заведено»; он вообще не приводит внешней причины (например, травмы без разминки или уважение к команде), а лишь перефразирует тезис.","pick_notes":{"non_sequitur":"Круг как раз «следует»: вывод тривиально вытекает из посылки, потому что он в ней уже содержится. Беда не в переходе, а в том, что такая посылка ничего не доказывает."}},{"id":"q030","batch":1,"difficulty":3,"text":"Критик пишет в рецензии: «Этот роман — шедевр, потому что он написан великим писателем. А то, что автор — великий писатель, доказывает хотя бы то, что он создал такие шедевры, как этот роман».","answer_id":"circular","distractors":["false_authority","non_sequitur","bandwagon","affirming_consequent"],"offer_none":true,"highlight":"А то, что автор — великий писатель, доказывает хотя бы то, что он создал такие шедевры, как этот роман","explanation":"Величие романа выводится из величия автора, а величие автора — из величия этого же романа. Без независимого аргумента (язык, композиция, влияние на литературу) оба утверждения держатся только друг на друге.","nearest_distractor":"false_authority","contrast":"Первая половина фразы похожа на ссылку на авторитет, но этот «авторитет» тут же обосновывается обсуждаемым романом — круг замыкается.","pick_notes":{"non_sequitur":"Круг как раз «следует»: вывод тривиально вытекает из посылки, потому что он в ней уже содержится. Беда не в переходе, а в том, что такая посылка ничего не доказывает."}},{"id":"q031","batch":1,"difficulty":1,"text":"Жена спрашивает мужа, почему он опять не оплатил коммуналку и пришёл штраф. Муж отвечает: «Слушай, а ты видела, сколько сейчас стоит бензин? Вот где настоящий грабёж! Скоро на работу пешком ходить будем».","answer_id":"red_herring","distractors":["tu_quoque","straw_man","appeal_to_pity","loaded_question"],"offer_none":false,"highlight":"а ты видела, сколько сейчас стоит бензин? Вот где настоящий грабёж!","explanation":"Вопрос был про неоплаченную коммуналку, а муж переводит разговор на цены на бензин. Тема может быть болезненной, но к пропущенному платежу отношения не имеет.","nearest_distractor":"tu_quoque","contrast":"Муж не упрекает жену в том же самом («ты сама вечно забываешь платить») — он просто меняет тему."},{"id":"q032","batch":1,"difficulty":2,"text":"На пресс-конференции мэра спросили, почему ремонт моста затянулся на два года сверх срока. Мэр ответил: «Хочу напомнить, что за последние пять лет мы открыли двенадцать новых детских площадок и посадили три тысячи деревьев. Город меняется к лучшему».","answer_id":"red_herring","distractors":["straw_man","tu_quoque","appeal_to_pity","bandwagon"],"offer_none":true,"highlight":"за последние пять лет мы открыли двенадцать новых детских площадок и посадили три тысячи деревьев","explanation":"Достижения в других сферах могут быть реальными, но не объясняют задержку с мостом. Вопрос остаётся без ответа, а внимание переключается на приятную тему.","nearest_distractor":"straw_man","contrast":"Мэр не искажает вопрос журналиста и не спорит с выдуманной позицией — он просто отвечает на другой, удобный ему вопрос."},{"id":"q033","batch":1,"difficulty":3,"text":"Пассажир жалуется контролёру, что в электричке не работает отопление и люди мёрзнут. Контролёр отвечает: «А билет у вас, кстати, есть? Предъявите, пожалуйста». Пассажир полез за билетом, и об отоплении больше никто не вспоминал.","answer_id":"red_herring","distractors":["ad_hominem","tu_quoque","straw_man","loaded_question"],"offer_none":true,"highlight":"А билет у вас, кстати, есть? Предъявите, пожалуйста","explanation":"Проверка билета — законная обязанность контролёра, но в этом разговоре она используется, чтобы увести беседу от жалобы. Вопрос об отоплении остался без ответа.","nearest_distractor":"ad_hominem","contrast":"Контролёр не дискредитирует пассажира и не заявляет, что ему нельзя жаловаться. Если бы он сказал «Безбилетникам жаловаться не положено», это был бы переход на личность. Здесь — просто переключение темы."},{"id":"q034","batch":1,"difficulty":1,"text":"На упаковке чая для похудения крупно написано: «100% натуральный состав — только травы, никакой химии. Природа не может навредить!» В составе есть сенна — растение с сильным слабительным действием.","answer_id":"appeal_to_nature","distractors":["appeal_to_tradition","appeal_to_novelty","false_authority","bandwagon"],"offer_none":false,"highlight":"Природа не может навредить!","explanation":"Натуральность не гарантирует безопасности: бледная поганка, борщевик и та же сенна в больших дозах — тоже «природа». Действие вещества определяется его свойствами, а не происхождением.","nearest_distractor":"appeal_to_tradition","contrast":"Апелляция к традиции — «так делали предки». Здесь довод — «это природное», без всякой ссылки на давность."},{"id":"q035","batch":1,"difficulty":2,"text":"Фитнес-блогер пишет: «Человек миллионы лет не пил молоко после младенчества, это неестественно. Поэтому молочные продукты взрослым вредны». Под постом сотни благодарных комментариев.","answer_id":"appeal_to_nature","distractors":["appeal_to_tradition","false_authority","bandwagon","appeal_to_novelty"],"offer_none":true,"highlight":"это неестественно. Поэтому молочные продукты взрослым вредны","explanation":"Из того, что что-то «неестественно» (не встречалось в древности), не следует, что оно вредно. Вред или польза определяются исследованиями — и для людей с непереносимостью лактозы ответ действительно другой, — а не тем, как жили предки.","nearest_distractor":"appeal_to_tradition","contrast":"Ссылка на «миллионы лет» похожа на довод традицией, но блогер опирается не на обычай («так всегда делали»), а на противопоставление «естественное — полезно, неестественное — вредно». Решающее слово в рассуждении — «неестественно».","also_accepted":[{"id":"appeal_to_tradition","note":"Ссылка на «миллионы лет» действительно сближает довод с традицией. Но решающее слово — «неестественно»: вред выводится из неестественности."}]},{"id":"q036","batch":1,"difficulty":3,"text":"Родители спорят, стоит ли ставить ребёнку пломбу. Мама говорит: «Зачем пломба? Зубы — часть организма, а организм сам умеет восстанавливаться, нужно просто не мешать ему». Стоматолог объясняет, что эмаль не регенерирует.","answer_id":"appeal_to_nature","distractors":["hasty_generalization","division","appeal_to_tradition","false_authority"],"offer_none":false,"highlight":"организм сам умеет восстанавливаться, нужно просто не мешать ему","explanation":"Вмешательство отвергается как помеха природе, а естественный ход вещей объявляется заведомо правильным. Но не всё в организме восстанавливается само — кариес без лечения только прогрессирует.","nearest_distractor":"hasty_generalization","contrast":"Фраза «организм сам восстанавливается» — действительно обобщение (кожа и кости заживают, эмаль — нет). Но смысл довода в другом: лечение отвергается именно как вмешательство в естественный процесс.","also_accepted":[{"id":"division","note":"Верно подмечено: «организм восстанавливается, зубы — часть организма, значит, и зубы восстановятся» — это ошибка деления. Но вывод мамы — «не мешать организму», то есть природный ход вещей объявлен правильным, поэтому основной ярлык — апелляция к природе."}]},{"id":"q037","batch":1,"difficulty":1,"text":"Андрей купил билет в кино за восемьсот рублей. Через двадцать минут фильм показался ему скучным и неприятным, но он решил досидеть: «Деньги же заплачены, не пропадать же им».","answer_id":"sunk_cost","distractors":["gamblers_fallacy","false_dilemma","appeal_to_tradition","slippery_slope"],"offer_none":false,"highlight":"Деньги же заплачены, не пропадать же им","explanation":"Восемьсот рублей потрачены в любом случае — уйдёт Андрей или останется. Оставаясь, он лишь добавляет к потерянным деньгам ещё полтора часа неприятного времени. Решение должно зависеть от будущего, а не от уже потраченного.","nearest_distractor":"gamblers_fallacy","contrast":"Ошибка игрока — ожидание, что случайный исход «должен» смениться. Андрей не рассчитывает, что фильм станет лучше, он держится за уже потраченные деньги."},{"id":"q038","batch":1,"difficulty":2,"text":"Город уже вложил в строительство новой развязки четыре миллиарда, но экспертиза показала, что проект устарел и пробок не решит. На заседании прозвучало: «Мы не можем остановиться сейчас — иначе четыре миллиарда окажутся выброшенными на ветер. Нужно найти ещё два и достроить».","answer_id":"sunk_cost","distractors":["false_dilemma","slippery_slope","nirvana","appeal_to_fear"],"offer_none":true,"highlight":"Мы не можем остановиться сейчас — иначе четыре миллиарда окажутся выброшенными на ветер","explanation":"Четыре миллиарда уже не вернуть ни при каком решении. Вопрос только в том, принесут ли новые два миллиарда пользу, — а экспертиза говорит, что нет. Прошлые траты используются как довод для новых.","nearest_distractor":"false_dilemma","contrast":"Можно увидеть выбор «или достраиваем, или деньги пропали», но второй вариант описывает не альтернативу, а уже случившуюся потерю. Весь довод опирается на понесённые затраты — это и есть ключевая ошибка."},{"id":"q039","batch":1,"difficulty":3,"text":"Лена пять лет училась на юриста и два года работала по специальности, но работа ей не нравится. В свободное время она с удовольствием программирует и уже получила предложение стать младшим разработчиком. Мама возражает: «Ты что, хочешь, чтобы семь лет пошли псу под хвост?»","answer_id":"sunk_cost","distractors":["gamblers_fallacy","false_dilemma","appeal_to_tradition","appeal_to_pity"],"offer_none":true,"highlight":"Ты что, хочешь, чтобы семь лет пошли псу под хвост?","explanation":"Годы учёбы и работы уже прожиты, и смена профессии их не отменит (часть навыков ещё и пригодится). Решать нужно, глядя в будущее: какая работа принесёт Лене больше удовлетворения и дохода. Мама же опирается на прошлые вложения.","nearest_distractor":"none","contrast":"Довод был бы разумным, если бы мама говорила о будущем: например, что в юриспруденции у Лены выше доход или что начинать с нуля рискованно. Но она апеллирует именно к уже потраченному времени."},{"id":"q040","batch":1,"difficulty":1,"text":"Невестка предложила на Новый год вместо оливье приготовить запечённые овощи и пару новых салатов. Свекровь отрезала: «У нас в семье оливье на Новый год делали всегда, и при моей маме, и при бабушке. Значит, так и правильно».","answer_id":"appeal_to_tradition","distractors":["bandwagon","appeal_to_nature","appeal_to_novelty","genetic_fallacy"],"offer_none":false,"highlight":"оливье на Новый год делали всегда, и при моей маме, и при бабушке. Значит, так и правильно","explanation":"Давность обычая объясняет, почему его соблюдают, но не доказывает, что он лучше альтернатив. Хотеть сохранить традицию — нормально; ошибка — выдавать её за доказательство «правильности».","nearest_distractor":"bandwagon","contrast":"Свекровь ссылается не на то, что так делают «все», а на то, что так делали всегда в прошлом."},{"id":"q041","batch":1,"difficulty":2,"text":"Главный инженер завода отклонил предложение перейти с бумажных журналов на электронный учёт: «Мы сорок лет ведём журналы от руки, и завод стоит. Зачем ломать то, что работает?»","answer_id":"appeal_to_tradition","distractors":["sunk_cost","appeal_to_novelty","post_hoc","bandwagon"],"offer_none":true,"highlight":"Мы сорок лет ведём журналы от руки, и завод стоит","explanation":"То, что завод работает, не доказывает, что бумажные журналы — лучший вариант: возможно, электронный учёт сэкономил бы время и сократил число ошибок. Сорок лет практики — аргумент о привычке, а не об эффективности.","nearest_distractor":"none","contrast":"Осторожность при смене работающих процессов разумна, и довод был бы корректным с конкретикой: стоимость перехода, риск сбоев, обучение персонала. Но инженер ничего из этого не приводит и опирается только на сорок лет привычки."},{"id":"q042","batch":1,"difficulty":3,"text":"В деревне спорят, нужен ли вывоз мусора по графику вместо сжигания в оврагах. Староста говорит: «Деды жгли, отцы жгли, и мы жгли. Значит, ничего страшного в этом нет, а ваши контейнеры — городские выдумки». Прошлым летом от такого костра сгорел сарай.","answer_id":"appeal_to_tradition","distractors":["appeal_to_nature","bandwagon","ad_hominem","appeal_to_novelty"],"offer_none":false,"highlight":"Деды жгли, отцы жгли, и мы жгли. Значит, ничего страшного в этом нет","explanation":"Давность практики выдаётся за доказательство её безопасности. Вред от сжигания мусора — дым, пожары, как с тем сараем, — не исчезает оттого, что так делали поколениями.","nearest_distractor":"appeal_to_nature","contrast":"Староста не утверждает, что сжигание «естественно» или «природно»; он опирается на то, что так делали всегда. Пренебрежительное «городские выдумки» — отдельный выпад в духе генетической ошибки (идею отвергают по происхождению), но главный довод старосты — о давности."},{"id":"q043","batch":1,"difficulty":1,"text":"Виктор играет в рулетку и уже семь раз подряд ставил на чёрное — и семь раз выпадало красное. Он удваивает ставку: «Ну теперь-то чёрное точно выпадет, сколько можно красному!»","answer_id":"gamblers_fallacy","distractors":["sunk_cost","hasty_generalization","post_hoc","survivorship"],"offer_none":false,"highlight":"Ну теперь-то чёрное точно выпадет, сколько можно красному!","explanation":"Каждое вращение рулетки не зависит от предыдущих: шарик «не помнит» прошлых результатов. Вероятность чёрного на восьмом вращении такая же, как на первом.","nearest_distractor":"sunk_cost","contrast":"Невозвратные затраты — «уже столько вложил, нельзя бросать». Виктор же рассчитывает, что серия красных повышает шансы чёрного, — это ошибка в понимании вероятности."},{"id":"q044","batch":1,"difficulty":2,"text":"У супругов три дочери, и они ждут четвёртого ребёнка. Соседка уверенно говорит: «Ну уж теперь-то точно будет мальчик — по закону вероятности не может же быть четыре девочки подряд!»","answer_id":"gamblers_fallacy","distractors":["hasty_generalization","post_hoc","misleading_statistics","appeal_to_nature"],"offer_none":true,"highlight":"по закону вероятности не может же быть четыре девочки подряд","explanation":"Пол каждого следующего ребёнка практически не зависит от пола предыдущих: шансы примерно равны при каждой беременности. Серия из четырёх девочек редка заранее, но когда три уже родились, вероятность для четвёртого ребёнка остаётся прежней.","nearest_distractor":"hasty_generalization","contrast":"Соседка не делает общего вывода по малой выборке; она считает, что прошлые независимые исходы влияют на следующий."},{"id":"q045","batch":1,"difficulty":3,"text":"Ольга каждую неделю покупает лотерейный билет с одной и той же комбинацией. «Эти числа не выпадали уже три года, — рассуждает она. — Значит, они назрели, и шансы у моей комбинации с каждой неделей всё выше». Тираж разыгрывается лотерейным барабаном, шары каждый раз перемешиваются заново.","answer_id":"gamblers_fallacy","distractors":["sunk_cost","hasty_generalization","appeal_to_tradition","survivorship"],"offer_none":false,"highlight":"Значит, они назрели, и шансы у моей комбинации с каждой неделей всё выше","explanation":"Каждый тираж независим, и вероятность выпадения комбинации одинакова каждую неделю. Числа не «назревают»: барабан не знает, что выпадало раньше.","nearest_distractor":"sunk_cost","contrast":"Можно подумать, что Ольга держится за комбинацию из-за трёх лет вложений. Но её довод — «шансы растут», а это ошибка игрока. Если бы она сказала «я столько вложила в эти числа, менять нельзя», это были бы невозвратные затраты."},{"id":"q046","batch":1,"difficulty":2,"text":"Врач-кардиолог говорит пациенту на приёме: «По результатам вашей ЭКГ и анализа на холестерин риск инфаркта у вас повышен. Рекомендую сократить жирное и начать принимать препарат, который я выписала». Пациент записал рекомендации.","answer_id":"none","distractors":["false_authority","slippery_slope","hasty_generalization","appeal_to_fear"],"offer_none":true,"highlight":"По результатам вашей ЭКГ и анализа на холестерин риск инфаркта у вас повышен","explanation":"Кардиолог — эксперт именно в этой области, а вывод опирается на конкретные данные обследования, а не только на статус. Доверять профильному специалисту, который обосновывает мнение данными, — разумно.","nearest_distractor":"false_authority","contrast":"Ложный авторитет — когда ссылаются на человека вне его компетенции или ставят статус на место доказательств. Здесь и компетенция профильная, и доказательства (ЭКГ, анализы) названы."},{"id":"q047","batch":1,"difficulty":2,"text":"Дежурный по станции говорит пассажиру: «Поезда на этой ветке ходят с интервалом пятнадцать минут. Предыдущий ушёл двенадцать минут назад — значит, следующий будет минуты через три». Через три минуты поезд действительно пришёл.","answer_id":"none","distractors":["gamblers_fallacy","post_hoc","hasty_generalization","affirming_consequent"],"offer_none":true,"highlight":"Предыдущий ушёл двенадцать минут назад — значит, следующий будет минуты через три","explanation":"Поезда — не случайные события, а движение по расписанию с известным интервалом. Здесь прошлое действительно определяет будущее, и вывод дежурного корректен.","nearest_distractor":"gamblers_fallacy","contrast":"Похоже на ошибку игрока («давно не было — значит, скоро будет»), но ошибка игрока касается только независимых случайных событий. Расписание делает события зависимыми."},{"id":"q048","batch":1,"difficulty":3,"text":"Жильцы обсуждают, стоит ли менять старый лифт. Председатель ТСЖ говорит: «Ремонт этого лифта обходится нам в двести тысяч в год, а новый стоит миллион и прослужит двадцать пять лет без капитального ремонта. Уже через пять-шесть лет замена окупится». Решили собирать деньги на новый лифт.","answer_id":"none","distractors":["sunk_cost","false_dilemma","appeal_to_tradition","appeal_to_novelty"],"offer_none":true,"highlight":"Уже через пять-шесть лет замена окупится","explanation":"Председатель сравнивает будущие расходы при обоих вариантах и выбирает выгодный. Он не ссылается на то, сколько уже вложено в старый лифт, и не утверждает, что вариантов только два из-за невозможности других, — он просто считает.","nearest_distractor":"sunk_cost","contrast":"Ошибка невозвратных затрат была бы, если бы кто-то сказал: «Мы уже столько вложили в ремонт старого лифта, нельзя его выбрасывать». Председатель смотрит только вперёд — это правильный подход."},{"id":"q049","batch":1,"difficulty":3,"text":"На дебатах кандидат заявил, что городской бюджет на образование вырос на двадцать процентов. Его соперница ответила: «Вы называете номинальный рост, но инфляция за тот же период составила двадцать пять процентов. В реальных ценах финансирование сократилось». Зал зашумел.","answer_id":"none","distractors":["red_herring","straw_man","ad_hominem","misleading_statistics"],"offer_none":true,"highlight":"Вы называете номинальный рост, но инфляция за тот же период составила двадцать пять процентов","explanation":"Соперница не переходит на личность и не подменяет тему: она отвечает на конкретный тезис оппонента и указывает на неучтённый фактор. Это корректное опровержение.","nearest_distractor":"red_herring","contrast":"Отвлекающий манёвр уводит к посторонней теме. Инфляция — не посторонняя тема, а прямое уточнение к цифре оппонента: без неё рост бюджета просто нельзя оценить."},{"id":"q050","batch":1,"difficulty":1,"text":"Синоптики дают на завтра девяностопроцентную вероятность сильного дождя. Таня перенесла пикник на воскресенье, когда обещают солнце: «Прогноз не всегда точен, но рисковать при девяноста процентах глупо».","answer_id":"none","distractors":["false_authority","bandwagon","false_dilemma","appeal_to_fear"],"offer_none":true,"highlight":"рисковать при девяноста процентах глупо","explanation":"Таня опирается на профильный источник (метеослужбу), понимает, что прогноз вероятностный, и делает разумный выбор с учётом риска.","nearest_distractor":"false_authority","contrast":"Синоптики — эксперты именно в погоде, и Таня не считает их слова непогрешимыми. Это обоснованное доверие специалистам, а не апелляция к ложному авторитету."},{"id":"q051","batch":2,"difficulty":1,"text":"На уроке истории девятиклассник заявил, что отказывается жить по семидневной неделе: «Неделю придумали древние вавилоняне, которые гадали по печени жертвенных овец. Значит, и сама неделя — суеверная чушь». Учительница предложила ему тогда приходить в школу по собственному календарю.","answer_id":"genetic_fallacy","distractors":["ad_hominem","appeal_to_novelty","appeal_to_tradition","tu_quoque"],"offer_none":false,"highlight":"Неделю придумали древние вавилоняне, которые гадали по печени жертвенных овец. Значит, и сама неделя — суеверная чушь","explanation":"Происхождение недели ничего не говорит о её нынешней пользе: семидневный цикл удобен для работы и отдыха независимо от верований тех, кто его ввёл. Идею отвергают по её родословной, а не по содержанию.","nearest_distractor":"ad_hominem","contrast":"Переход на личность — атака на оппонента в споре. Вавилоняне ни с кем не спорят: здесь отвергается сама идея из-за того, откуда она взялась, — это генетическая ошибка."},{"id":"q052","batch":2,"difficulty":2,"text":"На публичных слушаниях о запуске беспилотных автобусов один житель заявил: «Технологии автопилота изначально разрабатывали для армии. Военному изобретению не место на мирных улицах!» Интернет, кстати, тоже вырос из сети, построенной на деньги военного ведомства США, но на слушания все пришли по объявлению на сайте мэрии.","answer_id":"genetic_fallacy","distractors":["appeal_to_fear","ad_hominem","appeal_to_novelty","false_analogy"],"offer_none":true,"highlight":"Технологии автопилота изначально разрабатывали для армии. Военному изобретению не место на мирных улицах!","explanation":"Безопасность беспилотного автобуса определяется испытаниями, надёжностью и правилами движения, а не тем, кто финансировал первые разработки. Как ехидно подмечено в сценке, интернет тоже вырос из сети ARPANET, которую финансировало военное ведомство (хотя строили её университетские учёные).","nearest_distractor":"appeal_to_fear","contrast":"Житель не пугает последствиями («автобусы будут сбивать пешеходов») — он отвергает технологию из-за её происхождения. Если бы он рисовал страшную картину аварий без доказательств, это была бы апелляция к страху."},{"id":"q053","batch":2,"difficulty":1,"text":"На родительском собрании активная мама спросила директора: «Скажите честно, сколько ещё вы собираетесь закрывать глаза на травлю в шестом „Б“?» Директор растерялся: о травле в этом классе он слышал впервые, и ни одной жалобы к нему не поступало.","answer_id":"loaded_question","distractors":["false_premise","straw_man","red_herring","appeal_to_fear"],"offer_none":false,"highlight":"сколько ещё вы собираетесь закрывать глаза на травлю в шестом „Б“?","explanation":"В вопрос встроены два недоказанных утверждения: что травля есть и что директор о ней знает и бездействует. Любой прямой ответ («ещё месяц», «больше не буду») их подтверждает. Честный ход — сначала выяснить, есть ли травля.","nearest_distractor":"false_premise","contrast":"Ложное основание — когда рассуждение открыто строится на недоказанной посылке. В сложном вопросе посылка спрятана в самой форме вопроса: её не утверждают, а подразумевают, и любой ответ невольно её признаёт."},{"id":"q054","batch":2,"difficulty":2,"text":"Таможенник долго листает паспорт и строго спрашивает: «Контрабанду вы обычно в чемодане провозите или в сумке?» Турист, впервые выехавший за границу, мучительно пытается ответить честно.","answer_id":"loaded_question","distractors":["false_dilemma","false_premise","straw_man","appeal_to_fear"],"offer_none":true,"highlight":"Контрабанду вы обычно в чемодане провозите или в сумке?","explanation":"Вопрос заранее предполагает, что турист возит контрабанду, и предлагает уточнить лишь способ. Ответ «в чемодане» или «в сумке» — признание. Единственный честный ответ отвергает само допущение: «Я не вожу контрабанду».","nearest_distractor":"false_dilemma","also_accepted":[{"id":"false_dilemma","note":"Выбор «в чемодане или в сумке» действительно ложная дилемма: пропущен вариант «никак». Но корень ловушки — в допущении, заложенном в вопрос, поэтому точнее «сложный вопрос»."}],"contrast":"Выбор из двух вариантов похож на ложную дилемму, но главная ловушка не в числе вариантов: любой из них признаёт, что контрабанду турист возит.","pick_notes":{"false_premise":"Допущение «вы возите контрабанду» действительно ничем не обосновано. Но таможенник ничего из него не выводит — он прячет его в вопрос, чтобы любой ответ стал признанием. Это и есть сложный вопрос."}},{"id":"q055","batch":2,"difficulty":1,"text":"— Ни один настоящий рыбак не уходит с озера без улова, — заявил дядя Коля. — Так ты же вчера вернулся пустой, — напомнила жена. — Вчера я просто воздухом дышал, а не рыбачил по-настоящему.","answer_id":"no_true_scotsman","distractors":["special_pleading","equivocation","hasty_generalization","circular"],"offer_none":false,"highlight":"Вчера я просто воздухом дышал, а не рыбачил по-настоящему","explanation":"Когда появился контрпример — сам дядя Коля без улова, — он не пересматривает утверждение, а задним числом переопределяет «рыбалку». Теперь утверждение нельзя опровергнуть: любой неудачник просто «не рыбачил по-настоящему».","nearest_distractor":"special_pleading","contrast":"Двойные стандарты — когда себе явно разрешают то, что запрещают другим. Дядя Коля не делает себе исключения из правила: он меняет определение, чтобы его неудача под правило не попадала."},{"id":"q056","batch":2,"difficulty":3,"text":"Блогер пишет: «Вегетарианцы не бывают агрессивными — растительное питание исключает злость». В комментариях ему приводят пример известного вспыльчивого вегетарианца. Блогер отвечает: «Если он злился, значит, он не был истинным вегетарианцем: истинный отказывается от мяса ради доброты, а не ради диеты».","answer_id":"no_true_scotsman","distractors":["equivocation","circular","special_pleading","hasty_generalization"],"offer_none":true,"highlight":"Если он злился, значит, он не был истинным вегетарианцем","explanation":"Вегетарианец — человек, который не ест мяса. Получив контрпример, блогер добавляет к определению новое условие («ради доброты»), подогнанное так, чтобы его обобщение стало неопровержимым.","nearest_distractor":"equivocation","contrast":"При подмене понятий слово незаметно меняет смысл по ходу рассуждения. Здесь смысл меняют открыто и задним числом, чтобы спасти обобщение от неудобного примера, — это и отличает «настоящего шотландца»."},{"id":"q057","batch":2,"difficulty":1,"text":"Начальник отдела разослал письмо: «Опаздывать на совещания недопустимо — это неуважение к коллегам». На следующее совещание он сам пришёл на двадцать минут позже. «У меня была важная встреча с руководством, это другое», — пояснил он, хотя у троих опоздавших накануне тоже были встречи с клиентами.","answer_id":"special_pleading","distractors":["tu_quoque","no_true_scotsman","red_herring","ad_hominem"],"offer_none":false,"highlight":"У меня была важная встреча с руководством, это другое","explanation":"Правило объявлено для всех, но для себя начальник делает исключение по причине, которая была и у других: у опоздавших тоже были рабочие встречи. Чем его случай отличается по существу, не объяснено.","nearest_distractor":"tu_quoque","contrast":"«Сам такой» сказали бы подчинённые, отвергая правило из-за опоздания начальника. Здесь ошибается сам начальник: он применяет правило ко всем, кроме себя."},{"id":"q058","batch":2,"difficulty":2,"text":"Соседка возмущается в домовом чате: «Кто-то опять оставил коляску на лестничной площадке! Это запрещено, тут проход для пожарных!» Через неделю на той же площадке появился её велосипед. «Я его ненадолго поставила, и он аккуратный, не то что эти коляски».","answer_id":"special_pleading","distractors":["tu_quoque","no_true_scotsman","appeal_to_pity","red_herring"],"offer_none":true,"highlight":"Я его ненадолго поставила, и он аккуратный, не то что эти коляски","explanation":"Пожарному проходу всё равно, коляска на площадке или аккуратный велосипед. Соседка не показывает, чем её случай отличается по существу, — она просто освобождает себя от правила, которого требует от других.","nearest_distractor":"tu_quoque","contrast":"«Сам такой» — это довод в споре: «ты сам так делаешь, так что не указывай». Здесь соседку никто не упрекает; она сама придумывает для себя исключение — это двойные стандарты."},{"id":"q059","batch":2,"difficulty":1,"text":"Звонок с незнакомого номера: «Ваш компьютер заражён, банковские данные уже утекают! Если в течение десяти минут не установите нашу защитную программу, вы потеряете все сбережения». Ссылку на программу собеседник обещает прислать в мессенджер.","answer_id":"appeal_to_fear","distractors":["slippery_slope","false_dilemma","appeal_to_consequences","false_authority"],"offer_none":false,"highlight":"Если в течение десяти минут не установите нашу защитную программу, вы потеряете все сбережения","explanation":"Никаких доказательств заражения нет — есть только угроза и спешка. Решение навязывают страхом, а не доводами: классическая схема телефонных мошенников.","nearest_distractor":"slippery_slope","contrast":"Скользкая дорожка — цепочка «одно потянет за собой другое». Здесь цепочки нет: одна прямая угроза и требование действовать немедленно."},{"id":"q060","batch":2,"difficulty":3,"text":"Производитель бутилированной воды запустил рекламу: «Знаете ли вы, что течёт из вашего крана? Хлор, тяжёлые металлы, ржавые трубы. Подумайте о детях, пока не поздно». Результаты анализов водопроводной воды город публикует каждый месяц, но в рекламе о них ни слова.","answer_id":"appeal_to_fear","distractors":["appeal_to_pity","appeal_to_consequences","appeal_to_nature","bandwagon"],"offer_none":true,"highlight":"Подумайте о детях, пока не поздно","explanation":"Реклама рисует пугающую картину и давит на заботу о детях, но не приводит ни одного измерения. Если бы вода была опасна, это показали бы анализы — а они есть и публикуются.","nearest_distractor":"appeal_to_pity","contrast":"Упоминание детей здесь не вызывает сочувствия к кому-то, а пугает последствиями: эмоция — страх, а не жалость."},{"id":"q061","batch":2,"difficulty":1,"text":"Студент на пересдаче не ответил ни на один вопрос билета. «Поставьте, пожалуйста, хотя бы тройку, — просит он. — Я всю ночь не спал, бабушка болеет, а если меня отчислят, мама этого не переживёт».","answer_id":"appeal_to_pity","distractors":["appeal_to_fear","red_herring","appeal_to_consequences","special_pleading"],"offer_none":false,"highlight":"Я всю ночь не спал, бабушка болеет, а если меня отчислят, мама этого не переживёт","explanation":"Оценка должна отражать знания, а студент просит её за сочувствие. Бессонная ночь и болезнь бабушки могут быть правдой, но знаний предмета не добавляют. Попросить перенести экзамен по уважительной причине было бы честным доводом.","nearest_distractor":"appeal_to_fear","contrast":"Студент не угрожает экзаменатору, а давит на жалость: «пожалейте меня и мою семью». Апелляция к страху звучала бы иначе: «Поставите двойку — пожалуюсь в ректорат»."},{"id":"q062","batch":2,"difficulty":2,"text":"Адвокат в суде над директором фирмы, обвиняемым в растрате, говорит: «Мой подзащитный — отец троих детей, двадцать лет помогал детскому дому и в прошлом году перенёс операцию на сердце». Ни одного довода о том, куда на самом деле ушли деньги фирмы, защита не привела.","answer_id":"appeal_to_pity","distractors":["red_herring","appeal_to_fear","false_authority","tu_quoque"],"offer_none":true,"highlight":"Мой подзащитный — отец троих детей, двадцать лет помогал детскому дому и в прошлом году перенёс операцию на сердце","explanation":"Сочувствие к подсудимому может быть уместно при выборе наказания, но не при решении, виновен ли он. На вопрос «куда ушли деньги» защита отвечает поводами для жалости.","nearest_distractor":"red_herring","also_accepted":[{"id":"red_herring","note":"Это действительно уход от вопроса — апелляция к жалости вообще частный случай отвлечения. Но когда отвлечение держится именно на сочувствии, точнее назвать его апелляцией к жалости."}],"contrast":"Это тоже уход от вопроса, но особого рода: внимание переводят на страдания и заслуги подсудимого, чтобы вызвать сочувствие."},{"id":"q063","batch":2,"difficulty":2,"text":"Отец двух школьников прочитал статью о том, что смартфоны в начальной школе ухудшают концентрацию. «Чушь, — сказал он жене. — Если это правда, придётся отбирать у детей телефоны, а это будет война на месяц. Значит, статья ерунда».","answer_id":"appeal_to_consequences","distractors":["appeal_to_fear","slippery_slope","fallacy_fallacy","nirvana"],"offer_none":false,"highlight":"Если это правда, придётся отбирать у детей телефоны, а это будет война на месяц. Значит, статья ерунда","explanation":"Неприятные последствия правды никак не влияют на то, правда ли это. Влияние смартфонов на концентрацию проверяется исследованиями, а не тем, удобно ли с этим жить.","nearest_distractor":"appeal_to_fear","contrast":"Отца никто не запугивает — он сам отвергает факт, потому что следствия ему неприятны. Апелляция к страху — давление на собеседника угрозой; здесь же истинность подменяется желательностью."},{"id":"q064","batch":2,"difficulty":2,"text":"Астрономы сообщили, что через двадцать лет крупный астероид пройдёт в опасной близости от Земли. Ведущий ток-шоу возмутился: «Это не может быть правдой — тогда получается, что все наши планы на будущее бессмысленны! Я в такое верить отказываюсь».","answer_id":"appeal_to_consequences","distractors":["appeal_to_fear","false_authority","appeal_to_ignorance","slippery_slope"],"offer_none":true,"highlight":"Это не может быть правдой — тогда получается, что все наши планы на будущее бессмысленны!","explanation":"То, что последствия были бы ужасны, не делает факт менее вероятным. Орбиту проверяют наблюдениями, а не тем, насколько она нас пугает. К тому же двадцать лет — время, чтобы что-то предпринять, а не повод отрицать.","nearest_distractor":"appeal_to_fear","contrast":"Здесь никто не использует страх, чтобы склонить к решению. Ведущий сам отвергает утверждение, потому что его последствия неприемлемы."},{"id":"q065","batch":2,"difficulty":1,"text":"Консультант в магазине бытовой техники: «Берите эту стиральную машину — модель этого года! Прошлогоднюю брать нет смысла, она уже устарела». Характеристики двух машин в каталоге совпадают до последней цифры, только новая на треть дороже.","answer_id":"appeal_to_novelty","distractors":["appeal_to_tradition","bandwagon","false_authority","appeal_to_nature"],"offer_none":false,"highlight":"модель этого года! Прошлогоднюю брать нет смысла, она уже устарела","explanation":"Новизна сама по себе не делает машину лучше — характеристики одинаковы. Покупатель переплатил бы треть цены только за год выпуска.","nearest_distractor":"appeal_to_tradition","contrast":"Это зеркальная ошибка. Апелляция к традиции говорит «старое — значит проверенное», апелляция к новизне — «новое — значит лучшее». Консультант превозносит именно новизну."},{"id":"q066","batch":2,"difficulty":2,"text":"Новый директор школы объявил: «Отказываемся от бумажных учебников по всем предметам — на дворе двадцать первый век, пора жить по-современному». На вопрос учителей, есть ли данные, что дети лучше учатся по планшетам, директор ответил, что это и так понятно.","answer_id":"appeal_to_novelty","distractors":["bandwagon","appeal_to_tradition","appeal_to_nature","nirvana"],"offer_none":true,"highlight":"на дворе двадцать первый век, пора жить по-современному","explanation":"«Двадцать первый век» — не довод. Может быть, планшеты и лучше, но это надо показать: сравнить результаты, учесть зрение, отвлекаемость, стоимость. Директор заменяет доказательство ссылкой на современность.","nearest_distractor":"bandwagon","contrast":"Директор не говорит «все школы так делают» — он опирается на сам факт новизны."},{"id":"q067","batch":2,"difficulty":2,"text":"Журнал о здоровье пишет: «Исследование показало: люди, которые пьют больше кофе, живут дольше. Пейте больше кофе — и проживёте дольше!» Авторы самого исследования предупреждали, что кофе чаще пьют более обеспеченные люди с лучшим доступом к медицине.","answer_id":"cum_hoc","distractors":["post_hoc","hasty_generalization","false_authority","affirming_consequent"],"offer_none":false,"highlight":"Пейте больше кофе — и проживёте дольше!","explanation":"Связь между кофе и долголетием наблюдается, но причину она не доказывает: оба могут зависеть от третьего фактора — достатка и доступа к врачам. Сами авторы на это указывали.","nearest_distractor":"post_hoc","contrast":"«После — значит вследствие» опирается на порядок событий во времени. Здесь порядка нет вовсе: два явления просто встречаются вместе, и из этого выводят причину."},{"id":"q068","batch":2,"difficulty":1,"text":"Мэр приморского городка заметил: в дни, когда на пляже продают больше всего мороженого, спасатели вытаскивают из моря больше всего тонущих. «Мороженое явно провоцирует несчастные случаи», — заключил он и предложил ограничить продажу эскимо.","answer_id":"cum_hoc","distractors":["post_hoc","slippery_slope","hasty_generalization","false_analogy"],"offer_none":false,"highlight":"Мороженое явно провоцирует несчастные случаи","explanation":"Оба явления вызывает третья причина — жара: в жаркие дни больше едят мороженого и больше купаются. Совместность — ещё не причинность.","nearest_distractor":"post_hoc","contrast":"Мэр не говорит «сначала съели мороженое, потом начали тонуть»; он видит, что два показателя растут вместе, и делает вывод о причине."},{"id":"q069","batch":2,"difficulty":1,"text":"Фитнес-клуб выкладывает на сайте только восторженные отзывы. Когда Олег написал про сломанный душ и грубого администратора, его отзыв так и не появился. «Все наши клиенты довольны!» — гласит заголовок страницы.","answer_id":"cherry_picking","distractors":["hasty_generalization","bandwagon","misleading_statistics","false_authority"],"offer_none":false,"highlight":"«Все наши клиенты довольны!»","explanation":"Вывод «все довольны» сделан по отзывам, из которых недовольные удалены. Данные отобраны так, чтобы подтвердить нужный вывод.","nearest_distractor":"hasty_generalization","contrast":"Поспешное обобщение — вывод по слишком малой выборке. Здесь дело не в размере: недовольные отзывы были, но их убрали. Выборку подогнали под ответ."},{"id":"q070","batch":2,"difficulty":3,"text":"Автор новой диеты публикует фото «до и после» шести учеников, сбросивших по десять килограммов. «Метод работает у всех!» — пишет он. О двенадцати других, которые бросили диету через неделю или вернули вес, в посте ни слова, хотя он лично вёл всех восемнадцать.","answer_id":"cherry_picking","distractors":["survivorship","hasty_generalization","bandwagon","post_hoc"],"offer_none":true,"highlight":"«Метод работает у всех!»","explanation":"Автор знает обо всех восемнадцати участниках, но показывает только шестерых успешных. Неудачные случаи у него есть — он их сознательно не приводит.","nearest_distractor":"survivorship","contrast":"Ошибка выжившего — когда неудачников не видно и о них просто не знают. Здесь автор вёл всех и знает о двенадцати неудачах: он отбирает данные намеренно. Это выборочные факты."},{"id":"q071","batch":2,"difficulty":2,"text":"На встрече со студентами приглашённый спикер-миллионер рассказывает: «Я бросил университет на втором курсе и открыл своё дело. Посмотрите на самых богатых людей мира — многие из них тоже не доучились. Образование только мешает успеху».","answer_id":"survivorship","distractors":["hasty_generalization","false_authority","bandwagon","post_hoc"],"offer_none":false,"highlight":"Посмотрите на самых богатых людей мира — многие из них тоже не доучились.","explanation":"Мы видим немногих бросивших учёбу, кто разбогател, и не видим тысяч бросивших, кто ничего не добился, — о них не пишут в журналах. Вывод сделан только по «выжившим».","nearest_distractor":"hasty_generalization","contrast":"Дело не только в малом числе примеров: выборка устроена так, что неудачники в неё в принципе не попадают. Это особый вид смещённой выборки — ошибка выжившего."},{"id":"q072","batch":2,"difficulty":3,"text":"Бабушка Вера уверена: «Раньше вещи делали на века. У меня на даче и холодильник „ЗИЛ“, и швейная машинка, и утюг — всё шестидесятых годов, и всё до сих пор работает, а нынешние через пять лет ломаются». Соседка вспоминает, что почти вся техника тех лет давно отправилась на свалку.","answer_id":"survivorship","distractors":["appeal_to_tradition","hasty_generalization","appeal_to_novelty","misleading_statistics"],"offer_none":true,"highlight":"всё шестидесятых годов, и всё до сих пор работает","explanation":"До наших дней дожили только самые удачные экземпляры старой техники; миллионы сломавшихся давно на свалке, и их не видно. Сравнивать уцелевшие старые вещи со всеми новыми — ошибка выжившего.","nearest_distractor":"appeal_to_tradition","also_accepted":[{"id":"hasty_generalization","note":"Три вещи — действительно маленькая выборка. Но главное не размер, а то, как выборка устроена: в неё попали только уцелевшие вещи, поэтому точнее «ошибка выжившего»."}],"contrast":"Бабушка не говорит «так делали всегда — значит, правильно». Она судит о качестве по уцелевшим вещам, не видя выбывших."},{"id":"q073","batch":2,"difficulty":1,"text":"Заголовок новостного сайта: «Число нападений акул у побережья выросло на 200%!» Из текста статьи следует, что в прошлом году было одно нападение, а в этом — три, и все без серьёзных последствий.","answer_id":"misleading_statistics","distractors":["appeal_to_fear","cherry_picking","hasty_generalization","gamblers_fallacy"],"offer_none":false,"highlight":"Число нападений акул у побережья выросло на 200%!","explanation":"Формально рост с одного до трёх — это 200%. Но относительный рост на крошечной базе создаёт впечатление нашествия акул, хотя речь о трёх случаях за год.","nearest_distractor":"appeal_to_fear","contrast":"Заголовок пугает, но ничем не угрожает и ничего не требует. Трюк — в подаче цифры: проценты от крошечной базы."},{"id":"q074","batch":2,"difficulty":3,"text":"Компания по продаже ёлочных игрушек хвастается в отчёте: «Наша выручка в декабре выросла в три раза по сравнению с ноябрём!» По таблице в конце того же отчёта видно, что прошлый декабрь был заметно успешнее нынешнего.","answer_id":"misleading_statistics","distractors":["cherry_picking","post_hoc","hasty_generalization","cum_hoc"],"offer_none":true,"highlight":"Наша выручка в декабре выросла в три раза по сравнению с ноябрём!","explanation":"База сравнения выбрана так, чтобы впечатлить: для ёлочных игрушек декабрь всегда в разы сильнее ноября. Честное сравнение — с прошлым декабрём, а оно показывает падение.","nearest_distractor":"cherry_picking","also_accepted":[{"id":"cherry_picking","note":"Выбор удобного месяца для сравнения — это отчасти и отбор фактов. Но данные никто не скрывает (прошлый декабрь есть в том же отчёте), трюк в подаче цифры — поэтому точнее «манипуляция статистикой»."}],"contrast":"Цифра верная, и данные не спрятаны. Манипуляция — в выборе базы сравнения: сезонный рост выдаётся за успех."},{"id":"q075","batch":2,"difficulty":1,"text":"На викторине в баре двое участников спорят: один уверяет, что у паука восемь ног, другой — что шесть. Ведущий, не желая никого обидеть, решает: «Истина, как обычно, посередине — засчитаем семь».","answer_id":"middle_ground","distractors":["false_dilemma","bandwagon","nirvana","appeal_to_pity"],"offer_none":false,"highlight":"Истина, как обычно, посередине — засчитаем семь","explanation":"Среднее между верным и неверным ответом не становится верным. У паука восемь ног, и это проверяется подсчётом, а не компромиссом.","nearest_distractor":"false_dilemma","contrast":"Ложная дилемма сужает выбор до двух крайностей. Ведущий делает обратное: придумывает «средний» вариант и считает его истинным только потому, что он посередине."},{"id":"q076","batch":2,"difficulty":3,"text":"На переговорах о квартире продавец просил десять миллионов, покупатель предлагал шесть. Риелтор убеждает покупателя: «Справедливая цена — посередине, восемь миллионов, это честный компромисс». При этом похожие квартиры в том же доме недавно продавались за шесть с половиной.","answer_id":"middle_ground","distractors":["false_dilemma","nirvana","false_authority","bandwagon"],"offer_none":true,"highlight":"Справедливая цена — посередине, восемь миллионов, это честный компромисс","explanation":"Середина между двумя запросами зависит только от того, кто сколько запросил: попроси продавец двадцать миллионов — «справедливой» стала бы цена в тринадцать. Справедливую цену показывает рынок, а он говорит о шести с половиной.","nearest_distractor":"none","contrast":"Торговаться и сходиться посередине — обычная практика, и сам по себе компромисс не ошибка. Ошибка — объявлять середину справедливой по определению, не глядя на реальные цены."},{"id":"q077","batch":2,"difficulty":1,"text":"Жильцы обсуждают, ставить ли в подъезде домофон. Жилец с первого этажа против: «Какой в этом смысл? Всё равно кто-нибудь будет придерживать дверь курьерам, и посторонние всё равно пройдут».","answer_id":"nirvana","distractors":["false_dilemma","slippery_slope","appeal_to_ignorance","hasty_generalization"],"offer_none":false,"highlight":"Всё равно кто-нибудь будет придерживать дверь курьерам, и посторонние всё равно пройдут","explanation":"Домофон не остановит всех, но отсечёт большую часть посторонних. Отвергать улучшение только потому, что оно не идеально, — ошибка нирваны.","nearest_distractor":"false_dilemma","contrast":"Жилец не предлагает выбор из двух вариантов; он отвергает решение, сравнивая его с недостижимым идеалом — «чтобы ни один посторонний не прошёл»."},{"id":"q078","batch":2,"difficulty":2,"text":"Депутат выступил против бесплатной вакцинации пожилых от гриппа: «Прививка защищает лишь в шестидесяти процентах случаев. Зачем тратить бюджет на средство, которое не даёт стопроцентной гарантии?»","answer_id":"nirvana","distractors":["misleading_statistics","false_dilemma","middle_ground","appeal_to_consequences"],"offer_none":true,"highlight":"Зачем тратить бюджет на средство, которое не даёт стопроцентной гарантии?","explanation":"Защита в шестидесяти процентах случаев — это тысячи предотвращённых болезней и госпитализаций. Требовать стопроцентной гарантии — значит отвергать почти любую медицину.","nearest_distractor":"misleading_statistics","contrast":"Шестьдесят процентов названы честно, без искажения. Ошибка не в подаче статистики, а в требовании идеала."},{"id":"q079","batch":2,"difficulty":3,"text":"Сын опоздал к обеду, и отец сделал ему замечание. Тогда мальчик нарочно разбил мячом два стекла на веранде и невозмутимо объяснил: «Папа упрекнул меня, что я не обедаю дома, а обед стоит пятьсот рублей. Стекло стоит двести пятьдесят, так что на два стекла папа потратил на меня ровно столько же, сколько потратил бы на обед, — обижаться ему не на что».","answer_id":"ignoratio_elenchi","distractors":["straw_man","red_herring","non_sequitur","false_analogy"],"offer_none":false,"highlight":"Папа упрекнул меня, что я не обедаю дома, а обед стоит пятьсот рублей","explanation":"Отец упрекал за опоздание — за нарушение порядка и неуважение к семье. Мальчик подменяет этот тезис другим: «отец недоволен, что на меня не потрачены деньги», — и дальше вполне последовательно «исполняет» уже выдуманную претензию. Внутри подмены есть и арифметическая нелепость: обед уже приготовлен, так что стёкла не уравнивают счёт, а удваивают убыток. Формально стройные, но пустые построения такого рода психиатры называют резонёрством.","nearest_distractor":"straw_man","also_accepted":[{"id":"non_sequitur","note":"Вывод «обижаться не на что» и правда не следует из равенства сумм. Но этот шаг вторичен: всё рассуждение отвечает не на тот упрёк, который сделал отец. Главная ошибка — подмена тезиса."}],"contrast":"Соломенное чучело — частный случай подмены тезиса: позицию искажают, чтобы её опровергнуть. Мальчик ничего не опровергает — он искажает упрёк, чтобы его «удовлетворить». Поэтому точный ярлык здесь — общая категория, подмена тезиса.","pick_notes":{"red_herring":"Мальчик не уводит разговор на другую тему — он говорит именно об упрёке отца, но подменяет его смысл: опоздание превращается в «недотраченные деньги».","false_analogy":"Приравнивать обед к стёклам по цене действительно нелепо, но это следствие главной ошибки: если упрёк был о деньгах, сравнение сумм хотя бы имело бы смысл. Корень — в подмене упрёка."}},{"id":"q080","batch":2,"difficulty":1,"text":"Отец объявил сыновьям, что ночью какой-то гад украл корову, и братья взялись за дедукцию: «Раз гад — значит, маленького роста. Раз маленького роста — значит, из Малиновки. А раз из Малиновки — ясно дело, Васька Косой!» Мировой судья решил проверить их метод и показал закрытую коробку: «Что внутри?» Братья ответили: «Коробка квадратная — значит, внутри круглое; раз круглое — значит, оранжевое; стало быть, апельсин!» Судья открыл коробку, достал апельсин и строго сказал: «Васька, верни корову!»","answer_id":"non_sequitur","distractors":["slippery_slope","affirming_consequent","circular","cum_hoc"],"offer_none":false,"highlight":"Раз маленького роста — значит, из Малиновки. А раз из Малиновки — ясно дело, Васька Косой!","explanation":"Каждое «значит» ничем не обосновано: рост не связан с деревней, деревня — с конкретным Васькой. Цепочка выглядит как рассуждение, но звенья не следуют одно из другого. (Первое звено «гад — значит, маленький» вдобавок держится на игре слов: гад-ругательство и гад-пресмыкающееся.)","nearest_distractor":"slippery_slope","also_accepted":[{"id":"affirming_consequent","note":"Судья и правда ошибается: «если метод верен, он угадает; угадал — значит, верен» — это утверждение следствия, да ещё по одному-единственному попаданию. Но подсвеченная цепочка братьев — мнимое следование."}],"contrast":"Скользкая дорожка — прогноз цепочки будущих последствий. Братья ничего не прогнозируют: они «выводят» факт — кто вор — через цепь необоснованных «значит»."},{"id":"q081","batch":2,"difficulty":2,"text":"Молодой человек объясняет приятелю свою «систему»: «Чтобы переродиться и обрести душевный покой, человеку нужна сильная встряска. Хорошая драка — сильная встряска. Значит, мне непременно нужно с кем-нибудь подраться». Совет сходить к психологу он отверг как «слишком мягкий».","answer_id":"non_sequitur","distractors":["false_premise","false_dilemma","circular","hasty_generalization"],"offer_none":false,"highlight":"Хорошая драка — сильная встряска. Значит, мне непременно нужно с кем-нибудь подраться","explanation":"Даже если согласиться, что встряска нужна, из «драка даёт встряску» не следует «нужна именно драка». Достаточное средство выдано за необходимое: встряску дают и болезнь, и утрата, и спасение чужой жизни. Слово «непременно» ничем не обосновано. Пример навеян классическими описаниями резонёрства из учебников психиатрии.","nearest_distractor":"false_premise","contrast":"Первая посылка («для покоя нужна встряска») тоже ничем не доказана — это второй дефект. Но вывод не следует, даже если её принять: ошибка в самом шаге рассуждения.","also_accepted":[{"id":"false_premise","note":"Посылка «чтобы обрести покой, нужна сильная встряска» действительно не доказана. Но главный дефект — в переходе: даже при верной посылке из «драка встряхивает» не следует «нужна именно драка»."},{"id":"false_dilemma","note":"«Непременно» действительно оставляет единственный вариант из многих — это близко к ложной дилемме. Точнее назвать ошибку так: достаточное средство выдано за необходимое, то есть вывод не следует."}],"pick_notes":{"circular":"Порочного круга здесь нет: вывод «надо подраться» нигде не используется как посылка. Беда в том, что он не следует из посылок."}},{"id":"q082","batch":2,"difficulty":3,"text":"Главврач роддома распорядился: «Всем известно, что в полнолуние рожают чаще, поэтому в эти ночи ставим в смену вдвое больше акушерок». Через полгода выяснилось, что в полнолуния принимали столько же родов, сколько в обычные ночи, — как и показывают крупные исследования.","answer_id":"false_premise","distractors":["bandwagon","cum_hoc","circular","hasty_generalization"],"offer_none":true,"highlight":"Всем известно, что в полнолуние рожают чаще","explanation":"Решение логично вытекает из посылки, но посылка ложна: исследования не находят связи между фазами Луны и числом родов. Вывод из неверного основания неверен, как бы аккуратно его ни выводили.","nearest_distractor":"bandwagon","contrast":"«Всем известно» звучит как ссылка на большинство, но главврач не доказывает мысль её популярностью — он принимает поверье за факт и строит на нём решение. Ошибка — в основании рассуждения."},{"id":"q083","batch":2,"difficulty":1,"text":"— Если у человека грипп, у него поднимается температура, — рассуждает Миша. — У меня температура тридцать семь и восемь. Значит, у меня грипп, и надо срочно пить противовирусное.","answer_id":"affirming_consequent","distractors":["denying_antecedent","post_hoc","hasty_generalization","circular"],"offer_none":false,"highlight":"У меня температура тридцать семь и восемь. Значит, у меня грипп","explanation":"Температура бывает при гриппе, но не только: при ангине, отравлении, обычной простуде. Из «если грипп — то температура» нельзя вывести «есть температура — значит, грипп».","nearest_distractor":"denying_antecedent","contrast":"Отрицание основания звучало бы так: «Гриппа у меня нет — значит, и температуры не будет». Миша же идёт от следствия к причине: «температура есть — значит, грипп»."},{"id":"q084","batch":2,"difficulty":3,"text":"Следователь в детективном сериале рассуждает: «Убийца должен был знать код от сейфа. Племянник покойного знал код. Значит, убийца — племянник». Сериал продлили на второй сезон, ведь код знали ещё садовник, экономка и сам покойный.","answer_id":"affirming_consequent","distractors":["non_sequitur","denying_antecedent","post_hoc","false_premise"],"offer_none":true,"highlight":"Племянник покойного знал код. Значит, убийца — племянник","explanation":"Из «убийца знал код» следует лишь, что подозреваемых нужно искать среди тех, кто его знал. Знание кода — необходимое условие, а не доказательство: его знали ещё трое.","nearest_distractor":"non_sequitur","also_accepted":[{"id":"non_sequitur","note":"Вывод действительно не следует из посылок. Но у этой ошибки есть точная форма — «если A, то B; B есть — значит, A», и её лучше назвать конкретно."}],"contrast":"Мнимое следование — общий ярлык для вывода, не связанного с посылками. Здесь у ошибки есть узнаваемая форма: «если убийца, то знал код; знал код — значит, убийца»."},{"id":"q085","batch":2,"difficulty":2,"text":"Мама предупреждает: «Будешь сидеть на сквозняке — простудишься». Дочь закрыла окно и пошла гулять под ледяным дождём без шапки: «Сквозняка-то нет — значит, и не простужусь».","answer_id":"denying_antecedent","distractors":["affirming_consequent","false_premise","hasty_generalization","false_dilemma"],"offer_none":false,"highlight":"Сквозняка-то нет — значит, и не простужусь","explanation":"Сквозняк — лишь одна из возможных причин простуды. Из «если сквозняк — простудишься» не следует, что без сквозняка простуда невозможна: ледяной дождь справится не хуже.","nearest_distractor":"affirming_consequent","contrast":"Утверждение следствия идёт от следствия к причине («простудилась — значит, был сквозняк»). Дочь же отрицает условие и решает, что не будет и следствия."},{"id":"q086","batch":2,"difficulty":3,"text":"Объявление в банке: «Если оформите карту до конца месяца, получите кешбэк десять процентов». Пётр Сергеевич узнал, что коллега получила такой же кешбэк, хотя карту не оформляла, и возмутился: «Как так? Карты у неё не было — значит, и кешбэка быть не могло!» Коллега получила его по другой акции.","answer_id":"denying_antecedent","distractors":["affirming_consequent","false_dilemma","equivocation","false_premise"],"offer_none":true,"highlight":"Карты у неё не было — значит, и кешбэка быть не могло!","explanation":"Объявление говорит лишь, что карта — один из способов получить кешбэк. Оно не утверждает, что других способов нет, и коллега воспользовалась другим.","nearest_distractor":"none","contrast":"Вывод был бы верным, если бы банк написал «кешбэк — только для владельцев карты». Но «если… то» не означает «только если»."},{"id":"q087","batch":2,"difficulty":1,"text":"— Снежный человек существует, — уверяет Гена. — Учёные столько лет ищут, но так и не доказали, что его нет!","answer_id":"appeal_to_ignorance","distractors":["fallacy_fallacy","false_authority","circular","bandwagon"],"offer_none":false,"highlight":"Учёные столько лет ищут, но так и не доказали, что его нет!","explanation":"Отсутствие опровержения не доказывает существования. Доказывать должен тот, кто утверждает: нужен сам снежный человек (или хотя бы надёжные следы), а не то, что его не смогли не найти.","nearest_distractor":"fallacy_fallacy","contrast":"«Ошибка ошибки» выводит ложность тезиса из слабости довода. Гена делает обратное: выводит истинность из того, что тезис не опровергли."},{"id":"q088","batch":2,"difficulty":3,"text":"Начальник цеха докладывает: «За три месяца ни одной жалобы на новые защитные перчатки — значит, они безопасны». Рабочие просто не знали, куда жаловаться: ящик для обращений висел в бытовке, которую давно заперли.","answer_id":"appeal_to_ignorance","distractors":["hasty_generalization","fallacy_fallacy","false_premise","cherry_picking"],"offer_none":true,"highlight":"За три месяца ни одной жалобы на новые защитные перчатки — значит, они безопасны","explanation":"Отсутствие жалоб — не доказательство безопасности, особенно когда жаловаться было некуда. Безопасность проверяют испытаниями и осмотрами, а не тишиной.","nearest_distractor":"none","contrast":"Отсутствие жалоб может быть разумным косвенным признаком — если канал жалоб работает и им пользуются. Здесь он фактически недоступен, и тишина ничего не значит."},{"id":"q089","batch":2,"difficulty":2,"text":"Девятиклассник доказывал у доски, что Земля круглая: «Если бы она была плоской, корабли падали бы с края, а такого ни с кем не случалось». Одноклассник с задней парты засмеялся: «Довод бредовый — значит, Земля плоская!»","answer_id":"fallacy_fallacy","distractors":["appeal_to_ignorance","ad_hominem","straw_man","circular"],"offer_none":false,"highlight":"Довод бредовый — значит, Земля плоская!","explanation":"Плохое доказательство не делает вывод ложным. Земля круглая по множеству других причин — просто девятиклассник выбрал неудачный довод.","nearest_distractor":"appeal_to_ignorance","contrast":"Апелляция к незнанию — «никто не доказал, значит, неверно» вообще. Здесь есть конкретный неудачный довод, и из его слабости выводят ложность самого тезиса — это «ошибка ошибки»."},{"id":"q090","batch":2,"difficulty":3,"text":"Защитник животных в телеэфире призвал закрыть цирки с дикими животными и сослался на «исследование», которое оказалось студенческой курсовой с ошибками в расчётах. Директор цирка торжествовал: «Видите? Их доказательства — липа. Значит, нашим животным живётся прекрасно».","answer_id":"fallacy_fallacy","distractors":["ad_hominem","appeal_to_ignorance","red_herring","false_dilemma"],"offer_none":true,"highlight":"Их доказательства — липа. Значит, нашим животным живётся прекрасно","explanation":"Опровергнут был только один слабый довод. Как живётся животным в цирке, по-прежнему нужно выяснять — ветеринарными осмотрами, проверкой условий содержания. Негодный аргумент противника не доказывает правоту его оппонента.","nearest_distractor":"ad_hominem","contrast":"Директор не нападает на защитника лично — он разбирает его довод и находит изъян. Ошибка начинается дальше: из негодности довода он выводит ложность тезиса."},{"id":"q091","batch":2,"difficulty":1,"text":"На собеседовании директор говорит: «Нам нужен очень ответственный сотрудник». Кандидат оживляется: «Это точно я! На прошлой работе что бы ни сломалось, всегда говорили, что ответственный — я».","answer_id":"equivocation","distractors":["false_analogy","no_true_scotsman","composition","red_herring"],"offer_none":false,"highlight":"что бы ни сломалось, всегда говорили, что ответственный — я","explanation":"Директор говорит об ответственности как о черте характера — надёжности, а кандидат — об ответственности как о вине: «кто виноват». Вывод держится на том, что слово используется в двух смыслах.","nearest_distractor":"false_analogy","contrast":"Кандидат не сравнивает две разные вещи по сходству — он подменяет смысл одного и того же слова."},{"id":"q092","batch":2,"difficulty":2,"text":"Комментатор в соцсетях пишет: «Эволюция — это всего лишь теория. А теория — это просто предположение, догадка. Так что верить в эволюцию необязательно».","answer_id":"equivocation","distractors":["false_premise","appeal_to_ignorance","no_true_scotsman","circular"],"offer_none":true,"highlight":"А теория — это просто предположение, догадка","explanation":"В науке «теория» — проверенная система объяснений, подтверждённая множеством фактов, как теория тяготения. В быту — «догадка». Вывод получается только за счёт подмены научного смысла бытовым.","nearest_distractor":"false_premise","also_accepted":[{"id":"false_premise","note":"Посылка «теория — это догадка» действительно ложна — для научного смысла слова. Но в бытовом смысле она верна, и вся ошибка держится на смене смысла посреди рассуждения, поэтому точнее «подмена понятий»."}],"contrast":"Можно назвать посылку «теория — это догадка» ложной, но она верна в бытовом смысле слова. Ошибка в том, что смысл меняется посреди рассуждения."},{"id":"q093","batch":2,"difficulty":2,"text":"Ученик возмущается: «Почему мне нельзя пользоваться учебником на контрольной? Врачи же заглядывают в справочники во время операций, юристы — в кодексы на заседаниях. Контрольная — такая же работа».","answer_id":"false_analogy","distractors":["bandwagon","special_pleading","false_authority","equivocation"],"offer_none":true,"highlight":"Врачи же заглядывают в справочники во время операций, юристы — в кодексы на заседаниях","explanation":"Врачу и юристу справочник помогает сделать работу. Контрольная — не работа, а проверка того, что ученик знает сам; с подсказкой она теряет смысл. Сходство поверхностное, а в существенном ситуации различаются.","nearest_distractor":"bandwagon","contrast":"Ученик не говорит «так делают все» — он переносит правило из одной ситуации в другую по внешнему сходству."},{"id":"q094","batch":2,"difficulty":1,"text":"Повар-экспериментатор хвастается: «Я положил в этот суп всё самое вкусное: копчёную рыбу, клубнику, шоколад и маринованные огурцы. Каждый ингредиент великолепен, значит, и суп будет великолепен».","answer_id":"composition","distractors":["division","hasty_generalization","false_analogy","equivocation"],"offer_none":false,"highlight":"Каждый ингредиент великолепен, значит, и суп будет великолепен","explanation":"Свойства частей не обязательно переходят на целое: вкусные по отдельности продукты вместе могут дать ужасный результат. Вкус супа зависит от сочетания, а не только от качества ингредиентов.","nearest_distractor":"division","contrast":"Ошибка деления идёт от целого к части: «суп отличный — значит, и огурец в нём отличный». Повар идёт от частей к целому."},{"id":"q095","batch":2,"difficulty":3,"text":"Родители выбирают репетитора по физике. Мама говорит: «Он из лучшего физмата страны — значит, он отличный преподаватель». Через месяц выяснилось, что репетитор с трудом окончил этот вуз и объяснять совсем не умеет.","answer_id":"division","distractors":["false_authority","composition","hasty_generalization","false_analogy"],"offer_none":true,"highlight":"Он из лучшего физмата страны — значит, он отличный преподаватель","explanation":"Хорошая репутация вуза в целом не гарантирует, что каждый его выпускник хорош, — и тем более что он умеет преподавать. Свойство целого переносится на часть без проверки.","nearest_distractor":"false_authority","contrast":"Ложный авторитет — когда тезис подкрепляют мнением неподходящего эксперта. Мама не ссылается на мнение репетитора; она переносит качество вуза в целом на конкретного выпускника."},{"id":"q096","batch":2,"difficulty":2,"text":"В исследовании тысячу добровольцев жребием разделили на две группы: одни месяц ложились спать до одиннадцати, другие — после часа ночи. У первых тесты внимания оказались заметно лучше, и авторы заключили, что ранний отбой улучшает внимание.","answer_id":"none","distractors":["cum_hoc","post_hoc","hasty_generalization","false_authority"],"offer_none":true,"highlight":"авторы заключили, что ранний отбой улучшает внимание","explanation":"Это не простая корреляция: участников распределили случайно, поэтому прочие факторы — возраст, доход, привычки — поровну представлены в обеих группах. Рандомизированный эксперимент — как раз способ честно проверить причину.","nearest_distractor":"cum_hoc","contrast":"Корреляция не доказывает причину, когда два явления просто наблюдают вместе. Здесь причину целенаправленно меняли и сравнивали со случайной контрольной группой."},{"id":"q097","batch":2,"difficulty":2,"text":"Новое лекарство три года испытывали на двенадцати тысячах пациентов и не обнаружили ни одного серьёзного побочного эффекта. Регулятор одобрил препарат, но обязал производителя продолжать наблюдение после выхода на рынок.","answer_id":"none","distractors":["appeal_to_ignorance","hasty_generalization","false_authority","survivorship"],"offer_none":true,"highlight":"Регулятор одобрил препарат, но обязал производителя продолжать наблюдение","explanation":"Отсутствие побочных эффектов здесь — результат целенаправленного поиска на большой выборке, а не «никто не жаловался». И регулятор не заявляет, что опасности нет вовсе: он требует продолжать наблюдение.","nearest_distractor":"appeal_to_ignorance","contrast":"Апелляция к незнанию — «не доказано, что вредно, значит, безопасно». Здесь вред тщательно искали и не нашли, а вывод сделан осторожный."},{"id":"q098","batch":2,"difficulty":2,"text":"По правилам турнира, если команда не явилась на матч, ей засчитывается техническое поражение. «Северяне» на матч не приехали — у них сломался автобус. Судья засчитал им техническое поражение, хотя все им сочувствовали.","answer_id":"none","distractors":["affirming_consequent","denying_antecedent","appeal_to_pity","special_pleading"],"offer_none":true,"highlight":"Судья засчитал им техническое поражение, хотя все им сочувствовали","explanation":"Вывод корректен: «если A, то B; A есть — значит, B». Сочувствие к «северянам» понятно, но правило не делает исключений для уважительных причин, и судья применяет его правильно.","nearest_distractor":"affirming_consequent","contrast":"Утверждение следствия — когда идут от следствия к условию. Судья идёт от условия (не явились) к следствию (поражение) — это правильный вывод."},{"id":"q099","batch":2,"difficulty":3,"text":"Организаторы марафона заранее объявили: «Финишёром считается тот, кто пробежал всю дистанцию за отведённые семь часов». Участник, добравшийся до финиша через восемь часов, потребовал медаль. «По правилам вы не финишёр», — ответили ему и вручили памятный значок за упорство.","answer_id":"none","distractors":["no_true_scotsman","special_pleading","equivocation","appeal_to_pity"],"offer_none":true,"highlight":"По правилам вы не финишёр","explanation":"Определение финишёра было объявлено заранее, а не придумано задним числом, чтобы отбросить неудобный пример. Применять известное всем правило — корректно.","nearest_distractor":"no_true_scotsman","contrast":"«Настоящий шотландец» — когда определение меняют после того, как появился контрпример. Здесь определение существовало до забега и одинаково для всех."},{"id":"q100","batch":2,"difficulty":1,"text":"Отчёт городской больницы: «В этом году мы приняли 12 400 пациентов против 11 900 в прошлом — рост на 4%. Число врачей не изменилось, поэтому нагрузка на каждого врача тоже выросла примерно на 4%».","answer_id":"none","distractors":["misleading_statistics","cherry_picking","cum_hoc","hasty_generalization"],"offer_none":true,"highlight":"рост на 4%","explanation":"Цифры даны вместе с абсолютными значениями и базой сравнения, а вывод о нагрузке арифметически из них следует. Проценты подкреплены исходными числами — никакой манипуляции.","nearest_distractor":"misleading_statistics","contrast":"Манипуляция статистикой — когда цифры подают так, что они создают ложное впечатление: без базы, с неудобными сравнениями. Здесь всё прозрачно."},{"id":"q101","batch":3,"difficulty":1,"text":"В шахматном клубе двенадцатилетний Артём заметил, что в регламенте турнира ничья в разных пунктах засчитывается по-разному, и предложил это исправить. Организатор отмахнулся: «Ты сначала до разряда дорасти, а потом регламенты обсуждай». Противоречие в регламенте так и осталось.","answer_id":"ad_hominem","distractors":["false_authority","genetic_fallacy","red_herring","straw_man"],"offer_none":false,"highlight":"Ты сначала до разряда дорасти, а потом регламенты обсуждай","explanation":"Противоречие в регламенте либо есть, либо нет, и проверяется это чтением двух пунктов, а не шахматным разрядом того, кто его заметил. Довод отвергнут из-за возраста и статуса автора.","nearest_distractor":"false_authority","contrast":"Ложный авторитет — когда тезис подкрепляют мнением неподходящего эксперта. Здесь обратный ход: довод отвергают, потому что у автора «недостаточно» статуса. Это атака на личность, а не ссылка на авторитет."},{"id":"q102","batch":3,"difficulty":2,"text":"Климатолог выступила на конференции с призывом сокращать авиаперелёты ради снижения выбросов. В соцсетях её высмеяли: «Сама-то на конференцию прилетела на самолёте! Значит, все её разговоры о выбросах — пустой звук».","answer_id":"tu_quoque","distractors":["ad_hominem","special_pleading","red_herring","genetic_fallacy"],"offer_none":true,"highlight":"Сама-то на конференцию прилетела на самолёте! Значит, все её разговоры о выбросах — пустой звук","explanation":"Даже если климатолог непоследовательна, данные о выбросах от авиации от этого не меняются. Её поступок — повод упрекнуть её в непоследовательности, но не опровержение её довода.","nearest_distractor":"ad_hominem","contrast":"Переход на личность — общая категория. Здесь её частный случай: упрекают не в чём угодно, а в нарушении того самого, к чему она призывает. Это «сам такой».","pick_notes":{"special_pleading":"Двойные стандарты были бы, если бы климатолог заявила, что ей летать можно, а остальным нельзя. Она этого не говорит; ошибка — у тех, кто отвергает её довод из-за её поступка."}},{"id":"q103","batch":3,"difficulty":2,"text":"В споре о вежливости участник форума заявил: «Слово „спасибо“ произошло от „спаси Бог“. Я атеист, поэтому говорить „спасибо“ для меня лицемерие». Собеседники заметили, что сегодня это слово означает просто благодарность и, произнося его, никто не молится.","answer_id":"genetic_fallacy","distractors":["equivocation","appeal_to_tradition","ad_hominem","false_premise"],"offer_none":true,"highlight":"Слово „спасибо“ произошло от „спаси Бог“. Я атеист, поэтому говорить „спасибо“ для меня лицемерие","explanation":"Происхождение слова не определяет его нынешний смысл. Сегодня «спасибо» — просто выражение благодарности. Значение слова определяется употреблением, а не этимологией.","nearest_distractor":"equivocation","contrast":"Игра смыслов тут чувствуется, но слово не меняет значение внутри рассуждения: автор прямо выводит нынешний смысл из исторического. Оценка по происхождению — генетическая ошибка."},{"id":"q104","batch":3,"difficulty":1,"text":"Бабушка недовольна, что внук собирается на собеседование в банк в джинсах: «Джинсы придумали как рабочие штаны для золотоискателей. Это одежда для шахты, а не для приличного места!»","answer_id":"genetic_fallacy","distractors":["appeal_to_tradition","appeal_to_novelty","ad_hominem","bandwagon"],"offer_none":false,"highlight":"Джинсы придумали как рабочие штаны для золотоискателей. Это одежда для шахты, а не для приличного места!","explanation":"Уместность одежды определяется нынешними нормами, а не тем, для кого её шили полтора века назад. Может быть, в банк и правда лучше надеть костюм, но довод бабушки не об этом, а о происхождении джинсов.","nearest_distractor":"appeal_to_tradition","contrast":"Бабушка не говорит «на собеседования всегда ходили в костюмах». Она судит о джинсах по их происхождению — это генетическая ошибка."},{"id":"q105","batch":3,"difficulty":3,"text":"Автор популярной книги о здоровье пишет: «Лауреат Нобелевской премии по химии был уверен, что огромные дозы витамина C излечивают простуду и даже рак. Раз так считал нобелевский лауреат, сомневаться не приходится». Клинические испытания этого не подтвердили.","answer_id":"false_authority","distractors":["bandwagon","genetic_fallacy","ad_hominem","appeal_to_ignorance"],"offer_none":true,"highlight":"Раз так считал нобелевский лауреат, сомневаться не приходится","explanation":"Нобелевская премия по химии — признание заслуг в химии, а не в клинической медицине. Эффективность лечения проверяют клиническими испытаниями, а они результат не подтвердили. Авторитет в одной области перенесён на другую.","nearest_distractor":"none","contrast":"Ссылка на эксперта уместна, если он эксперт именно в этом вопросе и его мнение подтверждено данными. Здесь нет ни того, ни другого: химия — не клиническая медицина, а испытания говорят обратное."},{"id":"q106","batch":3,"difficulty":2,"text":"Прокурор полчаса доказывал присяжным, что ограбление ювелирного магазина спланировали профессионалы: сигнализацию отключили заранее, время выбрали с точностью до минуты. Ни одного довода, что всё это сделал именно подсудимый, он не привёл, но закончил речь требованием признать подсудимого виновным.","answer_id":"ignoratio_elenchi","distractors":["red_herring","straw_man","appeal_to_pity","ad_hominem"],"offer_none":false,"highlight":"Прокурор полчаса доказывал присяжным, что ограбление ювелирного магазина спланировали профессионалы","explanation":"Требовалось доказать, что преступление совершил подсудимый. Прокурор доказывает другой тезис — что ограбление было профессиональным. Это может быть правдой, но к виновности конкретного человека отношения не имеет.","nearest_distractor":"red_herring","contrast":"Отвлекающий манёвр уводит к посторонней теме. Прокурор от темы не уходит — он говорит о том же ограблении, но доказывает не тот тезис. Это подмена тезиса в общем виде.","pick_notes":{"straw_man":"Соломенное чучело — когда искажают позицию оппонента, чтобы её опровергнуть. Прокурор ничью позицию не искажает: он просто доказывает не то, что требуется."}},{"id":"q107","batch":3,"difficulty":1,"text":"Начальник вернул сотруднику отчёт: «Слишком длинно, сделайте короче — никто не будет читать двадцать страниц». Через час сотрудник принёс тот же текст, набранный восьмым кеглем: «Готово, теперь всего девять страниц».","answer_id":"ignoratio_elenchi","distractors":["equivocation","straw_man","red_herring","special_pleading"],"offer_none":false,"highlight":"Готово, теперь всего девять страниц","explanation":"Начальнику нужен был более короткий текст — такой, который быстрее прочитать. Сотрудник выполнил другое требование — «меньше страниц» — и выдаёт его за исполнение первого. Тезис подменён удобным буквальным прочтением.","nearest_distractor":"equivocation","also_accepted":[{"id":"equivocation","note":"Слово «короче» действительно можно понять двояко: по объёму текста и по числу страниц. Но смысл начальник пояснил («никто не будет читать») — сотрудник не путает значения, а подменяет само требование."}],"contrast":"Подмена понятий — когда слово меняет смысл внутри рассуждения. Здесь начальник ясно объяснил, чего хочет, а сотрудник «исполнил» другое требование — это подмена тезиса.","pick_notes":{"straw_man":"Сотрудник не спорит с начальником и не опровергает его — он искажает требование, чтобы его формально «выполнить». Это подмена тезиса в общем виде, а не соломенное чучело.","red_herring":"Сотрудник не уводит разговор на другую тему — он говорит именно об отчёте, но подменяет то, что от него требовалось."}},{"id":"q108","batch":3,"difficulty":3,"text":"Жильцы пожаловались в управляющую компанию, что зимой в квартирах всего пятнадцать градусов. Директор принёс на собрание папку актов: котельная работает на полную мощность, давление в системе в норме, все проверки пройдены. «Как видите, претензии необоснованны», — заключил он.","answer_id":"ignoratio_elenchi","distractors":["red_herring","false_authority","straw_man","circular"],"offer_none":true,"highlight":"Как видите, претензии необоснованны","explanation":"Жильцы жалуются на холод в квартирах, а директор доказывает другое — что исправна котельная. Это может быть правдой, но тепло может теряться по пути: в трубах, стояках, батареях. Доказан не тот тезис, а вывод сделан о первом.","nearest_distractor":"red_herring","contrast":"Директор не уводит разговор в сторону — он говорит о том же отоплении и даже приносит документы. Но доказывает он не то, что в квартирах тепло, а то, что исправна котельная.","pick_notes":{"straw_man":"Директор не искажает жалобу жильцов, чтобы её опровергнуть: он просто доказывает не то, о чём его спрашивали.","false_authority":"Акты — не мнение неподходящего эксперта, а документы о котельной. Беда в том, что они о другом: исправная котельная ещё не значит тёплые квартиры."}},{"id":"q109","batch":3,"difficulty":1,"text":"Депутаты предложили запретить салюты в парке рядом с зоопарком: животные пугаются и калечатся о вольеры. Один из блогеров написал: «Теперь они хотят отменить нам Новый год!»","answer_id":"straw_man","distractors":["ignoratio_elenchi","slippery_slope","appeal_to_fear","red_herring"],"offer_none":false,"highlight":"Теперь они хотят отменить нам Новый год!","explanation":"Предлагалось запретить салюты в одном парке, а не праздник. Блогер спорит с выдуманной, утрированной позицией, которую легко высмеять.","nearest_distractor":"ignoratio_elenchi","contrast":"Подмена тезиса — общая категория. Здесь её частный случай: позицию оппонентов доводят до абсурда, чтобы с ней было легко спорить, — это соломенное чучело."},{"id":"q110","batch":3,"difficulty":1,"text":"Посетитель ресторана подзывает официанта: «Суп совсем холодный». Официант улыбается: «Зато у нас лучший вид на набережную во всём городе — вы видели, какой сегодня закат?»","answer_id":"red_herring","distractors":["ignoratio_elenchi","straw_man","tu_quoque","appeal_to_pity"],"offer_none":false,"highlight":"Зато у нас лучший вид на набережную во всём городе — вы видели, какой сегодня закат?","explanation":"Жалоба — про холодный суп. Вид из окна может быть прекрасным, но суп от этого не нагреется. Официант переводит внимание на приятную постороннюю тему.","nearest_distractor":"ignoratio_elenchi","contrast":"Подмена тезиса — общая категория. Здесь её частный случай: разговор просто уводят на другую тему — отвлекающий манёвр."},{"id":"q111","batch":3,"difficulty":1,"text":"На собеседовании менеджер по персоналу, не поднимая глаз от резюме, спрашивает: «Расскажите, почему вы ушли с прошлой работы со скандалом?» Кандидат ушёл по собственному желанию, с благодарственным письмом от директора.","answer_id":"loaded_question","distractors":["false_premise","straw_man","ad_hominem","red_herring"],"offer_none":false,"highlight":"почему вы ушли с прошлой работы со скандалом?","explanation":"Вопрос предполагает, что скандал был, и просит лишь объяснить его причины. Любой ответ по существу («из-за начальника», «из-за зарплаты») подтверждает несуществующий скандал. Честный ответ начинается с отказа принять допущение.","nearest_distractor":"false_premise","contrast":"Ложное основание — когда рассуждение открыто опирается на неверную посылку. Здесь посылку не утверждают, а прячут в вопрос, так что любой прямой ответ её признаёт."},{"id":"q112","batch":3,"difficulty":3,"text":"Администрация района запустила онлайн-опрос: «Поддерживаете ли вы прекращение бессмысленной траты бюджета на содержание старого парка?» Через неделю она отчиталась: восемьдесят процентов жителей проголосовали за закрытие парка.","answer_id":"loaded_question","distractors":["misleading_statistics","false_premise","bandwagon","equivocation"],"offer_none":true,"highlight":"Поддерживаете ли вы прекращение бессмысленной траты бюджета на содержание старого парка?","explanation":"В вопрос заранее встроена оценка — «бессмысленная трата». Ответить «нет» — значит выступить за бессмысленные траты. Настоящий вопрос — нужно ли содержать парк — так и не задан, и результат показывает реакцию на формулировку, а не мнение о парке.","nearest_distractor":"misleading_statistics","contrast":"Восемьдесят процентов — честный подсчёт голосов. Проблема не в обработке цифр, а в самом вопросе, на который отвечали.","pick_notes":{"false_premise":"Оценка «бессмысленная трата» действительно не доказана. Но из неё ничего не выводят — её прячут в формулировку вопроса, чтобы любой ответ её принимал. Это сложный вопрос."}},{"id":"q113","batch":3,"difficulty":1,"text":"— Ни один настоящий программист не пользуется мышкой, только клавиатурой, — заявил стажёр. — А наш техлид всё делает мышкой, — заметила коллега. — Значит, он давно уже менеджер, а не программист.","answer_id":"no_true_scotsman","distractors":["hasty_generalization","equivocation","special_pleading","ad_hominem"],"offer_none":false,"highlight":"Значит, он давно уже менеджер, а не программист","explanation":"Когда появился контрпример — техлид с мышкой, — стажёр не пересматривает утверждение, а переопределяет «программиста» так, чтобы контрпример под него не подпадал. Теперь обобщение нельзя опровергнуть в принципе.","nearest_distractor":"hasty_generalization","contrast":"Само утверждение стажёра — поспешное обобщение, но подсвечен следующий ход: контрпример не признают, а исключают, переопределив понятие. Это и есть «настоящий шотландец»."},{"id":"q114","batch":3,"difficulty":2,"text":"— Настоящие фанаты никогда не освистывают свою команду, — сказал Игорь. — Вчера половина трибуны освистала наших после третьего пропущенного мяча, — напомнил друг. — Ну так это были не настоящие фанаты, а случайные зрители.","answer_id":"no_true_scotsman","distractors":["circular","special_pleading","equivocation","hasty_generalization"],"offer_none":true,"highlight":"Ну так это были не настоящие фанаты, а случайные зрители","explanation":"Половина трибуны — не случайные зрители, а обычные болельщики. Игорь спасает своё обобщение, задним числом исключая из «настоящих фанатов» всех, кто ему противоречит.","nearest_distractor":"circular","contrast":"Порочный круг — когда вывод заложен в посылку. Здесь круг возникает только после подгонки определения: «настоящий фанат» теперь значит «тот, кто не свистит». Ключевое — переопределение задним числом, это и есть «настоящий шотландец»."},{"id":"q115","batch":3,"difficulty":3,"text":"Мэр требовал проводить конкурс на каждую должность в администрации: «Никаких назначений по знакомству!» Когда его сына назначили начальником отдела без конкурса, мэр объяснил: «Это другой случай — сын у меня профессионал, я за него ручаюсь».","answer_id":"special_pleading","distractors":["tu_quoque","false_authority","no_true_scotsman","ad_hominem"],"offer_none":false,"highlight":"Это другой случай — сын у меня профессионал, я за него ручаюсь","explanation":"Конкурс и нужен, чтобы проверять профессионализм, а не полагаться на чьё-то поручительство. Мэр освобождает сына от правила по той самой причине, которую правило исключает.","nearest_distractor":"tu_quoque","contrast":"«Сам такой» сказал бы оппонент, отвергая требования мэра из-за назначения сына. Здесь ошибается сам мэр: он применяет правило ко всем, кроме своих.","pick_notes":{"false_authority":"Поручительство мэра звучит как ссылка на авторитет, но главная проблема не в нём: мэр делает для сына исключение из правила, которое сам ввёл для всех."}},{"id":"q116","batch":3,"difficulty":1,"text":"Мама запрещает детям сладкое перед сном: «От конфет на ночь портятся зубы». Вечером дети застали её на кухне с куском торта. «Мне можно, я же потом почищу зубы», — сказала мама. Почистить зубы дети тоже были готовы.","answer_id":"special_pleading","distractors":["tu_quoque","no_true_scotsman","appeal_to_pity","red_herring"],"offer_none":false,"highlight":"Мне можно, я же потом почищу зубы","explanation":"Причина, по которой мама освобождает себя от правила, в равной мере есть и у детей. Исключение сделано для себя без настоящего отличия.","nearest_distractor":"tu_quoque","contrast":"Дети маме ничего не возражают — ошибку делает она сама, применяя правило ко всем, кроме себя. «Сам такой» был бы, если бы дети сказали: «Ты сама ешь торт, так что нам тоже можно»."},{"id":"q117","batch":3,"difficulty":2,"text":"Страховой агент говорит клиенту: «Вы же не хотите, чтобы ваша семья осталась на улице, если с вами что-то случится? Подписывайте сегодня — завтра этот тариф может исчезнуть навсегда». Сравнить условия с другими страховыми он отсоветовал: «Пока вы сравниваете, может стать поздно».","answer_id":"appeal_to_fear","distractors":["appeal_to_pity","false_dilemma","appeal_to_consequences","slippery_slope"],"offer_none":true,"highlight":"Вы же не хотите, чтобы ваша семья осталась на улице, если с вами что-то случится?","explanation":"Страхование жизни может быть разумным решением, но агент не приводит ни одного довода в пользу именно этого полиса. Он давит страхом за семью и искусственной спешкой, мешая сравнить предложения.","nearest_distractor":"appeal_to_pity","contrast":"Агент не просит пожалеть его — он пугает клиента последствиями для семьи. Эмоция здесь — страх, а не сочувствие."},{"id":"q118","batch":3,"difficulty":1,"text":"Накануне выборов главы посёлка по почтовым ящикам разложили листовки: «Если победит Петров, в посёлке закроют школу и амбулаторию. Не допустите этого!» Ни в программе Петрова, ни в его выступлениях ничего подобного не было.","answer_id":"appeal_to_fear","distractors":["slippery_slope","ad_hominem","appeal_to_consequences","false_dilemma"],"offer_none":false,"highlight":"Если победит Петров, в посёлке закроют школу и амбулаторию","explanation":"Угроза ничем не подкреплена: в программе кандидата таких планов нет. Листовка пытается повлиять на выбор страхом, а не доводами.","nearest_distractor":"slippery_slope","contrast":"Скользкая дорожка — цепочка «одно потянет за собой другое». Здесь цепочки нет: одна голословная угроза."},{"id":"q119","batch":3,"difficulty":1,"text":"Пылесос сломался через неделю. Когда Нина начала писать отзыв на одну звезду, продавец прислал сообщение: «Пожалуйста, не ставьте низкую оценку! У нас маленький семейный бизнес, мы и так еле сводим концы с концами, один плохой отзыв нас погубит».","answer_id":"appeal_to_pity","distractors":["appeal_to_fear","red_herring","appeal_to_consequences","special_pleading"],"offer_none":false,"highlight":"У нас маленький семейный бизнес, мы и так еле сводим концы с концами, один плохой отзыв нас погубит","explanation":"Отзыв нужен, чтобы рассказать другим покупателям о качестве товара. Трудности продавца могут вызывать сочувствие, но пылесос от этого не заработал. Высокую оценку выпрашивают жалостью, вместо того чтобы исправить проблему.","nearest_distractor":"appeal_to_fear","contrast":"Продавец не угрожает Нине — он просит пожалеть его. «Погубит» здесь — о его беде, а не угроза покупательнице.","pick_notes":{"appeal_to_consequences":"Продавец не спорит с тем, что пылесос сломался, — он просит не говорить об этом из сочувствия к нему. Последствия здесь — повод для жалости, а не довод о качестве пылесоса."}},{"id":"q120","batch":3,"difficulty":2,"text":"На собеседовании на должность руководителя отдела сотрудник говорит: «Мне очень нужна эта должность: у меня ипотека, мама болеет, и я столько переживал из-за этого конкурса, что неделю не спал». О своём опыте управления людьми он так ничего и не рассказал.","answer_id":"appeal_to_pity","distractors":["red_herring","appeal_to_fear","special_pleading","appeal_to_consequences"],"offer_none":true,"highlight":"у меня ипотека, мама болеет, и я столько переживал из-за этого конкурса, что неделю не спал","explanation":"Руководителем назначают того, кто лучше справится с руководством. Жизненные трудности кандидата вызывают сочувствие, но ничего не говорят о его управленческих навыках.","nearest_distractor":"red_herring","also_accepted":[{"id":"red_herring","note":"Это действительно уход от главного вопроса — об опыте управления. Но когда отвлечение держится именно на сочувствии, точнее назвать его апелляцией к жалости."}],"contrast":"Это тоже уход от главного вопроса, но особого рода: внимание переводят на трудности кандидата, чтобы вызвать сочувствие."},{"id":"q121","batch":3,"difficulty":1,"text":"Соседи рассказали, что пёс Рекс покусал мальчика на детской площадке. Хозяйка возмутилась: «Не может быть! Если это правда, Рекса придётся отдать кинологам или даже усыпить. Значит, мальчик что-то путает».","answer_id":"appeal_to_consequences","distractors":["appeal_to_pity","appeal_to_fear","ad_hominem","fallacy_fallacy"],"offer_none":false,"highlight":"Если это правда, Рекса придётся отдать кинологам или даже усыпить. Значит, мальчик что-то путает","explanation":"Тяжёлые последствия никак не влияют на то, что произошло. Покусал ли пёс мальчика, выясняют по свидетелям и следам укуса, а не по тому, насколько хозяйке больно это признать.","nearest_distractor":"appeal_to_pity","contrast":"Хозяйка не просит её пожалеть — она отвергает сам факт, потому что его последствия для неё невыносимы."},{"id":"q122","batch":3,"difficulty":3,"text":"На совещании аналитик показал, что новый продукт за полгода не окупил даже рекламу. Директор отрезал: «Проект не мог провалиться. Если это провал, всем урежут премии, а акционеры потребуют моей отставки. Значит, в ваших расчётах ошибка».","answer_id":"appeal_to_consequences","distractors":["appeal_to_fear","ad_hominem","sunk_cost","appeal_to_ignorance"],"offer_none":true,"highlight":"Если это провал, всем урежут премии, а акционеры потребуют моей отставки. Значит, в ваших расчётах ошибка","explanation":"Неприятные последствия для премий и карьеры директора не делают расчёты неверными. Ошибку в расчётах ищут в расчётах.","nearest_distractor":"appeal_to_fear","contrast":"Директор никого не запугивает, чтобы склонить к решению; он сам отвергает факт из-за того, чем этот факт для него обернётся."},{"id":"q123","batch":3,"difficulty":2,"text":"Тётя Галя ставит племяннику горчичники при бронхите: «Горчичники ставили всегда — и мне в детстве, и моей маме. Раз столько поколений ставили, значит, они помогают». Педиатр в поликлинике сказала, что доказанной пользы у горчичников нет.","answer_id":"appeal_to_tradition","distractors":["appeal_to_nature","bandwagon","false_authority","appeal_to_novelty"],"offer_none":false,"highlight":"Горчичники ставили всегда — и мне в детстве, и моей маме. Раз столько поколений ставили, значит, они помогают","explanation":"Давность обычая не доказывает, что он работает. Эффективность лечения проверяют исследованиями, а не числом поколений, которые им пользовались.","nearest_distractor":"appeal_to_nature","contrast":"Тётя не говорит, что горчица натуральная и потому полезна, — её довод держится на давности.","pick_notes":{"bandwagon":"Тётя ссылается не на то, что так делают многие сейчас, а на то, что так делали всегда, из поколения в поколение. Это апелляция к традиции."}},{"id":"q124","batch":3,"difficulty":2,"text":"Тимлид предлагает переписать работающий интернет-магазин на фреймворк, вышедший месяц назад: «Он самый новый, значит, современнее и лучше нашего. Не сидеть же на старье». Магазин стабильно работает три года, а у нового фреймворка ещё нет ни одной стабильной версии.","answer_id":"appeal_to_novelty","distractors":["appeal_to_tradition","bandwagon","false_authority","sunk_cost"],"offer_none":false,"highlight":"Он самый новый, значит, современнее и лучше нашего","explanation":"Новизна сама по себе не делает инструмент лучше. Переписывать работающую систему стоит ради конкретных преимуществ, а у нового фреймворка нет даже стабильной версии.","nearest_distractor":"appeal_to_tradition","contrast":"Зеркальную ошибку сделал бы тот, кто сказал: «Три года работает — значит, менять ничего нельзя». Тимлид же превозносит новизну."},{"id":"q125","batch":3,"difficulty":2,"text":"Министерство опубликовало данные: в школах, где на ученика приходится больше компьютеров, выше средний балл выпускных экзаменов. Чиновник предложил: «Закупим отстающим школам компьютеры — и баллы вырастут». Школы с большим числом компьютеров в основном находятся в богатых районах, где у учеников есть и репетиторы.","answer_id":"cum_hoc","distractors":["post_hoc","hasty_generalization","false_analogy","misleading_statistics"],"offer_none":true,"highlight":"Закупим отстающим школам компьютеры — и баллы вырастут","explanation":"Компьютеры и высокие баллы встречаются вместе, но оба могут объясняться третьим фактором — достатком района, а с ним репетиторами и сильными учителями. Сами по себе компьютеры баллы могут и не поднять.","nearest_distractor":"post_hoc","contrast":"Чиновник не опирается на то, что баллы выросли после закупки компьютеров: он видит, что два показателя встречаются вместе, и принимает это за причину."},{"id":"q126","batch":3,"difficulty":2,"text":"На теледебатах мэр заявил: «За время моей работы безработица в городе снижалась — в марте, мае и сентябре!» Оппонент достал таблицу: в остальные девять месяцев безработица росла, и за год она увеличилась на треть.","answer_id":"cherry_picking","distractors":["misleading_statistics","hasty_generalization","survivorship","red_herring"],"offer_none":false,"highlight":"безработица в городе снижалась — в марте, мае и сентябре!","explanation":"Мэр называет только удачные месяцы и умалчивает об остальных девяти, когда безработица росла. Каждый названный факт верен, но вместе они создают ложную картину.","nearest_distractor":"misleading_statistics","contrast":"Мэр не искажает подачу цифр (проценты, базу сравнения) — он просто выбирает, какие факты упомянуть, а какие нет."},{"id":"q127","batch":3,"difficulty":3,"text":"Во время войны инженеры изучали бомбардировщики, вернувшиеся с заданий: больше всего пробоин было на крыльях и хвосте. Командование решило: «Усилим броню там, где больше всего попаданий». Математик возразил, что укреплять нужно двигатели: самолёты с пробоинами в двигателях просто не вернулись.","answer_id":"survivorship","distractors":["hasty_generalization","cherry_picking","cum_hoc","misleading_statistics"],"offer_none":true,"highlight":"Усилим броню там, где больше всего попаданий","explanation":"Изучали только вернувшиеся самолёты. Пробоины на крыльях показывают, куда можно получить попадание и всё равно долететь. Самолёты, получившие попадание в двигатель, не вернулись — их в выборке нет, поэтому выводы перевёрнуты с ног на голову.","nearest_distractor":"hasty_generalization","contrast":"Поспешное обобщение — общая категория. Здесь её частный случай: выборка состоит только из «выживших», и именно это искажает вывод."},{"id":"q128","batch":3,"difficulty":2,"text":"В вакансии крупной компании написано: «Средняя зарплата наших сотрудников — 300 тысяч рублей!» Из годового отчёта той же компании видно, что генеральный директор получает десятки миллионов, а у большинства сотрудников зарплата около пятидесяти тысяч.","answer_id":"misleading_statistics","distractors":["cherry_picking","hasty_generalization","cum_hoc","false_authority"],"offer_none":false,"highlight":"Средняя зарплата наших сотрудников — 300 тысяч рублей!","explanation":"Среднее арифметическое посчитано честно, но огромная зарплата директора тянет его вверх. Типичный сотрудник получает около пятидесяти тысяч — это показала бы медиана. Выбор показателя создаёт ложное впечатление.","nearest_distractor":"cherry_picking","contrast":"Никакие данные не скрыты — в среднее вошли все зарплаты. Манипуляция в выборе показателя, а не в отборе фактов."},{"id":"q129","batch":3,"difficulty":3,"text":"В передаче о прививках ведущий пригласил эпидемиолога, опиравшегося на многолетние исследования, и блогера, уверенного, что прививки вызывают аутизм. В конце ведущий подвёл итог: «Как всегда, истина где-то посередине: видимо, прививки иногда вызывают аутизм».","answer_id":"middle_ground","distractors":["false_dilemma","false_authority","nirvana","appeal_to_fear"],"offer_none":true,"highlight":"Как всегда, истина где-то посередине: видимо, прививки иногда вызывают аутизм","explanation":"Середина между доказанным фактом и необоснованным мнением не становится истиной. Связь прививок с аутизмом многократно проверяли на миллионах детей и не нашли. Ведущий уравнял позиции с очень разным весом доказательств.","nearest_distractor":"false_dilemma","contrast":"Ведущий не сводит выбор к двум вариантам — он придумывает третий, «средний», и объявляет его истинным только потому, что тот посередине.","pick_notes":{"false_authority":"Блогер действительно не эксперт, но ведущий не ссылается на его авторитет — он считает, что истина лежит между двумя мнениями, независимо от их обоснованности."}},{"id":"q130","batch":3,"difficulty":2,"text":"На публичных слушаниях о велодорожках один из жителей заявил: «Какой в этом смысл? Полгода у нас зима, и всё равно никто по ним зимой ездить не будет». По данным мэрии, в тёплое время года на велосипедах ездят около тридцати тысяч горожан.","answer_id":"nirvana","distractors":["false_dilemma","appeal_to_ignorance","middle_ground","hasty_generalization"],"offer_none":true,"highlight":"Полгода у нас зима, и всё равно никто по ним зимой ездить не будет","explanation":"Велодорожки не решают проблему круглый год, но полгода ими пользуются тысячи людей. Отвергать решение только потому, что оно не идеально, — ошибка нирваны.","nearest_distractor":"none","contrast":"Возражение было бы разумным, если бы зимний простой делал велодорожки бесполезными в целом. Но полгода они работают: решение улучшает положение, хоть и не идеально."},{"id":"q131","batch":3,"difficulty":3,"text":"Реклама банка: «Мы работаем с 1995 года — поэтому у нас самые выгодные ставки по вкладам в городе!» Сравнение на финансовом портале показывает, что ставки этого банка ниже средних.","answer_id":"non_sequitur","distractors":["appeal_to_tradition","false_authority","misleading_statistics","circular"],"offer_none":false,"highlight":"Мы работаем с 1995 года — поэтому у нас самые выгодные ставки по вкладам в городе!","explanation":"Возраст банка может говорить о его устойчивости, но о размере ставок не говорит ничего. Между «давно работаем» и «самые выгодные ставки» нет связи — вывод просто не следует.","nearest_distractor":"appeal_to_tradition","contrast":"Апелляция к традиции — «так делали всегда, значит, правильно». Банк не утверждает, что его ставки правильны, потому что традиционны; он выводит выгодность из возраста, хотя одно с другим не связано."},{"id":"q132","batch":3,"difficulty":2,"text":"Зоомагазин продаёт золотых рыбок вместе с круглыми аквариумами на три литра. Продавец успокаивает покупателей: «Память у золотой рыбки — три секунды, так что в маленьком аквариуме ей не скучно: каждый круг для неё новый». Исследования показывают, что золотые рыбки помнят события месяцами и поддаются дрессировке.","answer_id":"false_premise","distractors":["non_sequitur","false_authority","circular","appeal_to_ignorance"],"offer_none":false,"highlight":"Память у золотой рыбки — три секунды","explanation":"Вывод аккуратно следует из посылки, но посылка — популярный миф: рыбки помнят события месяцами. Рассуждение на ложном основании ничего не доказывает.","nearest_distractor":"non_sequitur","contrast":"Если бы память рыбки и правда длилась три секунды, вывод был бы почти разумным. Ошибка не в переходе, а в фундаменте."},{"id":"q133","batch":3,"difficulty":1,"text":"Реклама курса личностного роста: «Учёные доказали, что человек использует мозг лишь на десять процентов. Наш курс за двадцать тысяч рублей научит задействовать остальные девяносто!»","answer_id":"false_premise","distractors":["false_authority","appeal_to_ignorance","circular","hasty_generalization"],"offer_none":true,"highlight":"человек использует мозг лишь на десять процентов","explanation":"Миф о «десяти процентах» давно опровергнут: томография показывает, что в течение дня активны практически все области мозга. Обещание курса построено на ложной посылке.","nearest_distractor":"false_authority","also_accepted":[{"id":"false_authority","note":"Ссылка на безымянных «учёных» — действительно приём ложного авторитета. Но главная беда глубже: никакого такого доказательства нет, сама посылка ложна."}],"contrast":"«Учёные доказали» звучит как ссылка на авторитет, но главное не в ней: посылка ложна. Будь утверждение верным, ссылка на учёных была бы уместна."},{"id":"q134","batch":3,"difficulty":1,"text":"— Когда человек влюблён, он становится рассеянным, — рассуждает секретарша. — А наша бухгалтер на этой неделе дважды перепутала счета. Значит, влюбилась! Бухгалтер тем временем третью ночь подряд сидела над квартальным отчётом.","answer_id":"affirming_consequent","distractors":["denying_antecedent","non_sequitur","hasty_generalization","post_hoc"],"offer_none":false,"highlight":"А наша бухгалтер на этой неделе дважды перепутала счета. Значит, влюбилась!","explanation":"Влюблённость — лишь одна из причин рассеянности: усталость, недосып, болезнь дают тот же эффект. Из «если влюблён — рассеян» нельзя вывести «рассеян — значит, влюблён».","nearest_distractor":"denying_antecedent","contrast":"Отрицание основания звучало бы так: «Она не влюблена — значит, не будет путать счета». Секретарша же идёт от следствия к причине."},{"id":"q135","batch":3,"difficulty":3,"text":"Учитель говорит: «Наберёшь сто баллов — гарантированно поступишь на бюджет». Миша набрал девяносто два и расстроился: «Не сто — значит, на бюджет мне не поступить». В прошлом году проходной балл на его факультет был восемьдесят пять.","answer_id":"denying_antecedent","distractors":["affirming_consequent","non_sequitur","false_dilemma","nirvana"],"offer_none":false,"highlight":"Не сто — значит, на бюджет мне не поступить","explanation":"Учитель назвал сто баллов достаточным условием, но не необходимым. Из «если сто — то бюджет» не следует «если не сто — то не бюджет»: проходной балл ниже.","nearest_distractor":"affirming_consequent","contrast":"Утверждение следствия звучало бы так: «Поступил на бюджет — значит, набрал сто». Миша же отрицает условие и решает, что не будет и следствия."},{"id":"q136","batch":3,"difficulty":1,"text":"Новые жильцы старого дома по ночам слышат скрип на чердаке. Плотник, электрик и даже сосед-физик так и не смогли объяснить, откуда он. «Раз никто не может объяснить скрип — значит, у нас живёт привидение», — решила хозяйка.","answer_id":"appeal_to_ignorance","distractors":["fallacy_fallacy","false_authority","circular","hasty_generalization"],"offer_none":false,"highlight":"Раз никто не может объяснить скрип — значит, у нас живёт привидение","explanation":"То, что причину пока не нашли, не доказывает никакую конкретную причину, тем более сверхъестественную. Честный вывод — «причина пока неизвестна».","nearest_distractor":"fallacy_fallacy","contrast":"«Ошибка ошибки» выводит ложность тезиса из слабости довода. Хозяйка делает другое: выводит истинность своей версии из того, что других объяснений не нашли."},{"id":"q137","batch":3,"difficulty":3,"text":"Мама настаивает, чтобы сын в мороз надевал шапку: «Без шапки заболеешь от холода менингитом!» Сын прочитал, что менингит вызывают инфекции, а не холод, и торжествует: «Раз это миф, значит, шапка зимой вообще не нужна!» На улице минус двадцать пять.","answer_id":"fallacy_fallacy","distractors":["appeal_to_ignorance","straw_man","ad_hominem","hasty_generalization"],"offer_none":true,"highlight":"Раз это миф, значит, шапка зимой вообще не нужна!","explanation":"Мамин довод действительно неверен (это её собственная ошибка — ложное основание), но вывод «надевай шапку» от этого не становится ложным: в минус двадцать пять без шапки легко обморозить уши. Плохой аргумент не опровергает тезис.","nearest_distractor":"appeal_to_ignorance","contrast":"Апелляция к незнанию — «никто не доказал, значит, неверно» вообще. Здесь есть конкретный неудачный довод, и из его слабости выводят ложность самого тезиса."},{"id":"q138","batch":3,"difficulty":1,"text":"Восьмиклассник на уроке физики рассуждает: «Закон всемирного тяготения — это закон. Законы принимают депутаты. Значит, гравитацию придумали депутаты, и её можно отменить голосованием!»","answer_id":"equivocation","distractors":["false_analogy","false_premise","composition","genetic_fallacy"],"offer_none":false,"highlight":"Законы принимают депутаты","explanation":"«Закон» в физике — описание устойчивой закономерности природы, а «закон» в праве — правило, принятое людьми. Рассуждение держится на том, что слово используется в двух смыслах.","nearest_distractor":"false_analogy","also_accepted":[{"id":"false_premise","note":"Посылка «законы принимают депутаты» ложна для законов физики. Но она верна для законов права — и вся ошибка держится на смене смысла слова посреди рассуждения, поэтому точнее «подмена понятий»."}],"contrast":"Школьник не сравнивает две разные вещи по сходству — он незаметно меняет смысл одного и того же слова."},{"id":"q139","batch":3,"difficulty":2,"text":"Директор объясняет, почему не советуется с сотрудниками о новом графике работы: «Сотрудники — как дети. Детей же не спрашивают, во сколько им ложиться спать, — родители решают сами. Вот и я решу за всех».","answer_id":"false_analogy","distractors":["ad_hominem","equivocation","hasty_generalization","composition"],"offer_none":false,"highlight":"Сотрудники — как дети. Детей же не спрашивают, во сколько им ложиться спать","explanation":"Детей не спрашивают, потому что они не могут сами оценить последствия. Взрослые сотрудники могут — и лучше директора знают, как график скажется на их работе и жизни. Сходство поверхностное, в существенном ситуации различаются.","nearest_distractor":"ad_hominem","contrast":"Директор не опровергает ничей довод, нападая на личность; он строит решение на сравнении, которое не выдерживает проверки."},{"id":"q140","batch":3,"difficulty":3,"text":"Депутат выступает против государственного займа: «Государство — это та же семья. Нормальная семья не живёт в долг, значит, и государству занимать нельзя». Экономисты напоминают, что большинство семей в стране покупали жильё в ипотеку.","answer_id":"false_analogy","distractors":["false_premise","composition","hasty_generalization","appeal_to_tradition"],"offer_none":true,"highlight":"Государство — это та же семья. Нормальная семья не живёт в долг, значит, и государству занимать нельзя","explanation":"Государство отличается от семьи в существенном: оно может занимать на десятилетия вперёд, вкладывать в дороги и школы, которые окупятся налогами, и само выпускает деньги. Аналогия держится на внешнем сходстве — «бюджет есть и там, и там».","nearest_distractor":"false_premise","contrast":"Посылка «нормальная семья не живёт в долг» тоже сомнительна — вспомните ипотеку. Но даже будь она верной, перенос правила с семьи на государство не обоснован: главная ошибка — в сравнении."},{"id":"q141","batch":3,"difficulty":1,"text":"Комментатор перед чемпионатом: «Каждый игрок нашей сборной — лучший бомбардир своего клуба. Значит, сборная будет забивать больше всех и станет непобедимой». В первом же матче одиннадцать бомбардиров так и не договорились, кому отрабатывать в обороне.","answer_id":"composition","distractors":["division","hasty_generalization","false_analogy","false_authority"],"offer_none":false,"highlight":"Каждый игрок нашей сборной — лучший бомбардир своего клуба. Значит, сборная будет забивать больше всех","explanation":"Сила команды зависит не только от игроков по отдельности, но и от того, как они сочетаются: позиции, взаимодействие, оборона. Свойство частей не переходит на целое автоматически.","nearest_distractor":"division","contrast":"Ошибка деления шла бы от целого к части: «сборная сильная — значит, каждый игрок звезда». Комментатор идёт от частей к целому."},{"id":"q142","batch":3,"difficulty":2,"text":"— Кофе навынос за двести рублей — это же ерунда, — говорит Лера. — И такси за триста — ерунда, и подписка за двести девяносто девять. Каждая такая трата сама по себе бюджет не потопит, значит, и все вместе не потопят. В конце месяца Лера обнаружила, что «ерунда» съела треть зарплаты.","answer_id":"composition","distractors":["hasty_generalization","division","nirvana","false_analogy"],"offer_none":false,"highlight":"Каждая такая трата сама по себе бюджет не потопит, значит, и все вместе не потопят","explanation":"Свойство «незначительная» есть у каждой траты, но не у их суммы: десятки мелких трат складываются в серьёзные деньги. Свойство частей перенесено на целое.","nearest_distractor":"hasty_generalization","contrast":"Лера не делает вывода по малой выборке — она переносит свойство каждой части на их совокупность."},{"id":"q143","batch":3,"difficulty":2,"text":"Предприниматель выбирает банк: «Этот банк — один из крупнейших и самых надёжных в стране. Значит, и в его отделении у моего дома меня обслужат быстро и грамотно». В отделении у дома работали два стажёра, а очередь занимала весь коридор.","answer_id":"division","distractors":["composition","hasty_generalization","false_analogy","equivocation"],"offer_none":false,"highlight":"Этот банк — один из крупнейших и самых надёжных в стране. Значит, и в его отделении у моего дома меня обслужат быстро и грамотно","explanation":"Надёжность и размер банка в целом не означают, что каждое его отделение работает хорошо. Свойство целого перенесено на часть без проверки.","nearest_distractor":"composition","contrast":"Ошибка композиции идёт от частей к целому. Предприниматель идёт в обратную сторону — от целого к части."},{"id":"q144","batch":3,"difficulty":3,"text":"Школьник на олимпиаде рассуждает: «Вода тушит огонь. Вода состоит из водорода и кислорода. Значит, и водород тушит огонь — им можно заправлять огнетушители». Водород — один из самых горючих газов.","answer_id":"division","distractors":["composition","false_premise","equivocation","affirming_consequent"],"offer_none":true,"highlight":"Значит, и водород тушит огонь","explanation":"Свойства вещества не принадлежат его составным частям: водород горит, кислород поддерживает горение, а вода из них огонь тушит. Свойство целого перенесено на часть.","nearest_distractor":"composition","contrast":"Ошибка композиции шла бы от частей к целому: «водород горит — значит, и вода горит». Школьник идёт от целого к части."},{"id":"q145","batch":3,"difficulty":2,"text":"Дочка-пятиклассница просит разрешения завести аккаунт в новой соцсети. Мама сомневается в её безопасности, но дочка убеждает: «Там уже все наши одноклассники! Если бы она была опасной, столько людей бы там не сидело». По правилам самой соцсети регистрироваться можно только с тринадцати лет.","answer_id":"bandwagon","distractors":["false_premise","hasty_generalization","appeal_to_novelty","false_authority"],"offer_none":false,"highlight":"Если бы она была опасной, столько людей бы там не сидело","explanation":"Популярность среди одноклассников ничего не говорит о безопасности: об утечках данных, модерации, о том, кто пишет детям. Довод держится на количестве пользователей.","nearest_distractor":"false_premise","contrast":"Можно увидеть здесь ложную посылку — «в опасном месте люди бы не сидели». Но суть довода в другом: популярность выдаётся за доказательство безопасности, а это апелляция к большинству.","also_accepted":[{"id":"false_premise","note":"Формально довод опирается на скрытую посылку «в опасном месте люди бы не сидели», и она ложна. Но эта посылка и есть вера в то, что популярность гарантирует безопасность, — поэтому точнее «апелляция к большинству»."}]},{"id":"q146","batch":3,"difficulty":2,"text":"Электрик поднёс к розетке индикаторную отвёртку — её лампочка загорается, только когда на контакте есть напряжение. Лампочка загорелась, и электрик сказал хозяйке: «Розетка под напряжением, руками не трогайте, пока я не отключу автомат».","answer_id":"none","distractors":["false_authority","affirming_consequent","appeal_to_fear","hasty_generalization"],"offer_none":true,"highlight":"Розетка под напряжением, руками не трогайте","explanation":"Электрик — специалист именно в этом вопросе, а его вывод опирается на показания прибора. Лампочка загорается только при напряжении — значит, напряжение есть. Осторожность разумна.","nearest_distractor":"false_authority","contrast":"Ложный авторитет — когда ссылаются на статус вместо доказательств или на неподходящего эксперта. Здесь эксперт профильный, а вывод подкреплён измерением.","pick_notes":{"affirming_consequent":"Условие здесь стоит в форме «только если»: лампочка загорается только при напряжении. Из «загорается только при напряжении» и «загорелась» вывод «напряжение есть» корректен — это не утверждение следствия."}},{"id":"q147","batch":3,"difficulty":2,"text":"Из-под ванны течёт вода. Сантехник по телефону объясняет: «Если не перекрыть воду, она зальёт пол и просочится к соседям снизу; под полом проходит проводка, а мокрая проводка может замкнуть. Поэтому сначала перекройте стояк, а потом выключите электричество в щитке».","answer_id":"none","distractors":["slippery_slope","appeal_to_fear","false_dilemma","false_authority"],"offer_none":true,"highlight":"Поэтому сначала перекройте стояк, а потом выключите электричество в щитке","explanation":"Каждое звено цепочки физически обосновано: вода течёт вниз, проводка под полом действительно есть, вода проводит ток. Цепочка последствий реальна, и предосторожности разумны.","nearest_distractor":"slippery_slope","contrast":"Скользкая дорожка — когда звенья цепочки ничем не обоснованы. Здесь каждый шаг опирается на физику и устройство квартиры."},{"id":"q148","batch":3,"difficulty":3,"text":"Свидетель обвинения утверждал, что ночью разглядел номер машины подсудимого с расстояния ста метров. Адвокат предъявил медицинскую карту свидетеля: у него сильная близорукость, а очков в тот вечер, по его же словам, на нём не было.","answer_id":"none","distractors":["ad_hominem","red_herring","genetic_fallacy","tu_quoque"],"offer_none":true,"highlight":"у него сильная близорукость, а очков в тот вечер, по его же словам, на нём не было","explanation":"Зрение свидетеля прямо относится к тому, мог ли он разглядеть номер. Когда довод держится на показаниях человека, проверить, способен ли он был это увидеть, — законная критика, а не нападение на личность.","nearest_distractor":"ad_hominem","contrast":"Переход на личность — когда припоминают свойства человека, не связанные с обсуждаемым вопросом. Здесь свойство (зрение) и есть суть вопроса."},{"id":"q149","batch":3,"difficulty":3,"text":"Читатель возмущён, что словарь признал допустимым «кофе» среднего рода: «Если так говорят многие, это ещё не значит, что так правильно!» Лингвист отвечает: «В языке норма как раз и складывается из того, как говорит большинство образованных носителей. Словари не придумывают правила, а фиксируют употребление».","answer_id":"none","distractors":["bandwagon","false_authority","appeal_to_tradition","appeal_to_novelty"],"offer_none":true,"highlight":"В языке норма как раз и складывается из того, как говорит большинство образованных носителей","explanation":"Обычно «так считают многие» — не довод. Но языковая норма и есть договорённость носителей: правильность в языке определяется употреблением. Ссылка на большинство здесь уместна, потому что речь именно о том, как люди говорят.","nearest_distractor":"bandwagon","contrast":"Апелляция к большинству — ошибка, когда популярность выдают за доказательство факта, не зависящего от мнений (безопасности, пользы, истинности). Языковая норма от употребления как раз зависит."},{"id":"q150","batch":3,"difficulty":2,"text":"Прораб считает нагрузку на перекрытие: «Каждый кирпич весит около трёх с половиной килограммов, в стене две тысячи кирпичей. Значит, стена весит около семи тонн, плюс раствор».","answer_id":"none","distractors":["composition","hasty_generalization","division","misleading_statistics"],"offer_none":true,"highlight":"Значит, стена весит около семи тонн, плюс раствор","explanation":"Вес — свойство, которое складывается: вес целого действительно равен сумме весов частей. Перенос с частей на целое здесь корректен — в отличие от свойств вроде «вкусный» или «незначительный».","nearest_distractor":"composition","contrast":"Ошибка композиции — когда на целое переносят свойство, которое от сложения меняется. Вес от сложения не меняет своей природы, он просто суммируется."},{"id":"q151","batch":4,"difficulty":2,"text":"Волонтёр принёс в городской совет схему раздельного сбора мусора с подробными расчётами. Член совета ответил: «Человек трижды сменил работу за два года и ещё учит нас, как организовать город?» Расчёты на заседании так и не открыли.","answer_id":"ad_hominem","distractors":["red_herring","false_authority","genetic_fallacy","straw_man"],"offer_none":false,"highlight":"Человек трижды сменил работу за два года и ещё учит нас, как организовать город?","explanation":"Работает ли схема, показывают расчёты, а не трудовая биография автора. Предложение отвергнуто из-за того, кто его принёс, а сами доводы никто не рассмотрел.","nearest_distractor":"red_herring","contrast":"Это не просто смена темы: схему отвергают именно из-за биографии автора, чтобы не разбирать расчёты. Нападение на человека вместо довода — переход на личность."},{"id":"q152","batch":4,"difficulty":3,"text":"Перед выступлением экономиста ведущий дебатов предупредил зал: «Сейчас вы услышите мнение человека, который много лет консультировал банки, — сделайте выводы сами». Экономист собирался говорить о том, как снизить ставки по ипотеке.","answer_id":"ad_hominem","distractors":["genetic_fallacy","false_authority","straw_man","appeal_to_fear"],"offer_none":true,"highlight":"Сейчас вы услышите мнение человека, который много лет консультировал банки, — сделайте выводы сами","explanation":"Ведущий дискредитирует экономиста ещё до того, как прозвучал хоть один довод. Слушателям предлагают отвергнуть аргументы заранее — из-за прошлого автора. Этот приём называют «отравлением колодца»; это разновидность перехода на личность.","nearest_distractor":"none","contrast":"Сообщить о возможном конфликте интересов — нормально. Ошибка в предложении «сделать выводы» о доводах до того, как их услышали: оценку аргументов подменяют оценкой человека."},{"id":"q153","batch":4,"difficulty":1,"text":"Врач сказала пациенту, что с таким холестерином пора отказаться от фастфуда. Пациент усмехнулся: «Доктор, я вчера видел, как вы сами брали в буфете картошку фри. Так что не надо меня учить».","answer_id":"tu_quoque","distractors":["ad_hominem","special_pleading","red_herring","false_authority"],"offer_none":false,"highlight":"я вчера видел, как вы сами брали в буфете картошку фри. Так что не надо меня учить","explanation":"Холестерин пациента не станет ниже от того, что врач сама ест картошку фри. Совет отвергнут из-за непоследовательности советчика, а не из-за ошибки в нём.","nearest_distractor":"ad_hominem","contrast":"Переход на личность — общая категория. Здесь её частный случай: упрёк ровно в том, к чему врач призывает, — «сам такой»."},{"id":"q154","batch":4,"difficulty":3,"text":"Аудитор указал компании на нарушения в учёте командировочных расходов. Финансовый директор ответил: «В вашей же аудиторской фирме в прошлом году был скандал с поддельными отчётами. Так что ваши замечания мы обсуждать не будем».","answer_id":"tu_quoque","distractors":["ad_hominem","red_herring","genetic_fallacy","straw_man"],"offer_none":true,"highlight":"В вашей же аудиторской фирме в прошлом году был скандал с поддельными отчётами. Так что ваши замечания мы обсуждать не будем","explanation":"Нарушения в учёте либо есть, либо нет. Проблемы самой аудиторской фирмы не делают замечания аудитора неверными — их нужно проверить по документам компании.","nearest_distractor":"ad_hominem","contrast":"Переход на личность — общая категория. Здесь упрёк зеркальный: «у вас самих проблемы с отчётностью» — это «сам такой»."},{"id":"q155","batch":4,"difficulty":3,"text":"Блогер пишет: «Олимпийские игры придумали древние греки, чтобы прославлять языческих богов. Значит, современные Олимпиады — языческий праздник, и верующим спортсменам участвовать в них грешно». Современные Игры возродили в 1896 году как светское спортивное состязание.","answer_id":"genetic_fallacy","distractors":["appeal_to_tradition","ad_hominem","equivocation","false_premise"],"offer_none":true,"highlight":"Олимпийские игры придумали древние греки, чтобы прославлять языческих богов. Значит, современные Олимпиады — языческий праздник","explanation":"Нынешний смысл Олимпиад определяется тем, что они собой представляют сегодня, — светскими соревнованиями, а не тем, зачем похожие игры проводили две с половиной тысячи лет назад.","nearest_distractor":"appeal_to_tradition","contrast":"Блогер не говорит «так делали всегда, значит, правильно» — наоборот, он отвергает Олимпиады из-за их древнего происхождения. Оценка по происхождению — генетическая ошибка."},{"id":"q156","batch":4,"difficulty":3,"text":"Коллега предложил провести в инженерном отделе мозговой штурм. Начальник отказался: «Этот метод придумал рекламщик, чтобы его агентство продавало больше рекламы. Значит, для инженеров он не годится».","answer_id":"genetic_fallacy","distractors":["ad_hominem","false_analogy","appeal_to_novelty","straw_man"],"offer_none":false,"highlight":"Этот метод придумал рекламщик, чтобы его агентство продавало больше рекламы. Значит, для инженеров он не годится","explanation":"Метод мозгового штурма действительно придумал рекламщик, но годится ли он для инженеров, зависит от того, помогает ли он находить решения, а не от того, где его изобрели.","nearest_distractor":"ad_hominem","contrast":"Рекламщик ни с кем в отделе не спорит: начальник отвергает сам метод из-за того, кто и зачем его придумал. Это генетическая ошибка, а не атака на оппонента."},{"id":"q157","batch":4,"difficulty":1,"text":"Популярный рэпер в интервью уверенно заявил: «Египетские пирамиды строили не люди, а инопланетяне — я много читал на эту тему». Фанаты в комментариях пишут: «Раз он так сказал, значит, учебники истории врут».","answer_id":"false_authority","distractors":["bandwagon","ad_hominem","genetic_fallacy","appeal_to_novelty"],"offer_none":false,"highlight":"Раз он так сказал, значит, учебники истории врут","explanation":"Рэпер может быть прекрасным музыкантом, но в археологии он не специалист. Археологи нашли и каменоломни, и посёлки строителей пирамид, и их записи — мнение знаменитости этого не отменяет.","nearest_distractor":"bandwagon","contrast":"Фанаты ссылаются не на то, что так думают многие, а на мнение одного знаменитого человека, далёкого от археологии."},{"id":"q158","batch":4,"difficulty":2,"text":"Родители решают, делать ли сыну прививку от кори. Мама нашла видео, где фитнес-тренер с миллионом подписчиков рассказывает, что прививки ослабляют иммунитет. «Он же профессионально занимается здоровьем, ему виднее», — говорит она мужу.","answer_id":"false_authority","distractors":["bandwagon","appeal_to_nature","appeal_to_fear","genetic_fallacy"],"offer_none":false,"highlight":"Он же профессионально занимается здоровьем, ему виднее","explanation":"Фитнес-тренер разбирается в тренировках, а не в иммунологии. О вакцинах судят по исследованиям и мнению иммунологов, а не по профессии, которая лишь звучит похоже.","nearest_distractor":"bandwagon","contrast":"Мама ссылается не на число подписчиков, а на «профессионализм» тренера — в фитнесе, а не в иммунологии. Это ложный авторитет."},{"id":"q159","batch":4,"difficulty":2,"text":"На слушаниях о запрете продажи энергетиков подросткам депутат двадцать минут доказывал, что энергетики вредны для сердца. Спорили, однако, не об этом: противники запрета соглашались, что энергетики вредны, но сомневались, что запрет сработает, — подростки купят их через взрослых.","answer_id":"ignoratio_elenchi","distractors":["red_herring","straw_man","appeal_to_fear","cherry_picking"],"offer_none":false,"highlight":"депутат двадцать минут доказывал, что энергетики вредны для сердца","explanation":"Спорный тезис — «запрет сработает». Депутат доказывает другой, с которым и так никто не спорит, — «энергетики вредны». Вред энергетиков не отвечает на вопрос, уменьшит ли запрет их потребление.","nearest_distractor":"red_herring","contrast":"Депутат не уходит от темы — он говорит об энергетиках и о запрете. Но доказывает он не тот тезис, о котором спорят. Это подмена тезиса в общем виде.","pick_notes":{"straw_man":"Депутат не приписывает оппонентам мысль «энергетики полезны» и не опровергает её: он просто доказывает бесспорное вместо спорного.","cherry_picking":"Депутат не скрывает неудобные данные о вреде — он доказывает не тот тезис. Даже полный набор данных о вреде не ответил бы на вопрос, сработает ли запрет."}},{"id":"q160","batch":4,"difficulty":1,"text":"Начальник поставил задачу: «Клиенты жалуются, что слишком долго ждут ответа на линии. Разберитесь». Через неделю менеджер отчитался: «Готово — я убрал с сайта форму жалоб, жалоб ноль».","answer_id":"ignoratio_elenchi","distractors":["cherry_picking","red_herring","straw_man","nirvana"],"offer_none":false,"highlight":"Готово — я убрал с сайта форму жалоб, жалоб ноль","explanation":"Задача была сократить ожидание на линии, а менеджер выполнил другую — «чтобы жалоб не было». Клиенты ждут столько же, просто пожаловаться им теперь негде.","nearest_distractor":"cherry_picking","contrast":"Менеджер не отбирает удобные данные из имеющихся — он подменил саму цель: вместо «клиенты ждут меньше» выполнено «жалоб не видно».","pick_notes":{"red_herring":"Менеджер не уводит разговор в сторону: он отчитывается ровно о той задаче, но выполнил её подменённую версию.","straw_man":"Менеджер не спорит с начальником и не искажает его слова, чтобы их опровергнуть, — он молча выполняет другую задачу."}},{"id":"q161","batch":4,"difficulty":2,"text":"Экологи предложили запретить выбрасывать батарейки в общий мусорный бак и поставить во дворах контейнеры для них. Комментатор пишет: «Зелёные хотят, чтобы мы отказались от всей электроники и жили при свечах!»","answer_id":"straw_man","distractors":["ignoratio_elenchi","slippery_slope","red_herring","false_dilemma"],"offer_none":false,"highlight":"Зелёные хотят, чтобы мы отказались от всей электроники и жили при свечах!","explanation":"Предлагалось сдавать батарейки в отдельный контейнер, а не отказываться от электроники. Комментатор спорит с выдуманной крайней позицией, которую легко высмеять.","nearest_distractor":"ignoratio_elenchi","contrast":"Подмена тезиса — общая категория. Здесь её частный случай: позицию оппонентов доводят до абсурда, чтобы с ней было легко спорить, — соломенное чучело."},{"id":"q162","batch":4,"difficulty":3,"text":"В дискуссии о школьных оценках психолог сказала: «Оценки не всегда отражают знания: у тревожных детей на контрольных результат хуже их реального уровня». Оппонент ответил: «Если оценки ничего не значат, давайте сразу отменим экзамены и будем выдавать аттестаты всем подряд».","answer_id":"straw_man","distractors":["ignoratio_elenchi","slippery_slope","false_dilemma","red_herring"],"offer_none":true,"highlight":"Если оценки ничего не значат, давайте сразу отменим экзамены","explanation":"Психолог сказала «не всегда отражают», а оппонент спорит с «ничего не значат». Осторожное утверждение заменено крайним, и опровергается уже оно.","nearest_distractor":"slippery_slope","contrast":"Оппонент не выводит цепочку последствий из слов психолога — он сразу заменяет её «не всегда» на «ничего не значат» и спорит с этим."},{"id":"q163","batch":4,"difficulty":2,"text":"Журналист спросил директора строительной компании, почему у нового дома через полгода треснул фасад. Директор ответил: «А вы знаете, сколько налогов мы платим в городской бюджет? Мы, можно сказать, содержим половину района!»","answer_id":"red_herring","distractors":["ignoratio_elenchi","tu_quoque","straw_man","appeal_to_pity"],"offer_none":false,"highlight":"А вы знаете, сколько налогов мы платим в городской бюджет?","explanation":"Налоги компании не объясняют трещину в фасаде. Вопрос остаётся без ответа, а разговор переводится на заслуги компании.","nearest_distractor":"ignoratio_elenchi","contrast":"Подмена тезиса — общая категория. Здесь её частный случай: разговор уводят на постороннюю тему — отвлекающий манёвр."},{"id":"q164","batch":4,"difficulty":3,"text":"— Ты брал мою зарядку? Она опять пропала, — спрашивает сестра. — Слушай, а ты помнишь, что обещала вернуть мне двести рублей ещё в прошлом месяце? — отвечает брат.","answer_id":"red_herring","distractors":["tu_quoque","ignoratio_elenchi","ad_hominem","loaded_question"],"offer_none":true,"highlight":"а ты помнишь, что обещала вернуть мне двести рублей ещё в прошлом месяце?","explanation":"Вопрос был про зарядку. Долг сестры, даже если он есть, никак не отвечает, брал ли брат зарядку. Разговор уводят на другую тему.","nearest_distractor":"tu_quoque","contrast":"«Сам такой» — упрёк в том же самом: «ты сама берёшь мои вещи». Брат вспоминает другое — долг, то есть просто меняет тему.","pick_notes":{"ad_hominem":"Брат не утверждает, что из-за долга сестра не вправе спрашивать о зарядке, — он просто переводит разговор на другую тему."}},{"id":"q165","batch":4,"difficulty":2,"text":"Ведущий ток-шоу спрашивает гостя-министра: «Когда вы наконец прекратите скрывать от людей реальную инфляцию?» Министерство ежемесячно публикует и данные об инфляции, и методику их расчёта.","answer_id":"loaded_question","distractors":["straw_man","false_premise","ad_hominem","appeal_to_fear"],"offer_none":false,"highlight":"Когда вы наконец прекратите скрывать от людей реальную инфляцию?","explanation":"Вопрос уже содержит обвинение — «вы скрываете инфляцию». Любой прямой ответ («скоро», «никогда») его подтверждает. Честный ход — сначала спросить, скрывает ли министерство что-нибудь.","nearest_distractor":"straw_man","contrast":"Ведущий не спорит с позицией министра и не опровергает её — он задаёт вопрос, в который уже встроено недоказанное обвинение.","pick_notes":{"false_premise":"Обвинение действительно не доказано. Но из него ничего не выводят — его прячут в вопрос, чтобы любой ответ его признавал. Это сложный вопрос."}},{"id":"q166","batch":4,"difficulty":3,"text":"Адвокат на перекрёстном допросе спрашивает свидетеля: «Сколько бокалов вы выпили в тот вечер, прежде чем сесть за руль?» Свидетель в тот вечер действительно был за рулём, но не пил вообще.","answer_id":"loaded_question","distractors":["false_premise","straw_man","ad_hominem","red_herring"],"offer_none":true,"highlight":"Сколько бокалов вы выпили в тот вечер, прежде чем сесть за руль?","explanation":"Вопрос «сколько» уже предполагает, что свидетель пил. Ответ «один» или «два» это признаёт, а ответ «ноль» звучит как оправдание.","nearest_distractor":"none","contrast":"Спросить, пил ли свидетель, — законно. Ошибка в том, что вопрос «сколько» заранее принимает ответ «да».","pick_notes":{"false_premise":"Допущение «свидетель пил» не доказано, но адвокат его не утверждает — он прячет его в вопрос. Это сложный вопрос."}},{"id":"q167","batch":4,"difficulty":2,"text":"— Настоящий итальянец ни за что не положит в пасту кетчуп, — уверяет повар. — Мой знакомый из Неаполя каждый день ест макароны с кетчупом, — возражает посетитель. — Значит, он давно уже не настоящий итальянец.","answer_id":"no_true_scotsman","distractors":["hasty_generalization","special_pleading","equivocation","circular"],"offer_none":false,"highlight":"Значит, он давно уже не настоящий итальянец","explanation":"Неаполитанец — итальянец, что бы он ни ел. Повар, получив контрпример, не пересматривает обобщение, а исключает неудобного итальянца из «настоящих».","nearest_distractor":"hasty_generalization","contrast":"Само утверждение повара — поспешное обобщение, но подсвечен следующий ход: контрпример не признают, а отбрасывают, переопределив «настоящего итальянца»."},{"id":"q168","batch":4,"difficulty":3,"text":"Автор диеты утверждает: «Кто соблюдает нашу диету правильно, тот обязательно худеет». Читательница пишет: «Я три месяца соблюдала всё по списку и не похудела». Ответ: «Значит, вы соблюдали неправильно — у тех, кто соблюдает правильно, результат есть всегда».","answer_id":"no_true_scotsman","distractors":["circular","special_pleading","hasty_generalization","appeal_to_ignorance"],"offer_none":true,"highlight":"Значит, вы соблюдали неправильно","explanation":"Контрпример отбрасывают переопределением: «правильно соблюдает» теперь значит «тот, кто похудел». Утверждение стало неопровержимым — и пустым.","nearest_distractor":"circular","contrast":"Круг действительно возникает: «правильно» определено через результат. Но возник он из-за того, что понятие подогнали задним числом, чтобы спасти обобщение, — это «настоящий шотландец».","also_accepted":[{"id":"circular","note":"Верно: после подгонки определения утверждение стало круговым — «кто худеет, тот соблюдает правильно, а кто соблюдает правильно, тот худеет». Но ход, который к этому привёл, — переопределение задним числом, «настоящий шотландец»."}]},{"id":"q169","batch":4,"difficulty":2,"text":"Блогер регулярно разоблачает коллег за скрытую рекламу: «Не пометил рекламу — значит, обманываешь зрителей». Когда подписчики заметили у него в видео непомеченную рекламу кофе, он ответил: «Это другое — я этот кофе правда люблю».","answer_id":"special_pleading","distractors":["tu_quoque","no_true_scotsman","red_herring","appeal_to_pity"],"offer_none":false,"highlight":"Это другое — я этот кофе правда люблю","explanation":"Правило о пометке рекламы не делает исключения для любимых продуктов: зрителю важно знать, что за упоминание заплатили. Блогер освобождает себя от правила, которого требует от других.","nearest_distractor":"tu_quoque","contrast":"«Сам такой» сказали бы подписчики, отвергая его разоблачения из-за его рекламы. Здесь ошибается сам блогер: он придумывает для себя исключение."},{"id":"q170","batch":4,"difficulty":3,"text":"Профессор требует от студентов ссылаться на источники в каждой курсовой: «Без ссылок — это плагиат». В его собственном учебнике целая глава пересказывает чужую статью без единой ссылки. На вопрос студентов он ответил: «Учебник — жанр популярный, там ссылки только мешают».","answer_id":"special_pleading","distractors":["tu_quoque","no_true_scotsman","equivocation","red_herring"],"offer_none":true,"highlight":"Учебник — жанр популярный, там ссылки только мешают","explanation":"Жанр мог бы оправдать меньшее число ссылок, но не пересказ чужой работы без указания автора — а ведь именно это профессор называет плагиатом. Исключение для себя сделано без настоящего отличия.","nearest_distractor":"none","contrast":"Различие жанров действительно бывает: в популярной книге не обязательно ставить ссылку на каждую фразу. Но правило профессора — о присвоении чужого текста, и для учебника оно работает так же."},{"id":"q171","batch":4,"difficulty":1,"text":"Кафе у вокзала вывесило табличку: «Нас выбрали уже 100 000 гостей! Значит, у нас самая вкусная шаурма в городе». Другого кафе у вокзала, правда, нет.","answer_id":"bandwagon","distractors":["misleading_statistics","false_authority","hasty_generalization","appeal_to_tradition"],"offer_none":false,"highlight":"Нас выбрали уже 100 000 гостей! Значит, у нас самая вкусная шаурма в городе","explanation":"Число посетителей говорит о проходимости места, а не о вкусе. У вокзала гостей много просто потому, что больше поесть негде.","nearest_distractor":"misleading_statistics","contrast":"Цифра в сто тысяч может быть честной, и подана она без ухищрений. Ошибка в выводе: популярность выдаётся за доказательство качества."},{"id":"q172","batch":4,"difficulty":3,"text":"Начинающий инвестор объясняет, почему вложил все сбережения в акции малоизвестной компании: «За неделю их купили сорок тысяч частных инвесторов, цена выросла втрое. Раз их покупают все, значит, компания и правда столько стоит». Отчётности компания не публиковала ни разу.","answer_id":"bandwagon","distractors":["hasty_generalization","misleading_statistics","false_authority","appeal_to_novelty"],"offer_none":true,"highlight":"Раз их покупают все, значит, компания и правда столько стоит","explanation":"Ажиотаж показывает, что акции популярны, но не что компания чего-то стоит. Стоимость определяется её бизнесом и отчётностью, а их никто не видел.","nearest_distractor":"none","contrast":"Следить за интересом других инвесторов не запрещено — это может быть поводом изучить компанию. Ошибка в том, что сам ажиотаж принимается за доказательство ценности."},{"id":"q173","batch":4,"difficulty":2,"text":"Сотрудник предложил на совещании опробовать новую систему учёта задач. Начальник ответил: «Предлагай-предлагай. Только помни, что в конце квартала у нас сокращения, и я запомню, кто мешал работать».","answer_id":"appeal_to_fear","distractors":["appeal_to_consequences","ad_hominem","red_herring","straw_man"],"offer_none":false,"highlight":"Только помни, что в конце квартала у нас сокращения, и я запомню, кто мешал работать","explanation":"Начальник не приводит ни одного довода против системы — он угрожает, чтобы предложение отозвали. Хороша ли идея, от этой угрозы не зависит.","nearest_distractor":"appeal_to_consequences","contrast":"Начальник не утверждает, что идея неверна из-за неприятных последствий, — он запугивает, чтобы о ней перестали говорить. Это апелляция к страху (довод «к палке»)."},{"id":"q174","batch":4,"difficulty":3,"text":"Реклама охранной сигнализации: тёмная квартира, разбитое окно, тревожная музыка. Голос за кадром: «Каждые пять минут в стране совершается кража. Ваша квартира может быть следующей». Чем эта сигнализация лучше других и снижает ли она риск кражи, в ролике не говорится.","answer_id":"appeal_to_fear","distractors":["misleading_statistics","appeal_to_consequences","slippery_slope","bandwagon"],"offer_none":true,"highlight":"Ваша квартира может быть следующей","explanation":"Ролик ничего не сообщает о самой сигнализации — только нагнетает страх. Решение о покупке подталкивают тревогой, а не доводами.","nearest_distractor":"appeal_to_consequences","contrast":"Реклама не спорит с фактами из-за их неприятности — она пугает, чтобы склонить к покупке.","pick_notes":{"misleading_statistics":"Цифра «каждые пять минут» и правда подана без базы: на всю страну это не так много. Но ролик держится не на ней, а на нагнетании страха — подсвечен именно этот приём."}},{"id":"q175","batch":4,"difficulty":3,"text":"Автор рукописи пишет редактору: «Я писал этот роман восемь лет, пожертвовал ради него карьерой и семьёй. Неужели после всего этого вы его отклоните?» Редактор отметил, что сюжет романа почти дословно повторяет известный детектив.","answer_id":"appeal_to_pity","distractors":["sunk_cost","appeal_to_fear","special_pleading","appeal_to_consequences"],"offer_none":false,"highlight":"Я писал этот роман восемь лет, пожертвовал ради него карьерой и семьёй.","explanation":"Издавать роман или нет, решают по его качеству, а не по жертвам автора. Сочувствие к автору понятно, но сюжет от этого не становится оригинальным.","nearest_distractor":"sunk_cost","contrast":"Невозвратные затраты — когда сам человек продолжает вкладываться из-за уже потраченного. Автор же просит редактора принять роман из сочувствия к его жертвам — это апелляция к жалости."},{"id":"q176","batch":4,"difficulty":3,"text":"Сборщик пожертвований у метро просит прохожего показать документы фонда. Тот в ответ поднимает фотографию больного ребёнка: «Посмотрите на эти глаза! Неужели вы откажете из-за какой-то бумажки о регистрации?»","answer_id":"appeal_to_pity","distractors":["appeal_to_consequences","appeal_to_fear","special_pleading","ad_hominem"],"offer_none":true,"highlight":"Неужели вы откажете из-за какой-то бумажки о регистрации?","explanation":"Прохожий спрашивал, существует ли фонд и честен ли он. Вместо ответа ему показывают фото больного ребёнка: проверку честности подменяют сочувствием.","nearest_distractor":"appeal_to_consequences","contrast":"Сборщик не утверждает, что фонд честный, потому что иначе было бы плохо; он заменяет проверку документов давлением на жалость."},{"id":"q177","batch":4,"difficulty":1,"text":"Дедушка прочитал, что его любимый сериал признан худшим за десятилетие. «Ерунда, — заявил он. — Если бы он был плохим, выходило бы, что я двадцать лет смотрю ерунду. Значит, сериал хороший».","answer_id":"appeal_to_consequences","distractors":["sunk_cost","appeal_to_pity","appeal_to_fear","appeal_to_tradition"],"offer_none":false,"highlight":"Если бы он был плохим, выходило бы, что я двадцать лет смотрю ерунду. Значит, сериал хороший","explanation":"Неприятный для дедушки вывод не делает сериал лучше. Качество сериала оценивают по самому сериалу, а не по тому, приятно ли зрителю это признать.","nearest_distractor":"sunk_cost","contrast":"Дедушка не решает, продолжать ли смотреть из-за потраченных лет; он отвергает оценку сериала, потому что её последствия для его самолюбия обидны."},{"id":"q178","batch":4,"difficulty":3,"text":"Историк опубликовал архивные документы: прославленный земляк, в честь которого названа главная улица города, в молодости писал доносы на соседей. Местная газета ответила: «Это не может быть правдой: если признать это, придётся переименовывать улицу и переписывать школьные учебники краеведения».","answer_id":"appeal_to_consequences","distractors":["appeal_to_fear","ad_hominem","appeal_to_tradition","genetic_fallacy"],"offer_none":true,"highlight":"Это не может быть правдой: если признать это, придётся переименовывать улицу","explanation":"Подлинность документов проверяют экспертизой, а не тем, сколько хлопот принесёт их признание. Неудобные последствия не делают факт ложным.","nearest_distractor":"appeal_to_fear","contrast":"Газета никого не запугивает ради решения — она отвергает факт, потому что его признание обернётся неприятностями."},{"id":"q179","batch":4,"difficulty":1,"text":"Бабушка запрещает проветривать комнату, где лежит простуженный внук: «Испокон веку больных берегли от сквозняков. Значит, свежий воздух простуженным вреден». Педиатр, наоборот, советует проветривать регулярно.","answer_id":"appeal_to_tradition","distractors":["appeal_to_nature","bandwagon","false_authority","post_hoc"],"offer_none":false,"highlight":"Испокон веку больных берегли от сквозняков. Значит, свежий воздух простуженным вреден","explanation":"Давность обычая не доказывает его пользу. Врачи советуют проветривать: свежий воздух снижает концентрацию вирусов в комнате.","nearest_distractor":"appeal_to_nature","contrast":"Бабушка не говорит, что духота естественна, — она опирается на то, что так делали всегда."},{"id":"q180","batch":4,"difficulty":3,"text":"Совет директоров отклонил переход на четырёхдневную рабочую неделю, хотя в пилотном отделе её полгода тестировали и выработка выросла. «Пятидневка существует почти сто лет, — сказал председатель. — Если бы её можно было улучшить, это давно бы сделали».","answer_id":"appeal_to_tradition","distractors":["appeal_to_ignorance","bandwagon","sunk_cost","appeal_to_novelty"],"offer_none":true,"highlight":"Пятидневка существует почти сто лет","explanation":"Возраст пятидневки не доказывает, что лучше её ничего нет, — тем более что собственный пилот совета говорит об обратном.","nearest_distractor":"none","contrast":"Осторожность при больших переменах разумна. Но совет отбрасывает собственные данные пилота и опирается только на возраст пятидневки.","pick_notes":{"appeal_to_ignorance":"Председатель не говорит «никто не доказал, что четырёхдневка лучше» — наоборот, данные пилота есть. Его довод держится на том, что пятидневка существует давно."}},{"id":"q181","batch":4,"difficulty":1,"text":"В аптеке Ира выбирает между давно известным средством от изжоги и новым, вдвое дороже. «Возьму новое — раз новое, значит, его улучшили», — решает она. Фармацевт объясняет, что действующее вещество у них одно и то же.","answer_id":"appeal_to_novelty","distractors":["appeal_to_tradition","bandwagon","false_authority","appeal_to_nature"],"offer_none":false,"highlight":"раз новое, значит, его улучшили","explanation":"Новое лекарство не обязательно лучше старого: здесь действующее вещество одинаковое, отличается только упаковка и цена.","nearest_distractor":"appeal_to_tradition","contrast":"Зеркальной была бы мысль «старое — значит проверенное, беру его». Ира же выбирает по новизне."},{"id":"q182","batch":4,"difficulty":3,"text":"Стартап убеждает инвесторов: «Наша нейросеть ставит диагнозы по фотографии кожи. Врачебный осмотр — технология девятнадцатого века, а мы — технология будущего, значит, мы точнее». Сравнительных испытаний с врачами стартап не проводил.","answer_id":"appeal_to_novelty","distractors":["appeal_to_tradition","false_authority","bandwagon","false_analogy"],"offer_none":true,"highlight":"Врачебный осмотр — технология девятнадцатого века, а мы — технология будущего, значит, мы точнее","explanation":"Нейросеть может оказаться точнее врача — или нет; это показали бы сравнительные испытания. Довод «мы новее» ничего не говорит о точности.","nearest_distractor":"none","contrast":"Новые технологии действительно часто превосходят старые, и ссылаться на это можно — с данными. Без испытаний остаётся только новизна как довод."},{"id":"q183","batch":4,"difficulty":3,"text":"Ресторан убрал из меню борщ, который годами хвалили гости, и заменил его «авторским супом из ферментированной свёклы». На недовольные отзывы шеф ответил: «Классика устарела — современная кухня всегда интереснее».","answer_id":"appeal_to_novelty","distractors":["appeal_to_tradition","bandwagon","false_authority","middle_ground"],"offer_none":false,"highlight":"Классика устарела — современная кухня всегда интереснее","explanation":"«Современное» не значит «вкуснее»: гости как раз сравнили и предпочли борщ. Шеф отвечает не на отзывы, а ссылкой на новизну.","nearest_distractor":"appeal_to_tradition","contrast":"Апелляцию к традиции сделали бы гости, если бы сказали «борщ варили всегда — значит, он лучше». Шеф же превозносит новизну."},{"id":"q184","batch":4,"difficulty":1,"text":"Соседка лечит заболевшего кота: «Ветеринарные таблетки — сплошная химия. Дам ему травяную настойку, природа сама знает, что лечит». Кот третий день не ест.","answer_id":"appeal_to_nature","distractors":["appeal_to_tradition","false_authority","appeal_to_novelty","genetic_fallacy"],"offer_none":false,"highlight":"природа сама знает, что лечит","explanation":"«Природное» не значит «безопасное»: многие растения ядовиты для кошек, а спиртовые настойки им опасны. Лечение выбирают по действию, а не по происхождению.","nearest_distractor":"appeal_to_tradition","contrast":"Соседка не говорит «так лечили всегда» — она противопоставляет «природу» «химии»."},{"id":"q185","batch":4,"difficulty":2,"text":"На упаковке соли написано: «Гималайская розовая соль — природный продукт без обработки, поэтому она полезнее обычной». Розовый цвет ей придают примеси оксида железа, а по составу это почти тот же хлорид натрия.","answer_id":"appeal_to_nature","distractors":["appeal_to_novelty","bandwagon","false_authority","misleading_statistics"],"offer_none":false,"highlight":"природный продукт без обработки, поэтому она полезнее обычной","explanation":"Отсутствие обработки не делает соль полезнее: по составу она почти та же, а примеси в таких количествах на здоровье не влияют.","nearest_distractor":"appeal_to_novelty","contrast":"Производитель не говорит, что соль новая или модная, — он упирает на то, что она «природная»."},{"id":"q186","batch":4,"difficulty":3,"text":"Будущая мама отказывается от любой медицинской помощи в родах: «Женщины тысячи лет рожали сами — это естественный процесс. Значит, любое вмешательство только вредит». Врач отвечает, что решать ей, но «естественно» не значит «безопасно»: раньше роды были одной из главных причин смерти молодых женщин.","answer_id":"appeal_to_nature","distractors":["appeal_to_tradition","false_authority","hasty_generalization","appeal_to_fear"],"offer_none":true,"highlight":"это естественный процесс. Значит, любое вмешательство только вредит","explanation":"Естественность процесса не гарантирует его безопасности: без медицинской помощи роды часто заканчивались трагедией. Решение вправе принимать сама женщина, но довод «естественно — значит, безвредно» неверен.","nearest_distractor":"appeal_to_tradition","contrast":"«Тысячи лет» звучит как ссылка на традицию, но решающее слово — «естественный»: вред выводится из неестественности вмешательства.","also_accepted":[{"id":"appeal_to_tradition","note":"Ссылка на «тысячи лет» действительно сближает довод с традицией. Но решающий шаг — «естественно, значит, вмешательство вредит», поэтому точнее апелляция к природе."}]},{"id":"q187","batch":4,"difficulty":1,"text":"После того как в офисе поставили новый кулер, Петрович перестал болеть. «Это всё очищенная вода из кулера», — рассказывает он коллегам. В тот же месяц он бросил курить и начал ходить на работу пешком.","answer_id":"post_hoc","distractors":["hasty_generalization","cum_hoc","gamblers_fallacy","slippery_slope"],"offer_none":false,"highlight":"Это всё очищенная вода из кулера","explanation":"Здоровье улучшилось после появления кулера, но одновременно Петрович бросил курить и стал больше ходить. Совпадение во времени принято за причину.","nearest_distractor":"hasty_generalization","contrast":"Петрович не делает вывода обо всех людях — он приписывает причину по совпадению во времени, игнорируя другие объяснения."},{"id":"q188","batch":4,"difficulty":2,"text":"В январе правительство снизило налог на малый бизнес. К декабрю число новых предприятий выросло на четверть, и министр заявил: «Наша налоговая реформа дала результат». В соседних странах без всяких реформ число новых компаний выросло так же — экономика восстанавливалась после кризиса.","answer_id":"post_hoc","distractors":["cum_hoc","hasty_generalization","false_authority","cherry_picking"],"offer_none":false,"highlight":"Наша налоговая реформа дала результат","explanation":"Рост последовал за реформой, но такой же рост был и там, где реформ не было. Значит, его могло вызвать общее восстановление экономики.","nearest_distractor":"cum_hoc","contrast":"Здесь вывод опирается именно на порядок событий: «сначала реформа, потом рост». Корреляция без порядка во времени — другой случай."},{"id":"q189","batch":4,"difficulty":3,"text":"Ирина начала принимать витамин D в ноябре, а к марту перестала простужаться. «Вот что значит витамины!» — говорит она подруге. Простуды и так обычно идут на спад к весне.","answer_id":"post_hoc","distractors":["cum_hoc","hasty_generalization","gamblers_fallacy","misleading_statistics"],"offer_none":true,"highlight":"Вот что значит витамины!","explanation":"Простуды стали реже после начала приёма витаминов, но к весне они становятся реже и без них. Из одной последовательности событий причину не установить.","nearest_distractor":"none","contrast":"Витамин D мог и помочь — но вывод сделан только из того, что улучшение последовало за началом приёма. Проверить это можно было бы, сравнив с теми, кто витамины не пил."},{"id":"q190","batch":4,"difficulty":1,"text":"Колумнист заметил: в городах, где больше пожарных машин, больше и пожаров. «Выходит, пожарные машины как-то провоцируют пожары, — пишет он. — Может, не стоит покупать новые?»","answer_id":"cum_hoc","distractors":["post_hoc","hasty_generalization","false_analogy","slippery_slope"],"offer_none":false,"highlight":"Выходит, пожарные машины как-то провоцируют пожары","explanation":"Оба показателя зависят от третьего — размера города: в больших городах больше и домов, и пожаров, и пожарных машин.","nearest_distractor":"post_hoc","contrast":"Колумнист не опирается на то, что пожары начались после покупки машин, — он видит, что два показателя растут вместе, и делает вывод о причине."},{"id":"q191","batch":4,"difficulty":3,"text":"Исследование показало: дети, которые каждый день завтракают, учатся лучше. Директор школы распорядился раздавать всем бесплатные завтраки и пообещал родителям, что оценки вырастут.","answer_id":"cum_hoc","distractors":["post_hoc","hasty_generalization","false_authority","nirvana"],"offer_none":true,"highlight":"пообещал родителям, что оценки вырастут","explanation":"Завтраки полезны, но связь с оценками может объясняться третьим фактором: в семьях, где дети завтракают, обычно больше внимания к режиму и учёбе. Обещание опирается на корреляцию.","nearest_distractor":"none","contrast":"Раздавать завтраки — хорошее решение и само по себе. Ошибка только в обещании роста оценок: исследование показало связь, а не причину."},{"id":"q192","batch":4,"difficulty":3,"text":"Опрос показал: у людей, которые много сидят в соцсетях, чаще бывает депрессия. Блогер делает вывод: «Соцсети вызывают депрессию — удалите их, и вам станет лучше».","answer_id":"cum_hoc","distractors":["post_hoc","hasty_generalization","appeal_to_fear","misleading_statistics"],"offer_none":true,"highlight":"Соцсети вызывают депрессию","explanation":"Связь может идти и в обратную сторону: люди в депрессии чаще уходят в соцсети. Или обоим способствует третье — одиночество. Опрос показал совместность, а не направление причины.","nearest_distractor":"post_hoc","contrast":"Блогер не говорит, что депрессия началась после регистрации в соцсетях; он делает вывод о причине из того, что два явления встречаются вместе."},{"id":"q193","batch":4,"difficulty":1,"text":"Таня впервые поехала в Италию, и в первом же кафе ей нагрубил официант. Вернувшись, она рассказывает подругам: «Итальянцы — ужасно невежливый народ».","answer_id":"hasty_generalization","distractors":["cherry_picking","post_hoc","ad_hominem","gamblers_fallacy"],"offer_none":false,"highlight":"Итальянцы — ужасно невежливый народ","explanation":"Один грубый официант — не выборка, по которой можно судить о шестидесяти миллионах человек.","nearest_distractor":"cherry_picking","contrast":"Таня не отбирает удобные факты из многих — у неё просто всего один случай. Это поспешное обобщение."},{"id":"q194","batch":4,"difficulty":2,"text":"Новый сотрудник за первую неделю дважды опоздал — оба раза из-за поломки в метро. Начальник записал в характеристике: «Непунктуален, на него нельзя полагаться».","answer_id":"hasty_generalization","distractors":["ad_hominem","post_hoc","cherry_picking","false_premise"],"offer_none":false,"highlight":"Непунктуален, на него нельзя полагаться","explanation":"Два опоздания за неделю по внешней причине — слишком мало, чтобы судить о характере человека.","nearest_distractor":"cherry_picking","contrast":"Начальник не отбирает удобные факты: других данных о сотруднике у него просто нет. Вывод сделан по слишком малой выборке."},{"id":"q195","batch":4,"difficulty":3,"text":"Компания проверила новое приложение на пятнадцати сотрудниках собственного отдела разработки. Все пятнадцать разобрались в интерфейсе за минуту, и маркетологи написали в пресс-релизе: «Наше приложение интуитивно понятно любому пользователю».","answer_id":"hasty_generalization","distractors":["cherry_picking","bandwagon","misleading_statistics","composition"],"offer_none":true,"highlight":"Наше приложение интуитивно понятно любому пользователю","explanation":"Пятнадцать разработчиков — малая и к тому же нетипичная выборка: им интерфейс понятнее, чем, скажем, пенсионерам. Вывод о «любом пользователе» не обоснован.","nearest_distractor":"cherry_picking","contrast":"Неудачных результатов никто не скрывает — их просто не искали. Проблема в выборке: она мала и не похожа на реальных пользователей."},{"id":"q196","batch":4,"difficulty":2,"text":"Повар тщательно перемешал кастрюлю супа, зачерпнул одну ложку, попробовал и сказал: «Пересолено». Остальные сорок порций он пробовать не стал.","answer_id":"none","distractors":["hasty_generalization","cherry_picking","composition","false_authority"],"offer_none":true,"highlight":"Пересолено","explanation":"Одна ложка — маленькая выборка, но суп тщательно перемешан, поэтому любая ложка похожа на всю кастрюлю. Если выборка действительно представительна, хватает и малой.","nearest_distractor":"hasty_generalization","contrast":"Поспешное обобщение — вывод по малой или нерепрезентативной выборке. Здесь выборка мала, но представительна: перемешанный суп одинаков во всех ложках."},{"id":"q197","batch":4,"difficulty":2,"text":"Агроном разделил поле на две части: одну удобрил, другую нет; семена, полив и почва везде одинаковые. На удобренной части урожай оказался на треть выше, и агроном заключил, что удобрение работает.","answer_id":"none","distractors":["post_hoc","cum_hoc","hasty_generalization","false_authority"],"offer_none":true,"highlight":"агроном заключил, что удобрение работает","explanation":"Это сравнение с контролем: всё, кроме удобрения, одинаково, поэтому разницу в урожае можно приписать именно ему.","nearest_distractor":"post_hoc","contrast":"«После — значит вследствие» — когда причину выводят только из порядка событий. Здесь есть контрольная часть поля, которая исключает другие объяснения."},{"id":"q198","batch":4,"difficulty":2,"text":"Инженер рассуждает: «Этот мост той же конструкции, из тех же материалов и с тем же пролётом, что и соседний, который тридцать лет выдерживает грузовики. Значит, и этот должен выдержать такую нагрузку — но перед открытием мы всё равно проведём испытания».","answer_id":"none","distractors":["false_analogy","hasty_generalization","appeal_to_tradition","false_authority"],"offer_none":true,"highlight":"Значит, и этот должен выдержать такую нагрузку","explanation":"Аналогия опирается на существенные признаки — конструкцию, материалы, пролёт, — а вывод инженер собирается проверить испытаниями. Это корректное рассуждение по аналогии.","nearest_distractor":"false_analogy","contrast":"Ложная аналогия — когда сходство поверхностное. Здесь мосты похожи именно в том, что определяет их прочность."},{"id":"q199","batch":4,"difficulty":3,"text":"Новый управляющий решил снести в цеху странную перегородку посреди прохода. Старый мастер остановил его: «Сначала выясни, зачем её поставили, а потом убирай». Оказалось, перегородка защищает соседний участок от искр сварки.","answer_id":"none","distractors":["appeal_to_tradition","appeal_to_ignorance","false_authority","sunk_cost"],"offer_none":true,"highlight":"Сначала выясни, зачем её поставили, а потом убирай","explanation":"Мастер не утверждает, что перегородка нужна, раз она давно стоит. Он предлагает сначала узнать её назначение — это разумная проверка перед изменением.","nearest_distractor":"appeal_to_tradition","contrast":"Апелляция к традиции — «так было всегда, значит, правильно». Мастер говорит другое: «узнай причину, потом решай» — и не мешает перегородку убрать, если причины нет."},{"id":"q200","batch":4,"difficulty":1,"text":"Ремонт машины обойдётся в сорок тысяч, а новая такая же стоит шестьсот. В остальном машина в отличном состоянии. «Отремонтирую — так выгоднее», — решает Илья.","answer_id":"none","distractors":["sunk_cost","appeal_to_novelty","false_dilemma","appeal_to_tradition"],"offer_none":true,"highlight":"Отремонтирую — так выгоднее","explanation":"Илья сравнивает будущие расходы: сорок тысяч на ремонт против шестисот на новую машину. Он не ссылается на то, сколько уже вложено в старую, — решение верное.","nearest_distractor":"sunk_cost","contrast":"Невозвратные затраты — когда держатся за дело из-за уже потраченного. Илья смотрит только вперёд и выбирает дешёвый вариант."},{"id":"q201","batch":5,"difficulty":1,"text":"Риелтор показывает квартиру только днём и водит покупателей к окнам с видом на парк. Окна спальни выходят на круглосуточную автомойку, но на просмотре шторы там задёрнуты. «Тихая, зелёная квартира», — подытоживает риелтор.","answer_id":"cherry_picking","distractors":["hasty_generalization","misleading_statistics","bandwagon","post_hoc"],"offer_none":false,"highlight":"Тихая, зелёная квартира","explanation":"Риелтор показывает только удачные стороны квартиры и прячет неудобную — шумную автомойку под окнами спальни. Каждый показанный факт верен, но картина ложная.","nearest_distractor":"hasty_generalization","contrast":"Покупатель мог бы ошибиться, судя по одному окну. Но здесь данные отбирает сам риелтор — намеренно, чтобы создать нужное впечатление."},{"id":"q202","batch":5,"difficulty":2,"text":"На флаконе шампуня крупно написано: «93% женщин отметили, что волосы стали более блестящими!» В отчёте об испытаниях было пять показателей, но на упаковку вынесли только этот: по объёму и ломкости волос шампунь оказался хуже обычного.","answer_id":"cherry_picking","distractors":["misleading_statistics","hasty_generalization","bandwagon","false_authority"],"offer_none":false,"highlight":"93% женщин отметили, что волосы стали более блестящими!","explanation":"Из пяти показателей выбран единственный удачный, а остальные, где шампунь проиграл, не упомянуты. Цифра верная, но впечатление о шампуне ложное.","nearest_distractor":"misleading_statistics","contrast":"Цифра 93% подана честно — без хитростей с базой или графиком. Обман в том, что из пяти результатов показан только удачный."},{"id":"q203","batch":5,"difficulty":3,"text":"Сторонник гомеопатии публикует подборку: «Вот двадцать научных статей, где пациентам стало лучше, — гомеопатия работает!» Обзоры, объединившие сотни исследований и не нашедшие эффекта сверх плацебо, в подборку не попали.","answer_id":"cherry_picking","distractors":["hasty_generalization","false_authority","bandwagon","misleading_statistics"],"offer_none":true,"highlight":"Вот двадцать научных статей, где пациентам стало лучше, — гомеопатия работает!","explanation":"Из сотен исследований выбраны двадцать удачных, а обзоры, которые учитывают все данные, проигнорированы. Двадцать статей — не мало, но они не представляют всей картины.","nearest_distractor":"hasty_generalization","contrast":"Двадцать статей — не маленькая выборка, проблема не в размере. Их отобрали из сотен так, чтобы подтвердить вывод: это выборочные факты."},{"id":"q204","batch":5,"difficulty":1,"text":"Дедушка-грибник учит внука: «Я сорок лет собираю грибы, пробую незнакомые на вкус и ни разу не отравился. Значит, это безопасно». Тех, кому так не повезло, на грибной поляне с дедушкой уже не встретишь.","answer_id":"survivorship","distractors":["hasty_generalization","false_authority","post_hoc","bandwagon"],"offer_none":false,"highlight":"ни разу не отравился. Значит, это безопасно","explanation":"Об опасности судят по тем, кто уцелел. Грибники, которые отравились, советов уже не дают — их опыт в «выборку» дедушки не попадает.","nearest_distractor":"hasty_generalization","contrast":"Поспешное обобщение — общая категория. Здесь её частный случай: выводы делаются только по уцелевшим, а пострадавших не видно."},{"id":"q205","batch":5,"difficulty":1,"text":"Музыкант на мастер-классе говорит: «Все великие рок-группы начинали в гараже, без всякого музыкального образования. Так что забудьте про музыкальную школу — главное репетировать в гараже!»","answer_id":"survivorship","distractors":["hasty_generalization","false_authority","bandwagon","appeal_to_tradition"],"offer_none":false,"highlight":"Все великие рок-группы начинали в гараже, без всякого музыкального образования","explanation":"Мы знаем только о гаражных группах, которые прославились. Тысячи групп, которые репетировали в гаражах и так никуда и не вышли, в эту статистику не попадают.","nearest_distractor":"hasty_generalization","contrast":"Поспешное обобщение — общая категория. Здесь её частный случай: о «рецепте успеха» судят только по тем, кто добился успеха."},{"id":"q206","batch":5,"difficulty":2,"text":"Аналитик сравнил доходность паевых фондов за десять лет по готовой базе данных и сделал вывод: «Средний фонд обгоняет рынок». В базе остались только фонды, дожившие до сегодняшнего дня: закрывшиеся из-за убытков из неё просто удалили.","answer_id":"survivorship","distractors":["hasty_generalization","cherry_picking","misleading_statistics","cum_hoc"],"offer_none":true,"highlight":"Средний фонд обгоняет рынок","explanation":"Неудачные фонды закрылись и выпали из базы, остались только успешные. Среднее по «выжившим» завышено.","nearest_distractor":"hasty_generalization","contrast":"Поспешное обобщение — общая категория. Здесь её частный случай: выборка состоит только из уцелевших фондов.","pick_notes":{"cherry_picking":"Аналитик никого не обманывает намеренно — он даже не знает о закрывшихся фондах. Выборку испортил сам способ сбора данных: это ошибка выжившего."}},{"id":"q207","batch":5,"difficulty":1,"text":"Реклама зубной пасты: «Рекомендуют 8 из 10 стоматологов!» Мелким шрифтом: стоматологам дали список паст, разрешив отметить сколько угодно, и эту отметили наряду с другими.","answer_id":"misleading_statistics","distractors":["false_authority","bandwagon","cherry_picking","hasty_generalization"],"offer_none":false,"highlight":"Рекомендуют 8 из 10 стоматологов!","explanation":"«Рекомендуют» звучит как «выбирают именно её», а на деле стоматологи отметили её среди нескольких. Цифра верная, но подана так, что создаёт ложное впечатление.","nearest_distractor":"false_authority","contrast":"Стоматологи — профильные эксперты, тут всё в порядке. Обман в подаче цифры: «отметили среди прочих» превратилось в «рекомендуют»."},{"id":"q208","batch":5,"difficulty":2,"text":"В вечерних новостях показали график: столбик за этот год вдвое выше столбика за прошлый. Ведущий объявил: «Преступность резко выросла!» Ось графика начиналась не с нуля, а с 950: преступлений было 980, стало 1010.","answer_id":"misleading_statistics","distractors":["appeal_to_fear","cherry_picking","hasty_generalization","post_hoc"],"offer_none":false,"highlight":"Преступность резко выросла!","explanation":"Рост с 980 до 1010 — около трёх процентов. Обрезанная ось превращает его в «удвоение» на картинке.","nearest_distractor":"appeal_to_fear","contrast":"Новость, конечно, тревожит, но приём не в запугивании, а в подаче цифр: ось начинается не с нуля и раздувает маленький рост."},{"id":"q209","batch":5,"difficulty":3,"text":"Чиновник отчитывается: «Число зарегистрированных случаев болезни Лайма в области за десять лет выросло в пять раз — это эпидемия!» Врачи поясняют, что десять лет назад анализ на эту болезнь почти нигде не делали, а теперь его делают в каждой поликлинике.","answer_id":"misleading_statistics","distractors":["appeal_to_fear","post_hoc","hasty_generalization","cherry_picking"],"offer_none":true,"highlight":"Число зарегистрированных случаев болезни Лайма в области за десять лет выросло в пять раз — это эпидемия!","explanation":"Выросло число найденных случаев, а не обязательно число заболевших: раньше болезнь просто не выявляли. Сравнение цифр, собранных по-разному, создаёт ложное впечатление эпидемии.","nearest_distractor":"appeal_to_fear","contrast":"Слово «эпидемия» пугает, но ошибка не в запугивании, а в сравнении несопоставимых цифр."},{"id":"q210","batch":5,"difficulty":1,"text":"Монетку подбросили пять раз, и пять раз выпал орёл. Вовка уверенно ставит на решку: «Теперь точно решка — монетка же должна выровняться!»","answer_id":"gamblers_fallacy","distractors":["sunk_cost","hasty_generalization","post_hoc","misleading_statistics"],"offer_none":false,"highlight":"Теперь точно решка — монетка же должна выровняться!","explanation":"У монетки нет памяти: шанс решки при шестом броске — по-прежнему половина. Выравнивание «в среднем» происходит на тысячах бросков, а не за счёт следующего.","nearest_distractor":"sunk_cost","contrast":"Вовка не держится за ставку из-за уже проигранного — он считает, что прошлые броски меняют шансы следующего."},{"id":"q211","batch":5,"difficulty":2,"text":"В настольной игре Маше нужна шестёрка, а она не выпадает уже двенадцать бросков подряд. «Ну всё, следующий бросок точно шестёрка — по теории вероятности она давно должна была выпасть», — объявляет Маша и ставит на этот ход все фишки.","answer_id":"gamblers_fallacy","distractors":["hasty_generalization","sunk_cost","post_hoc","appeal_to_ignorance"],"offer_none":false,"highlight":"следующий бросок точно шестёрка — по теории вероятности она давно должна была выпасть","explanation":"Кубик не знает, что выпадало раньше: шанс шестёрки при каждом броске — одна шестая. Длинная серия неудач её не увеличивает.","nearest_distractor":"hasty_generalization","contrast":"Маша не делает общего вывода по малой выборке — она считает, что прошлые независимые броски влияют на следующий."},{"id":"q212","batch":5,"difficulty":3,"text":"Игрок в казино видит, что соседний автомат только что выдал крупный выигрыш. «На этом автомате теперь долго ничего не выпадет — он своё отдал», — говорит он и садится за другой. Автоматы работают на генераторе случайных чисел, и каждое вращение не зависит от предыдущих.","answer_id":"gamblers_fallacy","distractors":["hasty_generalization","post_hoc","sunk_cost","misleading_statistics"],"offer_none":true,"highlight":"На этом автомате теперь долго ничего не выпадет — он своё отдал","explanation":"Это та же ошибка игрока, только наоборот: игрок думает, что недавний выигрыш уменьшает шансы следующего. Но вращения независимы — автомат «не помнит», что уже выдал.","nearest_distractor":"none","contrast":"Ошибки не было бы, если бы автомат и правда был устроен с запасом выигрышей, который тратится. Но здесь каждое вращение независимо."},{"id":"q213","batch":5,"difficulty":1,"text":"Тренер говорит новичку: «Либо ты тренируешься со мной шесть дней в неделю, либо вообще забудь о спорте». Новичок хотел просто ходить на тренировки пару раз в неделю для здоровья.","answer_id":"false_dilemma","distractors":["nirvana","appeal_to_fear","middle_ground","slippery_slope"],"offer_none":false,"highlight":"Либо ты тренируешься со мной шесть дней в неделю, либо вообще забудь о спорте","explanation":"Между «шесть дней в неделю» и «никакого спорта» есть множество вариантов, включая тот, что нужен новичку.","nearest_distractor":"nirvana","contrast":"Ошибка нирваны отвергает решение из-за того, что оно не идеально. Тренер же оставляет только два варианта, хотя вариантов много."},{"id":"q214","batch":5,"difficulty":2,"text":"На собрании жильцов чиновник поставил вопрос ребром: «Или вы соглашаетесь на платную парковку во дворах, или ямы на дороге так и останутся». О том, что ремонт дороги уже заложен в областной бюджет, он не сказал.","answer_id":"false_dilemma","distractors":["appeal_to_fear","nirvana","middle_ground","sunk_cost"],"offer_none":false,"highlight":"Или вы соглашаетесь на платную парковку во дворах, или ямы на дороге так и останутся","explanation":"Есть и другие варианты: ремонт за счёт уже выделенных денег, отдельный сбор, перенос сроков. Чиновник объявляет их несуществующими.","nearest_distractor":"appeal_to_fear","contrast":"Ямы — неприятная перспектива, но главный приём не в угрозе, а в искусственном выборе из двух вариантов."},{"id":"q215","batch":5,"difficulty":3,"text":"Политик в дебатах: «Кто не поддерживает этот законопроект, тот против безопасности наших детей». Законопроект предлагал поставить камеры в каждом классе; критики предлагали вместо этого нанять больше охранников и психологов.","answer_id":"false_dilemma","distractors":["straw_man","appeal_to_fear","ad_hominem","middle_ground"],"offer_none":true,"highlight":"Кто не поддерживает этот законопроект, тот против безопасности наших детей","explanation":"Критики тоже за безопасность детей — они лишь предлагают другие средства. Политик оставляет только два варианта: «за законопроект» или «против безопасности».","nearest_distractor":"straw_man","contrast":"Элемент искажения позиции критиков есть, но ядро приёма — «или камеры, или вы против безопасности», то есть искусственное сужение выбора.","also_accepted":[{"id":"straw_man","note":"Политик и правда искажает позицию критиков. Но ядро приёма — выбор «или законопроект, или против безопасности», поэтому точнее «ложная дилемма»."}]},{"id":"q216","batch":5,"difficulty":1,"text":"Муж уверен, что до дачи сто километров, жена — что сорок. Сын, не глядя в карту, предлагает: «Давайте считать семьдесят — истина посередине». Навигатор показал сорок два.","answer_id":"middle_ground","distractors":["false_dilemma","bandwagon","nirvana","appeal_to_pity"],"offer_none":false,"highlight":"Давайте считать семьдесят — истина посередине","explanation":"Расстояние — факт, его измеряют, а не усредняют. Середина между верным и неверным ответом не становится верной.","nearest_distractor":"false_dilemma","contrast":"Ложная дилемма сужает выбор до двух вариантов. Сын делает обратное — придумывает третий, «средний», и считает его верным только потому, что он посередине."},{"id":"q217","batch":5,"difficulty":2,"text":"Двое сотрудников спорят, кто виноват в срыве сроков: один говорит, что дизайнер задержал макеты на две недели, другой — что макеты сдали вовремя. Руководитель, не открывая переписку, решает: «Видимо, задержали на неделю — разделим вину пополам».","answer_id":"middle_ground","distractors":["false_dilemma","nirvana","appeal_to_ignorance","false_authority"],"offer_none":false,"highlight":"Видимо, задержали на неделю — разделим вину пополам","explanation":"Когда сдали макеты, видно по переписке. Руководитель вместо проверки берёт середину между двумя версиями, хотя верной может быть только одна из них.","nearest_distractor":"false_dilemma","contrast":"Руководитель не сводит выбор к двум вариантам — он придумывает средний и объявляет его истиной, не проверив факты."},{"id":"q218","batch":5,"difficulty":2,"text":"На экзамене по истории Петя не помнит, в каком году была Куликовская битва: то ли в 1380-м, то ли в 1382-м. «Напишу 1381-й, — решает он. — Истина обычно посередине».","answer_id":"middle_ground","distractors":["false_dilemma","appeal_to_ignorance","nirvana","bandwagon"],"offer_none":true,"highlight":"Напишу 1381-й, — решает он. — Истина обычно посередине","explanation":"Битва была в 1380 году. Средний год между двумя вариантами гарантированно неверен, если верен один из вариантов.","nearest_distractor":"none","contrast":"Когда нужно угадать число вроде цены или расстояния, середина иногда уменьшает ошибку. Но дата — не оценка: верна ровно одна, и «среднего» года не бывает.","not_paraphrase_of":["q075"]},{"id":"q219","batch":5,"difficulty":1,"text":"Мама хочет пристегнуть маленького сына в автокресле. Папа возражает: «Кресло всё равно не спасает в любой аварии — какой в нём смысл?»","answer_id":"nirvana","distractors":["false_dilemma","appeal_to_ignorance","middle_ground","hasty_generalization"],"offer_none":false,"highlight":"Кресло всё равно не спасает в любой аварии — какой в нём смысл?","explanation":"Автокресло не даёт стопроцентной защиты, но в разы снижает риск тяжёлых травм. Отвергать его из-за того, что оно не идеально, — ошибка нирваны.","nearest_distractor":"false_dilemma","contrast":"Папа не предлагает выбор из двух вариантов; он отвергает решение, сравнивая его с недостижимым идеалом — защитой в любой аварии."},{"id":"q220","batch":5,"difficulty":3,"text":"Обсуждая фильтры нежелательных сайтов на школьных компьютерах, учитель информатики сказал: «Дети всё равно найдут способ их обойти. Значит, фильтры бесполезны». Директор напомнил, что большинство младшеклассников обходить фильтры не умеет.","answer_id":"nirvana","distractors":["false_dilemma","slippery_slope","appeal_to_ignorance","hasty_generalization"],"offer_none":false,"highlight":"Дети всё равно найдут способ их обойти. Значит, фильтры бесполезны","explanation":"Фильтр, который обходят немногие, всё равно защищает большинство. «Не идеально» не значит «бесполезно».","nearest_distractor":"hasty_generalization","contrast":"Есть и обобщение («дети найдут способ»), но суть довода в другом: решение отвергается за то, что не даёт полной защиты."},{"id":"q221","batch":5,"difficulty":3,"text":"Экологи предложили запретить одноразовые пакеты в магазинах. Противник запрета возражает: «Пакеты — лишь малая доля пластикового мусора. Океан мы этим не спасём — так зачем начинать?»","answer_id":"nirvana","distractors":["false_dilemma","misleading_statistics","red_herring","appeal_to_consequences"],"offer_none":true,"highlight":"Океан мы этим не спасём — так зачем начинать?","explanation":"Запрет пакетов не решит проблему целиком, но уменьшит её. Отвергать частичное улучшение за то, что оно не полное, — ошибка нирваны.","nearest_distractor":"none","contrast":"Возражение было бы разумным, если бы противник показал, что запрет стоит дороже пользы от него. Но он отвергает меру только за то, что она не спасает весь океан."},{"id":"q222","batch":5,"difficulty":1,"text":"Сын просит завести хомяка. Папа против: «Сегодня хомяк, завтра попросишь собаку, потом лошадь — и через пять лет у нас дома будет зоопарк».","answer_id":"slippery_slope","distractors":["appeal_to_fear","false_dilemma","hasty_generalization","appeal_to_consequences"],"offer_none":false,"highlight":"Сегодня хомяк, завтра попросишь собаку, потом лошадь","explanation":"Каждый следующий шаг объявлен неизбежным, хотя ничто к нему не ведёт: решение о собаке и тем более о лошади папа будет принимать отдельно.","nearest_distractor":"appeal_to_fear","contrast":"Папа не запугивает сына — он рисует цепочку необоснованных шагов от хомяка до зоопарка. Это скользкая дорожка."},{"id":"q223","batch":5,"difficulty":2,"text":"Педсовет обсуждает, разрешить ли школьникам телефоны на переменах. Завуч против: «Разрешим на переменах — дети начнут доставать их на уроках, потом перестанут слушать учителей, а к выпускному не смогут прочитать и страницы текста».","answer_id":"slippery_slope","distractors":["appeal_to_fear","post_hoc","false_dilemma","appeal_to_consequences"],"offer_none":false,"highlight":"потом перестанут слушать учителей, а к выпускному не смогут прочитать и страницы текста","explanation":"Телефоны на переменах не ведут автоматически к телефонам на уроках — это отдельное правило, которое школа может сохранить. Дальнейшие звенья ещё менее обоснованы.","nearest_distractor":"post_hoc","contrast":"«После — значит вследствие» объясняет уже случившееся. Завуч прогнозирует цепочку будущих событий, которых ещё не было, — это скользкая дорожка."},{"id":"q224","batch":5,"difficulty":3,"text":"Жилец просит в суде разрешить ему держать в квартире одну кошку, хотя правила дома запрещают животных. Представитель управляющей компании возражает: «Разрешим одну кошку — кто-нибудь заведёт двух, потом собаку, потом кур, и дом превратится в ферму».","answer_id":"slippery_slope","distractors":["appeal_to_fear","false_dilemma","hasty_generalization","appeal_to_tradition"],"offer_none":true,"highlight":"потом собаку, потом кур, и дом превратится в ферму","explanation":"Первое звено — прецедент — можно обсуждать. Но дальше идут переходы, ничем не подкреплённые: каждое новое животное потребовало бы отдельного решения суда.","nearest_distractor":"none","contrast":"Опасение прецедента само по себе разумно, и если бы представитель на нём остановился, ошибки могло бы не быть. Ошибка — в цепочке до «фермы»."},{"id":"q225","batch":5,"difficulty":1,"text":"Миша полгода учит китайский, понял, что язык ему не нужен и не нравится, а для работы нужен испанский. Но продолжает: «Я уже столько сил вложил в иероглифы — бросать жалко».","answer_id":"sunk_cost","distractors":["gamblers_fallacy","appeal_to_tradition","false_dilemma","nirvana"],"offer_none":false,"highlight":"Я уже столько сил вложил в иероглифы — бросать жалко","explanation":"Полгода уже потрачены, их не вернуть ни при каком решении. Выбирать нужно по будущей пользе — а она на стороне испанского.","nearest_distractor":"gamblers_fallacy","contrast":"Миша не ждёт, что китайский вдруг станет нужнее, — он держится за уже вложенные силы."},{"id":"q226","batch":5,"difficulty":2,"text":"Компания три года разрабатывает собственную бухгалтерскую программу, хотя готовая на рынке дешевле и лучше. Директор настаивает: «Мы вложили в разработку двадцать миллионов. Если сейчас купим готовую, получится, что всё было зря».","answer_id":"sunk_cost","distractors":["false_dilemma","appeal_to_consequences","appeal_to_novelty","slippery_slope"],"offer_none":false,"highlight":"Мы вложили в разработку двадцать миллионов. Если сейчас купим готовую, получится, что всё было зря","explanation":"Двадцать миллионов уже потрачены в любом случае. Вопрос в том, что выгоднее дальше: дописывать своё или купить готовое, — а готовое дешевле и лучше.","nearest_distractor":"appeal_to_consequences","contrast":"Директор не спорит с тем, что готовая программа лучше, — он предлагает продолжать из-за уже потраченного. Это невозвратные затраты."},{"id":"q227","batch":5,"difficulty":3,"text":"Сериал третий сезон подряд становится всё хуже, но Аня продолжает смотреть: «Я уже посмотрела шестьдесят серий, надо узнать, чем всё кончится». Пересказ концовки она прочитала ещё на прошлой неделе.","answer_id":"sunk_cost","distractors":["gamblers_fallacy","appeal_to_tradition","nirvana","appeal_to_consequences"],"offer_none":true,"highlight":"Я уже посмотрела шестьдесят серий, надо узнать, чем всё кончится","explanation":"Концовку Аня уже знает, так что «узнать, чем кончится» — не настоящая причина. Держат её шестьдесят уже просмотренных серий, а не ожидаемое удовольствие.","nearest_distractor":"none","contrast":"Досматривать сериал ради концовки — нормальное желание. Но Аня концовку уже знает, и остаётся только довод «столько уже посмотрела»."},{"id":"q228","batch":5,"difficulty":1,"text":"— Почему ты веришь этой гадалке? — Потому что она никогда не ошибается. — А откуда ты знаешь, что не ошибается? — Она сама мне так сказала.","answer_id":"circular","distractors":["false_authority","appeal_to_ignorance","bandwagon","genetic_fallacy"],"offer_none":false,"highlight":"Она сама мне так сказала","explanation":"Надёжность гадалки доказывается её же словами — то есть тем, в чём и нужно убедиться. Круг замкнулся.","nearest_distractor":"false_authority","contrast":"Ссылка на авторитет опирается на внешний источник. Здесь источник подтверждает сам себя."},{"id":"q229","batch":5,"difficulty":2,"text":"— Почему Сидоров — лучший сотрудник месяца? — спрашивают директора. — Он получил больше всех премий. — А почему он получил больше всех премий? — Потому что он лучший сотрудник.","answer_id":"circular","distractors":["false_authority","appeal_to_tradition","non_sequitur","equivocation"],"offer_none":false,"highlight":"Потому что он лучший сотрудник","explanation":"Звание объясняется премиями, а премии — званием. Ни одного внешнего довода — выполненных задач, отзывов клиентов — не прозвучало.","nearest_distractor":"false_authority","contrast":"Директор не ссылается на чьё-то мнение — он доказывает тезис через самого себя.","pick_notes":{"non_sequitur":"Круг как раз «следует»: вывод тривиально вытекает из посылки, потому что он в ней уже содержится. Беда не в переходе, а в том, что такая посылка ничего не доказывает."}},{"id":"q230","batch":5,"difficulty":3,"text":"Аналитик уверен: «Рынок всегда прав». — «Почему?» — «Потому что цена на рынке отражает всю доступную информацию». — «А откуда известно, что отражает?» — «Иначе рынок ошибался бы, а рынок всегда прав».","answer_id":"circular","distractors":["false_authority","false_premise","appeal_to_ignorance","non_sequitur"],"offer_none":true,"highlight":"Иначе рынок ошибался бы, а рынок всегда прав","explanation":"Тезис «рынок прав» доказывается через «цены отражают информацию», а это — через тот же «рынок прав». Утверждение держится только на самом себе.","nearest_distractor":"false_premise","contrast":"Посылка спорная, но главное другое: она доказывается через сам вывод — «рынок прав, потому что отражает, а отражает, потому что прав».","pick_notes":{"non_sequitur":"Круг как раз «следует»: вывод тривиально вытекает из посылки, потому что он в ней уже содержится. Беда не в переходе, а в том, что такая посылка ничего не доказывает."},"not_paraphrase_of":["q028","q228"]},{"id":"q231","batch":5,"difficulty":1,"text":"Сосед отказывается менять сорокалетнюю проводку, которая уже дважды искрила: «Я же не электрик — значит, и пожара у меня не будет». Жена молча купила огнетушитель.","answer_id":"non_sequitur","distractors":["false_premise","appeal_to_ignorance","denying_antecedent","circular"],"offer_none":false,"highlight":"Я же не электрик — значит, и пожара у меня не будет","explanation":"Профессия соседа никак не связана с тем, загорится ли старая проводка. Вывод не следует из посылки.","nearest_distractor":"false_premise","contrast":"Посылка «я не электрик» верна — дело не в ней. Просто из неё вообще ничего не следует о пожаре.","pick_notes":{"denying_antecedent":"Отрицание основания — «если A, то B; не A — значит, не B». Но здесь и связи «если электрик, то пожар» никто не утверждал: вывод просто не связан с посылкой."}},{"id":"q232","batch":5,"difficulty":2,"text":"Директор школы объявил на педсовете: «Наши выпускники в этом году набрали рекордные баллы по математике. Следовательно, учителя литературы тоже работают отлично — премию получат все».","answer_id":"non_sequitur","distractors":["composition","division","false_authority","hasty_generalization"],"offer_none":false,"highlight":"Следовательно, учителя литературы тоже работают отлично","explanation":"Результаты по математике ничего не говорят о работе учителей литературы. Вывод не следует из посылки.","nearest_distractor":"division","contrast":"Ошибка деления переносила бы свойство целого на часть: «школа отличная — значит, и каждый учитель». Здесь же успех одних переносится на других, не связанных с ним, — просто мнимое следование."},{"id":"q233","batch":5,"difficulty":3,"text":"Кандидат в мэры на встрече с избирателями: «Я вырос в этом районе, ходил в эту школу, играл в этом дворе. Поэтому я лучше всех знаю, как решить проблему с транспортом во всём городе».","answer_id":"non_sequitur","distractors":["false_authority","genetic_fallacy","circular","equivocation"],"offer_none":false,"highlight":"Поэтому я лучше всех знаю, как решить проблему с транспортом во всём городе","explanation":"Детство в районе даёт знание района, но не умение решать транспортные проблемы целого города. Из посылки этот вывод не следует.","nearest_distractor":"false_authority","contrast":"Кандидат не ссылается на чужое экспертное мнение — он выводит свою компетентность из детских воспоминаний, а одно из другого не следует."},{"id":"q234","batch":5,"difficulty":1,"text":"Мама не разрешает дочке купаться после обеда: «Если поплаваешь в течение часа после еды, сведёт судорогой и утонешь». Девочка грустно ждёт на берегу целый час.","answer_id":"false_premise","distractors":["appeal_to_fear","slippery_slope","appeal_to_tradition","false_authority"],"offer_none":false,"highlight":"Если поплаваешь в течение часа после еды, сведёт судорогой и утонешь","explanation":"Это популярный миф: исследования не находят связи между едой перед купанием и утоплениями. Запрет построен на ложной посылке.","nearest_distractor":"appeal_to_fear","contrast":"Мама не запугивает дочь ради выгоды — она сама верит в миф. Если бы угроза была правдой, предупреждение было бы разумным; беда в ложности посылки."},{"id":"q235","batch":5,"difficulty":2,"text":"Отец объясняет сыну, почему тот проиграл школьный шахматный турнир: «Шахматный талант передаётся только по мужской линии, а наш дедушка был музыкантом». Мама мальчика, между прочим, — гроссмейстер.","answer_id":"false_premise","distractors":["genetic_fallacy","hasty_generalization","non_sequitur","appeal_to_tradition"],"offer_none":false,"highlight":"Шахматный талант передаётся только по мужской линии","explanation":"Объяснение держится на выдуманной посылке. Никакого «шахматного таланта по мужской линии» нет — и мама-гроссмейстер это наглядно опровергает.","nearest_distractor":"non_sequitur","contrast":"Если бы посылка была верна, вывод почти следовал бы. Ошибка не в переходе, а в фундаменте.","pick_notes":{"genetic_fallacy":"Название обманчиво: генетическая ошибка — это оценка идеи по её происхождению, а не рассуждения о наследственности. Здесь вывод держится на ложной посылке о передаче таланта."}},{"id":"q236","batch":5,"difficulty":3,"text":"Депутат выступает за ужесточение наказаний: «Как все мы знаем, преступность за последние десять лет резко выросла, поэтому нужны более суровые сроки». По официальной статистике, за десять лет преступность снизилась на треть.","answer_id":"false_premise","distractors":["bandwagon","appeal_to_fear","cherry_picking","misleading_statistics"],"offer_none":true,"highlight":"Как все мы знаем, преступность за последние десять лет резко выросла","explanation":"Предложение логично вытекает из посылки, но посылка противоречит статистике. Вывод, построенный на неверном основании, ничего не доказывает.","nearest_distractor":"bandwagon","contrast":"«Как все мы знаем» звучит как ссылка на мнение большинства, но депутат не доказывает свою мысль её популярностью — он выдаёт неверное утверждение за общеизвестный факт."},{"id":"q237","batch":5,"difficulty":2,"text":"— Если сел аккумулятор, машина не заводится, — рассуждает Олег. — Моя не заводится. Значит, аккумулятор сел — поеду за новым. В автосервисе выяснилось, что в баке просто кончился бензин.","answer_id":"affirming_consequent","distractors":["denying_antecedent","non_sequitur","post_hoc","hasty_generalization"],"offer_none":false,"highlight":"Моя не заводится. Значит, аккумулятор сел","explanation":"Машина не заводится по многим причинам: нет бензина, неисправен стартер, свечи. Из «если сел аккумулятор — не заводится» нельзя вывести «не заводится — значит, аккумулятор».","nearest_distractor":"denying_antecedent","contrast":"Отрицание основания звучало бы так: «Аккумулятор в порядке — значит, заведётся». Олег же идёт от следствия к причине."},{"id":"q238","batch":5,"difficulty":2,"text":"Фитнес-тренер говорит клиентке: «Когда тренируешься правильно, на следующий день болят мышцы. У вас болят — значит, вы тренируетесь правильно». У клиентки болит потянутая на тренировке спина.","answer_id":"affirming_consequent","distractors":["denying_antecedent","non_sequitur","false_authority","cum_hoc"],"offer_none":false,"highlight":"У вас болят — значит, вы тренируетесь правильно","explanation":"Мышцы болят не только после правильной тренировки, но и после травмы. Из «правильно — значит, болит» нельзя вывести «болит — значит, правильно».","nearest_distractor":"denying_antecedent","contrast":"Отрицание основания звучало бы так: «Вы тренировались неправильно — значит, болеть не будет». Тренер идёт от следствия к причине."},{"id":"q239","batch":5,"difficulty":3,"text":"Исследователь пишет в статье: «Если наше лекарство действует, у пациентов должна снизиться температура. Температура снизилась — гипотеза подтверждена, лекарство работает». Контрольной группы, получавшей пустышку, в исследовании не было.","answer_id":"affirming_consequent","distractors":["post_hoc","denying_antecedent","non_sequitur","cum_hoc"],"offer_none":true,"highlight":"Температура снизилась — гипотеза подтверждена, лекарство работает","explanation":"Температура могла снизиться и сама — при большинстве инфекций она со временем спадает. Из «если действует — снизится» и «снизилась» нельзя вывести «действует»: для этого и нужна контрольная группа.","nearest_distractor":"post_hoc","contrast":"Ход рассуждения похож на «после — значит вследствие», но исследователь явно рассуждает по схеме «если A, то B; B — значит, A». Это утверждение следствия.","also_accepted":[{"id":"post_hoc","note":"Верно: «температура снизилась после лекарства — значит, из-за него» — это тоже ошибка. Но исследователь проговаривает именно схему «если A, то B; B есть — значит, A», поэтому точнее утверждение следствия."}]},{"id":"q240","batch":5,"difficulty":1,"text":"Бабушка говорит: «Кто ест кашу, тот вырастет сильным». Внук наотрез отказывается от каши, и бабушка вздыхает: «Ну всё, не вырастет у нас богатырь».","answer_id":"denying_antecedent","distractors":["affirming_consequent","non_sequitur","false_premise","slippery_slope"],"offer_none":false,"highlight":"Ну всё, не вырастет у нас богатырь","explanation":"Даже если каша помогает расти сильным, это не единственный путь: есть спорт, другая еда, наследственность. Из «если каша — сильный» не следует «без каши — не сильный».","nearest_distractor":"affirming_consequent","contrast":"Утверждение следствия было бы «вырос сильным — значит, ел кашу». Бабушка же отрицает условие и решает, что не будет и следствия.","pick_notes":{"false_premise":"Посылку «кто ест кашу, тот вырастет сильным» можно оспорить, но даже если она верна, из неё не следует, что без каши сильным не вырасти. Главная ошибка — в этом переходе."}},{"id":"q241","batch":5,"difficulty":1,"text":"Интернет-магазин обещает: «Оплатите до полудня — получите заказ сегодня». Света оплатила в час дня и написала в чат: «Раз опоздала, сегодня точно не привезут — отменяю заказ». Курьер в это время уже подъезжал к её дому.","answer_id":"denying_antecedent","distractors":["affirming_consequent","non_sequitur","nirvana","false_dilemma"],"offer_none":false,"highlight":"Раз опоздала, сегодня точно не привезут — отменяю заказ","explanation":"Магазин обещал доставку при оплате до полудня, но не говорил, что при оплате позже доставки сегодня не будет. «Если… то» не означает «только если».","nearest_distractor":"affirming_consequent","contrast":"Утверждение следствия звучало бы так: «Привезли сегодня — значит, оплатила до полудня». Света отрицает условие и решает, что не будет и следствия."},{"id":"q242","batch":5,"difficulty":2,"text":"Мэр обещал: «Если построим новый мост, пробки в центре сократятся». Мост решили не строить, и оппозиционная газета написала: «Значит, пробки в центре так и не сократятся». Через год их сократили за счёт выделенных полос для автобусов.","answer_id":"denying_antecedent","distractors":["affirming_consequent","non_sequitur","false_dilemma","slippery_slope"],"offer_none":false,"highlight":"Значит, пробки в центре так и не сократятся","explanation":"Мост — лишь один способ сократить пробки. Из «если мост — пробок меньше» не следует «без моста пробок меньше не станет».","nearest_distractor":"affirming_consequent","contrast":"Утверждение следствия звучало бы так: «Пробки сократились — значит, построили мост». Газета же отрицает условие и решает, что не будет и следствия."},{"id":"q243","batch":5,"difficulty":2,"text":"Новый пищевой краситель появился в продаже два месяца назад. Производитель пишет на сайте: «Никто не доказал, что он вреден, значит, он безопасен».","answer_id":"appeal_to_ignorance","distractors":["fallacy_fallacy","false_authority","hasty_generalization","appeal_to_novelty"],"offer_none":false,"highlight":"Никто не доказал, что он вреден, значит, он безопасен","explanation":"За два месяца вред могли просто не успеть заметить. Безопасность доказывают испытаниями, а не отсутствием опровержений.","nearest_distractor":"fallacy_fallacy","contrast":"«Ошибка ошибки» выводит ложность тезиса из слабости довода. Производитель делает другое: выводит безопасность из того, что вред не доказан."},{"id":"q244","batch":5,"difficulty":2,"text":"Подруга уверяет Ольгу, что её муж изменяет: «Ты же не можешь доказать, что он не изменяет! Значит, изменяет».","answer_id":"appeal_to_ignorance","distractors":["fallacy_fallacy","false_premise","circular","ad_hominem"],"offer_none":false,"highlight":"Ты же не можешь доказать, что он не изменяет! Значит, изменяет","explanation":"Доказать, что чего-то не было, почти невозможно. Бремя доказательства лежит на том, кто утверждает измену, а не на том, кто её отрицает.","nearest_distractor":"fallacy_fallacy","contrast":"Подруга не находит изъяна в доводах Ольги — у Ольги доводов и нет. Она выводит измену из того, что её нельзя опровергнуть.","not_paraphrase_of":["q087"]},{"id":"q245","batch":5,"difficulty":3,"text":"Скептик заявляет на лекции: «Нет никаких доказательств, что во Вселенной есть жизнь, кроме земной. Значит, её нет нигде».","answer_id":"appeal_to_ignorance","distractors":["hasty_generalization","fallacy_fallacy","false_premise","circular"],"offer_none":true,"highlight":"Нет никаких доказательств, что во Вселенной есть жизнь, кроме земной. Значит, её нет нигде","explanation":"Мы изучили ничтожную часть Вселенной. Отсутствие находок при таком поиске — не доказательство отсутствия. Честный вывод: «пока не знаем».","nearest_distractor":"none","contrast":"Отсутствие находок бывает доводом — если искали так, что нашли бы. Здесь поиск охватил крошечную долю Вселенной."},{"id":"q246","batch":5,"difficulty":2,"text":"На двери бассейна правило: «Пускают только с медицинской справкой». У Кати справки с собой нет. «Значит, сегодня меня не пустят», — понимает она и идёт домой за справкой.","answer_id":"none","distractors":["denying_antecedent","affirming_consequent","special_pleading","nirvana"],"offer_none":true,"highlight":"Значит, сегодня меня не пустят","explanation":"Правило сформулировано как «только с»: справка — необходимое условие. Нет справки — нет и входа. Вывод корректен.","nearest_distractor":"denying_antecedent","contrast":"Отрицание основания — ошибка для «если A, то B». Здесь же правило «только если A» — и тогда «не A — значит, не B» верно."},{"id":"q247","batch":5,"difficulty":3,"text":"Совет посёлка решает, открывать ли в декабре каток на пруду. Председатель говорит: «Если откроем, а лёд окажется тонким, кто-нибудь провалится. Давайте сначала измерим толщину льда».","answer_id":"none","distractors":["appeal_to_consequences","appeal_to_fear","slippery_slope","false_dilemma"],"offer_none":true,"highlight":"Давайте сначала измерим толщину льда","explanation":"Последствия здесь учитывают при принятии решения, а сам факт — толщину льда — собираются измерить. Это разумная предосторожность.","nearest_distractor":"appeal_to_consequences","contrast":"Апелляция к последствиям — когда по неприятным последствиям судят об истинности факта. Председатель не говорит «лёд тонкий, потому что иначе страшно» — он предлагает проверить."},{"id":"q248","batch":5,"difficulty":1,"text":"Сайт о ценах пишет: «Молоко подорожало на 10%: литр стоил 90 рублей, а теперь стоит 99». Цены сайт собирает по чекам крупных сетей за одну и ту же неделю каждого месяца.","answer_id":"none","distractors":["misleading_statistics","cherry_picking","hasty_generalization","cum_hoc"],"offer_none":true,"highlight":"Молоко подорожало на 10%: литр стоил 90 рублей, а теперь стоит 99","explanation":"Процент посчитан верно и подкреплён исходными ценами. Читатель сам видит базу и может проверить расчёт.","nearest_distractor":"misleading_statistics","contrast":"Манипуляция статистикой — когда цифры создают ложное впечатление. Здесь процент дан вместе с исходными числами."},{"id":"q249","batch":5,"difficulty":2,"text":"Таможенник просветил чемодан, проверил его с собакой и досмотрел вручную, но ничего запрещённого не нашёл. «Можете проходить», — сказал он.","answer_id":"none","distractors":["appeal_to_ignorance","hasty_generalization","false_authority","survivorship"],"offer_none":true,"highlight":"Можете проходить","explanation":"Отсутствие находок после тщательного поиска — законный довод: если бы что-то было, его бы, скорее всего, нашли.","nearest_distractor":"appeal_to_ignorance","contrast":"Апелляция к незнанию — «не нашли, значит, нет» без серьёзного поиска. Здесь искали тремя способами, так что отсутствие находок что-то значит."},{"id":"q250","batch":5,"difficulty":3,"text":"Словарь определяет «холостяк» как «неженатый мужчина». Сестра говорит про двоюродного брата: «Олег — холостяк, значит, он не женат».","answer_id":"none","distractors":["circular","equivocation","false_premise","no_true_scotsman"],"offer_none":true,"highlight":"Олег — холостяк, значит, он не женат","explanation":"Вывод следует из самого определения слова. Это не доказательство спорного тезиса, а пояснение того, что значит «холостяк», — так и должно быть.","nearest_distractor":"circular","contrast":"Порочный круг — ошибка, когда спорный тезис доказывают через него самого. Здесь ничего спорного не доказывают: просто раскрывают значение слова."},{"id":"q251","batch":6,"difficulty":1,"text":"Мальчик доказывает сестре, что киты — млекопитающие: «Они же огромные, а все огромные животные — млекопитающие». Сестра смеётся: «Крокодил тоже огромный, а он не млекопитающее. Значит, твой кит — рыба!»","answer_id":"fallacy_fallacy","distractors":["appeal_to_ignorance","straw_man","ad_hominem","false_analogy"],"offer_none":false,"highlight":"Значит, твой кит — рыба!","explanation":"Довод мальчика действительно плохой, но кит от этого не становится рыбой: он дышит лёгкими и выкармливает детёнышей молоком. Слабый аргумент не делает вывод ложным.","nearest_distractor":"appeal_to_ignorance","contrast":"Апелляция к незнанию — «не доказано, значит, неверно» вообще. Здесь есть конкретный неудачный довод, и из его слабости выводят ложность самого тезиса."},{"id":"q252","batch":6,"difficulty":1,"text":"Коллега убеждает Диму бросить курить: «Курение вредно — так на пачке написано, а на пачках всегда пишут правду». Дима смеётся: «Довод так себе. Раз он такой слабый, значит, курение не вредит».","answer_id":"fallacy_fallacy","distractors":["appeal_to_ignorance","straw_man","circular","hasty_generalization"],"offer_none":false,"highlight":"Раз он такой слабый, значит, курение не вредит","explanation":"Ссылка на надпись на пачке — слабый довод. Но вред курения доказан многолетними исследованиями, и от неудачного аргумента коллеги он никуда не делся.","nearest_distractor":"appeal_to_ignorance","contrast":"Дима не говорит «никто не доказал вред» — он находит изъян в конкретном доводе и делает из этого вывод о ложности самого тезиса."},{"id":"q253","batch":6,"difficulty":2,"text":"На научно-популярной лекции лектор объяснил, что небо голубое, потому что в нём отражается океан. Слушатель, знающий физику, встал: «Это неверное объяснение. Значит, небо на самом деле не голубое, а нам только кажется».","answer_id":"fallacy_fallacy","distractors":["appeal_to_ignorance","ad_hominem","hasty_generalization","circular"],"offer_none":true,"highlight":"Это неверное объяснение. Значит, небо на самом деле не голубое","explanation":"Объяснение лектора действительно неверно: небо голубое из-за рассеяния света в атмосфере. Но ложность объяснения не делает ложным сам факт, который объясняли.","nearest_distractor":"appeal_to_ignorance","contrast":"Слушатель не ссылается на отсутствие доказательств — он опровергает конкретное объяснение и ошибочно выводит отсюда, что неверен и сам факт."},{"id":"q254","batch":6,"difficulty":2,"text":"Учитель философии сказал классу: «Ничто не совершенно». Двоечник Вася тут же нашёлся: «А моя контрольная — это ничто, я её даже не писал. Значит, моя контрольная совершенна!»","answer_id":"equivocation","distractors":["false_analogy","composition","circular","red_herring"],"offer_none":false,"highlight":"А моя контрольная — это ничто, я её даже не писал","explanation":"У учителя «ничто» означает «ни одна вещь», у Васи — «пустое место». Вывод держится на том, что слово используется в двух разных смыслах.","nearest_distractor":"false_analogy","contrast":"Вася не сравнивает две вещи по сходству — он подменяет смысл одного и того же слова."},{"id":"q255","batch":6,"difficulty":3,"text":"Сторонник гомеопатии объясняет: «Вода обладает памятью. В физике даже есть понятие „память формы“ у металлов. Значит, и вода может „помнить“ лекарство, которое в ней когда-то растворяли».","answer_id":"equivocation","distractors":["false_analogy","false_authority","false_premise","appeal_to_ignorance"],"offer_none":true,"highlight":"В физике даже есть понятие „память формы“ у металлов. Значит, и вода может „помнить“ лекарство","explanation":"«Память формы» у металлов — способность восстанавливать форму при нагреве, а «память воды» — выдуманная способность хранить свойства растворённого вещества. Общее только слово «память».","nearest_distractor":"false_analogy","contrast":"Сравнение с металлами действительно есть, но оно держится только на общем слове. Ошибка в подмене смысла: «память» в физике и «память» в гомеопатии — разные вещи.","also_accepted":[{"id":"false_analogy","note":"Сравнение воды с металлами и правда поверхностное — это ложная аналогия. Но сходство держится исключительно на слове «память», поэтому точнее подмена понятий."}]},{"id":"q256","batch":6,"difficulty":3,"text":"На упаковке батончика крупно написано: «Не содержит сахара». В составе — мёд и фруктовый сироп. Представитель производителя пояснил: «Сахаром у нас в отрасли называют только сахарозу, а её в батончике нет».","answer_id":"equivocation","distractors":["misleading_statistics","cherry_picking","false_premise","red_herring"],"offer_none":true,"highlight":"Сахаром у нас в отрасли называют только сахарозу","explanation":"Покупатель понимает «сахар» по-бытовому — как сладкие вещества вообще, а производитель оправдывается узким техническим смыслом. Надпись держится на подмене смысла слова.","nearest_distractor":"cherry_picking","contrast":"Мёд и сироп честно указаны в составе — никто ничего не прячет. Обман в слове «сахар»: в рекламе его читают по-бытовому, а оправдываются техническим смыслом."},{"id":"q257","batch":6,"difficulty":1,"text":"Студент объясняет, почему не ходит на лекции по высшей математике: «Чтобы научиться плавать, не нужно слушать лекции о плавании — надо прыгать в воду. Так и с математикой: открою задачник перед экзаменом и разберусь».","answer_id":"false_analogy","distractors":["equivocation","hasty_generalization","appeal_to_novelty","false_premise"],"offer_none":false,"highlight":"Чтобы научиться плавать, не нужно слушать лекции о плавании — надо прыгать в воду. Так и с математикой","explanation":"Плавание — телесный навык, а высшая математика требует понять теорию, прежде чем решать задачи. Сходство («учиться на практике») поверхностное.","nearest_distractor":"equivocation","contrast":"Студент не играет смыслом одного слова — он переносит вывод с плавания на математику по внешнему сходству."},{"id":"q258","batch":6,"difficulty":1,"text":"Соседка просит хозяина собаки убирать за питомцем во дворе. Тот возмущается: «Птицы тоже гадят на улице, и за ними никто не убирает!»","answer_id":"false_analogy","distractors":["tu_quoque","special_pleading","bandwagon","red_herring"],"offer_none":false,"highlight":"Птицы тоже гадят на улице, и за ними никто не убирает!","explanation":"Птицы дикие, за ними никто не отвечает и убрать за ними невозможно. За собаку отвечает хозяин. В существенном ситуации различаются.","nearest_distractor":"special_pleading","contrast":"Хозяин не просит исключения для себя лично — он сравнивает свою собаку с дикими птицами, хотя сравнение не выдерживает проверки.","pick_notes":{"tu_quoque":"«Сам такой» — упрёк критикующему в том же самом. Птицы никого не критикуют: хозяин сравнивает собаку с ними, а это сравнение ложное."}},{"id":"q259","batch":6,"difficulty":3,"text":"Директор завода против обеденных перерывов: «Станки работают по двадцать часов без остановки — и ничего. Рабочий на конвейере — такая же часть производственной линии, значит, и ему перерывы ни к чему».","answer_id":"false_analogy","distractors":["composition","equivocation","false_premise","hasty_generalization"],"offer_none":true,"highlight":"Рабочий на конвейере — такая же часть производственной линии, значит, и ему перерывы ни к чему","explanation":"Рабочий и станок похожи лишь тем, что стоят на одной линии. Человек устаёт, теряет внимание и получает травмы — станок нет. Перенос «правила для станков» на людей не обоснован.","nearest_distractor":"composition","contrast":"Директор не переносит свойство частей на целое — он переносит свойство одной части (станка) на другую (человека) по поверхностному сходству."},{"id":"q260","batch":6,"difficulty":2,"text":"Студент на семинаре по физике заявил: «Ни одна отдельная молекула воды не бывает мокрой. Значит, и вода в целом не мокрая». Преподаватель предложил ему проверить это, опустив руку в стакан.","answer_id":"composition","distractors":["division","equivocation","hasty_generalization","false_premise"],"offer_none":false,"highlight":"Значит, и вода в целом не мокрая","explanation":"«Мокрость» — свойство большого количества воды, у отдельной молекулы его нет. Свойства целого не обязаны совпадать со свойствами частей.","nearest_distractor":"division","contrast":"Ошибка деления идёт от целого к части: «вода мокрая — значит, и молекула мокрая». Студент идёт от частей к целому."},{"id":"q261","batch":6,"difficulty":3,"text":"Экономист рассуждает: «Если один человек начнёт больше откладывать, он станет богаче. Значит, если все в стране начнут больше откладывать, страна станет богаче». Когда в кризис все разом перестали тратить, продажи упали, и многие лишились работы.","answer_id":"composition","distractors":["division","hasty_generalization","false_analogy","slippery_slope"],"offer_none":true,"highlight":"Значит, если все в стране начнут больше откладывать, страна станет богаче","explanation":"Для одного человека экономия выгодна, но если экономят все, падают продажи, а с ними и доходы самих экономящих. То, что верно для части, неверно для целого.","nearest_distractor":"hasty_generalization","contrast":"Экономист не делает вывода по малой выборке — он переносит свойство поведения одного человека на всю страну, где действуют другие законы."},{"id":"q262","batch":6,"difficulty":3,"text":"Блогер пишет: «Натрий — ядовитый металл, который взрывается в воде, хлор — ядовитый газ. Значит, поваренная соль, состоящая из натрия и хлора, — смертельный яд!»","answer_id":"composition","distractors":["division","false_premise","genetic_fallacy","hasty_generalization"],"offer_none":false,"highlight":"Значит, поваренная соль, состоящая из натрия и хлора, — смертельный яд!","explanation":"В соединении вещества теряют свои прежние свойства: соль — не смесь металла и газа, а новое вещество с другими свойствами.","nearest_distractor":"division","contrast":"Ошибка деления переносила бы свойства соли на натрий и хлор. Блогер идёт в обратную сторону — от частей к целому.","pick_notes":{"genetic_fallacy":"Генетическая ошибка — оценка идеи или обычая по их истории. Здесь же свойства частей переносят на целое — это ошибка композиции."}},{"id":"q263","batch":6,"difficulty":1,"text":"Мама гордится: «Наш класс занял первое место на олимпиаде по математике. Значит, мой Ваня — отличный математик». Ваня на олимпиаду не ходил: у него была ангина.","answer_id":"division","distractors":["composition","hasty_generalization","false_analogy","equivocation"],"offer_none":false,"highlight":"Наш класс занял первое место на олимпиаде по математике. Значит, мой Ваня — отличный математик","explanation":"Успех класса в целом не означает, что каждый ученик силён в математике, — тем более тот, кто в олимпиаде не участвовал.","nearest_distractor":"composition","contrast":"Ошибка композиции идёт от частей к целому. Мама идёт в обратную сторону — от класса к сыну."},{"id":"q264","batch":6,"difficulty":1,"text":"Турист заходит в ресторан: «У них мишленовская звезда, значит, любое блюдо здесь — шедевр. Закажу самое дешёвое!» Самым дешёвым оказался хлеб с маслом.","answer_id":"division","distractors":["composition","hasty_generalization","false_authority","false_analogy"],"offer_none":false,"highlight":"У них мишленовская звезда, значит, любое блюдо здесь — шедевр","explanation":"Звезду дают ресторану в целом — за кухню и опыт. Из этого не следует, что каждый пункт меню, вплоть до хлеба с маслом, — шедевр.","nearest_distractor":"composition","contrast":"Ошибка композиции шла бы от отдельных блюд к ресторану. Турист идёт от ресторана к отдельному блюду."},{"id":"q265","batch":6,"difficulty":2,"text":"Журналист пишет: «Компания „Альфа“ — крупнейший работодатель области, зарплаты там выше средних. Значит, уборщица в „Альфе“ получает больше, чем учитель в школе». Зарплаты уборщиц в компании он не уточнял.","answer_id":"division","distractors":["composition","hasty_generalization","misleading_statistics","cum_hoc"],"offer_none":false,"highlight":"Значит, уборщица в „Альфе“ получает больше, чем учитель в школе","explanation":"Высокие зарплаты компании в среднем не означают, что у каждой должности зарплата высокая. Свойство целого перенесено на часть без проверки.","nearest_distractor":"composition","contrast":"Ошибка композиции идёт от частей к целому. Журналист идёт от компании к отдельной должности."},{"id":"q266","batch":6,"difficulty":2,"text":"Социологи опросили три тысячи человек, отобранных случайно по всей стране с учётом возраста, пола и региона. По итогам они сообщили о взглядах жителей страны с погрешностью около двух процентов.","answer_id":"none","distractors":["hasty_generalization","bandwagon","misleading_statistics","cherry_picking"],"offer_none":true,"highlight":"По итогам они сообщили о взглядах жителей страны с погрешностью около двух процентов","explanation":"Выборка большая и случайная, отобрана с учётом состава населения, а погрешность честно указана. Такой опрос позволяет судить обо всей стране.","nearest_distractor":"hasty_generalization","contrast":"Поспешное обобщение — вывод по малой или нерепрезентативной выборке. Здесь выборка и достаточна, и представительна."},{"id":"q267","batch":6,"difficulty":1,"text":"Метеоролог говорит в эфире: «Давление резко падает, ветер усиливается, а спутник показывает грозовой фронт в ста километрах от города. Скорее всего, через пару часов будет гроза».","answer_id":"none","distractors":["affirming_consequent","post_hoc","hasty_generalization","false_authority"],"offer_none":true,"highlight":"Скорее всего, через пару часов будет гроза","explanation":"Метеоролог опирается на несколько независимых признаков и говорит «скорее всего», а не «точно». Это разумный вероятностный вывод.","nearest_distractor":"affirming_consequent","contrast":"Утверждение следствия — «если A, то B; B есть — значит, точно A». Метеоролог сводит вместе несколько признаков и делает осторожный вывод о вероятности."}],"easter":[{"id":"egg1","unlock_correct":100,"text":"Во дворе дядя Гена объясняет соседу дяде Игорю:\n\nГена: — По заказу мирового теневого правительства рептилоидов, повсюду понавтыкали 5G вышек. Из-за них пчёлы не могут найти дорогу к ульям, улетают за край земли и скоро все мы вымрем, так как некому будет опылять цветы. Ну, посуди сам: у нас во дворе поставили вышку, и всего через месяц голубей во дворе стало заметно меньше.\nИгорь: — Какие рептилоиды, какой край земли, ты о чём? Голубей могло стать меньше по сотне причин: зима пришла, бабушка с батоном переехала. «После» ещё не значит «из-за».\nГена: — А ты кто такой, орнитолог? Диплом сначала покажи.\nИгорь: — От моего диплома твой довод не станет ни лучше, ни хуже. И откуда ты, вообще, набрался этих идей про рептилоидов и край земли?\nГена: — Про край земли тебе лучше Юрия Лозу послушать — эх, и головастый! Не веришь? Пожалуйста, докажи, что вышки безопасны. Не можешь? Вот!\nИгорь: — Доказывает тот, кто утверждает. Если опровержения пока нет, это ещё не доказательство. И какой-то там певец не может быть авторитетом в вопросах астрофизики.\nГена: — Миллионы людей уже прозрели, один ты как овца.\nИгорь: — Если люди во что-то верят, это ничего не говорит о том, правда ли это на самом деле.\nГена: — Ага, значит, тебе плевать, что пчёлы и голуби вымирают! А потом и наша очередь придёт. Ты или с нами, или с рептилоидами! Ты просто не понимаешь очевидного, потому что уже зомбирован мировым правительством.\nИгорь: — Я не говорил, что мне плевать. И вариантов больше двух: можно любить пчёл и голубей и не бояться вышек.\nГена: — С тобой бесполезно разговаривать. Как и со всеми проплаченными либералами.","prompt":"Где ошибся Игорь?","options":[{"text":"Начал спорить с идиотом","correct":true},{"text":"Усомнился в реальности рептилоидов","note":"Сомневаться в рептилоидах можно. Главное — не вслух и не при Гене."},{"text":"Верит в шарообразность Земли, хотя сам в космос не летал","note":"Гена бы оценил. Но Игорю и без Земли хватило — его бы и за голубей зомбированным объявили."},{"text":"Не посмотрел то самое видео, где всё объясняют","note":"Посмотрел бы — нашлось бы второе. Их там бесконечно."},{"text":"Ловушка «ошибка в ошибке»: раз доводы кривые, вывод ложен","note":"Хорошая попытка, вы внимательны. Но Игорь нигде не сказал «значит, ты неправ» — он только указывал на ошибки. Тут к нему не придраться."},{"text":"Ошибки нет: Игорь безупречно разобрал каждый довод","note":"Разобрал безупречно, это правда. Только смысла у спора от этого не прибавилось.","last":true}],"explanation":"С логикой у Игоря всё чисто. Гена выдал заговор без доказательств, вывод о пчёлах из голубей, «после — значит из-за», переход на личность, певца в роли астрофизика, «докажи, что нет», «миллионы прозрели», соломенное чучело, ложную дилемму, а на закуску — «зомбирован» и «проплаченный». Игорь всё поймал и всё назвал правильно. А Гена ушёл с чувством победы — как голубь, который сыграл партию в шахматы: разбросал фигуры, нагадил на доску и улетел.\n\nОшибка Игоря в том, что он вообще сел за эту доску. Гена не искал истину — ему нужна была победа. Перед спором полезно спросить: «А что могло бы тебя переубедить?» Если честный ответ — «ничего», спор окончен, не начавшись. Подробнее — в разделе «Как спорить»."}]};
